/* --------------------------- COMPONENTE --------------------------- */

function CalendarioInstitucional() {
  const [mesActivo, setMesActivo] = useState(5); // junio, mes actual de referencia
  const [completados, setCompletados] = useState({});

  const mes = MESES[mesActivo];
  const colorMes = MES_COLORES[mesActivo];
  const fondoSuave = matizClaro(colorMes, 0.62);
  const fondoTinte = matizClaro(colorMes, 0.32);
  const textoClaro = esFondoOscuro(fondoTinte);
  const periodoEstilo = PERIODO_STYLE[mes.periodoTipo];
  const PeriodoIcon = periodoEstilo.Icon;
  const grilla = construirGrilla(mesActivo);

  const toggle = (idx) => {
    const k = `${mesActivo}-${idx}`;
    setCompletados((c) => ({ ...c, [k]: !c[k] }));
  };

  return (
    <div
      className="ci-root"
      style={{
        background: `radial-gradient(ellipse 120% 90% at 50% -10%, ${fondoSuave} 0%, ${fondoTinte} 70%)`,
      }}
    >
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,600;9..144,700&family=Source+Sans+3:wght@400;500;600&family=JetBrains+Mono:wght@500;700&display=swap');

        .ci-root {
          --bg: #121317;
          --cream: #FAF7F0;
          --cream-dim: #F1EAD9;
          --ink: #1F3A5F;
          --charcoal: #2B2B28;
          --line: #D9CBAA;
          --festivo: #C0392B;
          --gold: #C9A86A;
          --text-lo: #9C9486;
          font-family: 'Source Sans 3', sans-serif;
          color: var(--charcoal);
          min-height: 100%;
          padding: 28px 16px 48px;
          box-sizing: border-box;
          transition: background 0.5s ease;
        }
        .ci-root * { box-sizing: border-box; }

        .ci-header {
          max-width: 980px;
          margin: 0 auto 22px;
          display: flex;
          align-items: center;
          gap: 14px;
        }
        .ci-emblem {
          flex: 0 0 auto;
          width: 48px; height: 48px;
          border-radius: 50%;
          background: var(--gold);
          display: flex; align-items: center; justify-content: center;
          color: var(--ink);
          box-shadow: 0 0 0 3px rgba(201,168,106,0.3), 0 6px 14px -4px rgba(0,0,0,0.18);
        }
        .ci-eyebrow {
          font-size: 12px;
          letter-spacing: 0.14em;
          text-transform: uppercase;
          color: var(--ink);
          font-weight: 600;
          margin: 0 0 2px;
        }
        .ci-title {
          font-family: 'Fraunces', serif;
          font-weight: 700;
          font-size: clamp(26px, 4vw, 38px);
          color: var(--ink);
          margin: 0;
          line-height: 1.05;
        }

        .ci-tabs {
          max-width: 980px;
          margin: 0 auto;
          display: grid;
          grid-template-columns: repeat(6, 1fr);
          gap: 6px 8px;
        }
        @media (max-width: 640px) {
          .ci-tabs { grid-template-columns: repeat(4, 1fr); }
        }
        .ci-tab {
          position: relative;
          border: 1px solid var(--line);
          border-bottom-width: 4px;
          background: rgba(255,255,255,0.55);
          color: var(--ink);
          border-radius: 10px 10px 4px 4px;
          padding: 10px 4px 8px;
          font-family: 'JetBrains Mono', monospace;
          font-weight: 700;
          font-size: 12px;
          letter-spacing: 0.06em;
          cursor: pointer;
          transition: transform .15s ease, background .15s ease;
        }
        .ci-tab:hover { transform: translateY(-2px); background: rgba(255,255,255,0.85); }
        .ci-tab.active {
          color: var(--cream);
          transform: translateY(-4px);
          box-shadow: 0 10px 20px -8px rgba(0,0,0,0.25);
        }
        .ci-tab-count {
          position: absolute;
          top: -7px; right: -6px;
          background: #B23A2E;
          color: #fff;
          font-size: 10px;
          width: 17px; height: 17px;
          border-radius: 50%;
          display: flex; align-items: center; justify-content: center;
          font-family: 'JetBrains Mono', monospace;
        }

        .ci-panel {
          max-width: 980px;
          margin: 18px auto 0;
          background: #FFFFFF;
          color: var(--charcoal);
          border: 1px solid rgba(0,0,0,0.05);
          border-radius: 4px 14px 14px 14px;
          padding: 22px 22px 26px;
          box-shadow: 0 30px 60px -30px rgba(0,0,0,0.25), 0 2px 0 rgba(0,0,0,0.03);
        }
        @media (max-width: 640px) { .ci-panel { padding: 16px 14px 20px; } }

        .ci-mes-title {
          font-family: 'Fraunces', serif;
          font-size: 24px;
          font-weight: 600;
          color: var(--ink);
          margin: 0 0 4px;
        }

        .ci-periodo {
          display: flex;
          align-items: flex-start;
          gap: 8px;
          font-size: 12.5px;
          padding: 8px 12px;
          border-radius: 8px;
          margin: 10px 0 20px;
          border: 1px solid;
        }

        .ci-cols {
          display: grid;
          grid-template-columns: 1fr 1.4fr;
          gap: 22px;
        }
        .ci-col-agenda { order: 1; }
        .ci-col-calendario { order: 2; }
        @media (max-width: 760px) {
          .ci-cols { grid-template-columns: 1fr; }
          .ci-col-calendario { order: 1; }
          .ci-col-agenda { order: 2; }
        }

        .ci-col-label {
          font-family: 'JetBrains Mono', monospace;
          font-size: 11px;
          letter-spacing: 0.1em;
          text-transform: uppercase;
          color: #8a7c5c;
          margin: 0 0 12px;
          border-bottom: 1px solid var(--line);
          padding-bottom: 6px;
        }

        .ci-nota {
          display: flex;
          gap: 10px;
          padding: 9px 0;
          border-bottom: 1px dashed var(--line);
        }
        .ci-nota:last-child { border-bottom: none; }
        .ci-check {
          flex: 0 0 auto;
          width: 20px; height: 20px;
          border-radius: 5px;
          border: 1.5px solid var(--line);
          margin-top: 1px;
          display: flex; align-items: center; justify-content: center;
          cursor: pointer;
          background: var(--cream);
        }
        .ci-check.done { background: var(--ink); border-color: var(--ink); }
        .ci-dia {
          flex: 0 0 30px;
          font-family: 'JetBrains Mono', monospace;
          font-weight: 700;
          color: var(--ink);
          font-size: 14px;
          padding-top: 1px;
        }
        .ci-nota-body { flex: 1; min-width: 0; }
        .ci-nota-titulo {
          font-weight: 600;
          font-size: 14px;
          display: flex;
          align-items: center;
          gap: 6px;
          flex-wrap: wrap;
        }
        .ci-nota.done .ci-nota-titulo { text-decoration: line-through; opacity: 0.5; }
        .ci-tagpill {
          display: inline-flex;
          align-items: center;
          gap: 4px;
          font-size: 10px;
          font-weight: 600;
          padding: 2px 7px;
          border-radius: 999px;
          color: #fff;
          white-space: nowrap;
        }
        .ci-resp {
          font-size: 12px;
          color: #B23A2E;
          margin-top: 2px;
          font-weight: 600;
        }
        .ci-extra {
          font-size: 12px;
          color: #6b6456;
          font-style: italic;
          margin-top: 2px;
        }
        .ci-oficial {
          font-size: 10.5px;
          color: #8a7c5c;
          margin-top: 3px;
          display: flex;
          align-items: center;
          gap: 4px;
        }
        .ci-empty {
          font-size: 13px;
          color: #8a7c5c;
          font-style: italic;
          text-align: center;
          padding: 20px 0;
        }

        .ci-cal {
          display: grid;
          grid-template-columns: repeat(7, 1fr);
          gap: 4px;
        }
        .ci-cal-head {
          text-align: center;
          font-family: 'JetBrains Mono', monospace;
          font-size: 10px;
          font-weight: 700;
          color: #8a7c5c;
          padding-bottom: 4px;
        }
        .ci-cal-cell {
          position: relative;
          aspect-ratio: 1 / 1;
          border-radius: 7px;
          border: 1px solid var(--line);
          background: var(--cream-dim);
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          font-family: 'JetBrains Mono', monospace;
          font-size: 12px;
          color: var(--charcoal);
        }
        .ci-cal-cell.vacia { border: none; background: transparent; }
        .ci-cal-cell.festivo {
          background: #F6D7D0;
          border-color: var(--festivo);
          color: var(--festivo);
          font-weight: 700;
        }
        .ci-cal-cell.domingo { color: var(--festivo); font-weight: 700; }
        .ci-cal-dots {
          display: flex;
          gap: 2px;
          margin-top: 2px;
          flex-wrap: wrap;
          justify-content: center;
        }
        .ci-cal-dot { width: 5px; height: 5px; border-radius: 50%; }
        .ci-leyenda {
          display: flex;
          flex-wrap: wrap;
          gap: 8px 14px;
          margin-top: 14px;
          padding-top: 12px;
          border-top: 1px solid var(--line);
        }
        .ci-leyenda-item {
          display: flex;
          align-items: center;
          gap: 5px;
          font-size: 11px;
          color: #6b6456;
        }
        .ci-leyenda-swatch {
          width: 9px; height: 9px;
          border-radius: 50%;
          flex-shrink: 0;
        }
        .ci-leyenda-swatch.festivo {
          border-radius: 3px;
          background: #F6D7D0;
          border: 1.5px solid var(--festivo);
        }
        .ci-festivo-lista { margin-top: 12px; }
        .ci-festivo-item {
          font-size: 12px;
          display: flex;
          gap: 6px;
          align-items: baseline;
          padding: 3px 0;
        }
        .ci-festivo-item b {
          font-family: 'JetBrains Mono', monospace;
          color: var(--festivo);
        }
        .ci-festivo-item .mov {
          font-size: 10px;
          color: #8a7c5c;
          font-style: italic;
        }
      `}</style>

      <header className="ci-header">
        <div className="ci-emblem"><Shield size={24} /></div>
        <div>
          <p
            className="ci-eyebrow"
            style={{ color: textoClaro ? "#EBDDBB" : "#5B4630" }}
          >
            Institución Educativa La Amistad
          </p>
          <h1
            className="ci-title"
            style={{ color: textoClaro ? "#FAF7F0" : "#20242B" }}
          >
            Calendario Institucional 2026
          </h1>
        </div>
      </header>

      <nav className="ci-tabs">
        {MESES.map((m, i) => {
          const c = MES_COLORES[i];
          const activa = i === mesActivo;
          return (
            <button
              key={m.nombre}
              className={"ci-tab" + (activa ? " active" : "")}
              onClick={() => setMesActivo(i)}
              style={
                activa
                  ? { background: c, borderColor: c }
                  : { borderBottomColor: c }
              }
            >
              {m.nombre.slice(0, 3).toUpperCase()}
              {m.festivos.length > 0 && (
                <span className="ci-tab-count">{m.festivos.length}</span>
              )}
            </button>
          );
        })}
      </nav>

      <section className="ci-panel" style={{ borderTop: `4px solid ${colorMes}` }}>
        <h2 className="ci-mes-title" style={{ color: colorMes }}>{mes.nombre} 2026</h2>

        <div
          className="ci-periodo"
          style={{ background: periodoEstilo.bg, borderColor: periodoEstilo.border, color: periodoEstilo.border }}
        >
          <PeriodoIcon size={16} style={{ flexShrink: 0, marginTop: 1 }} />
          <span>{mes.periodo}</span>
        </div>

        <div className="ci-cols">
          {/* NOTAS — izquierda */}
          <div className="ci-col-agenda">
            <p className="ci-col-label">Agenda institucional</p>
            {mes.notas.length === 0 ? (
              <p className="ci-empty">
                Sin actividades registradas. {mes.periodoTipo === "receso" ? "Mes de receso y cierre de vacaciones." : "Mes de receso o periodo de planeación."}
              </p>
            ) : (
              mes.notas.map((n, idx) => {
                const key = `${mesActivo}-${idx}`;
                const done = !!completados[key];
                const tag = TAGS[n.tag];
                const TagIcon = tag.Icon;
                return (
                  <div className={"ci-nota" + (done ? " done" : "")} key={idx}>
                    <div
                      className={"ci-check" + (done ? " done" : "")}
                      onClick={() => toggle(idx)}
                    >
                      {done && <Check size={13} color="#FBF6EC" />}
                    </div>
                    <div className="ci-dia">{String(n.dia).padStart(2, "0")}</div>
                    <div className="ci-nota-body">
                      <div className="ci-nota-titulo">
                        {n.titulo}
                        <span className="ci-tagpill" style={{ background: tag.color }}>
                          <TagIcon size={10} /> {tag.label}
                        </span>
                      </div>
                      {n.responsables && (
                        <div className="ci-resp">Responsable(s): {n.responsables}</div>
                      )}
                      {n.extra && <div className="ci-extra">{n.extra}</div>}
                      {n.oficial && (
                        <div className="ci-oficial">
                          <Shield size={11} /> {n.oficial}
                        </div>
                      )}
                    </div>
                  </div>
                );
              })
            )}
          </div>

          {/* CALENDARIO REAL — centrado */}
          <div className="ci-col-calendario">
            <p className="ci-col-label" style={{ display: "flex", alignItems: "center", gap: 6 }}>
              <span
                style={{
                  width: 8,
                  height: 8,
                  borderRadius: "50%",
                  background: colorMes,
                  display: "inline-block",
                }}
              />
              Calendario de {mes.nombre}
            </p>

            <div className="ci-cal">
              {DIAS_SEMANA.map((d, i) => (
                <div
                  className="ci-cal-head"
                  key={i}
                  style={i === 6 ? { color: "var(--festivo)" } : undefined}
                >
                  {d}
                </div>
              ))}
              {grilla.map((d, idx) => {
                if (d === null) {
                  return <div className="ci-cal-cell vacia" key={idx} />;
                }
                const esDomingo = idx % 7 === 6;
                const festivo = mes.festivos.find((f) => f.dia === d);
                const notasDia = mes.notas.filter((n) => n.dia === d);
                const coloresUnicos = [
                  ...new Set(notasDia.map((n) => TAGS[n.tag].color)),
                ];
                return (
                  <div
                    className={
                      "ci-cal-cell" +
                      (festivo ? " festivo" : "") +
                      (esDomingo ? " domingo" : "")
                    }
                    key={idx}
                    title={
                      festivo
                        ? festivo.nombre
                        : notasDia.map((n) => n.titulo).join(" · ") || undefined
                    }
                  >
                    <span>{d}</span>
                    {coloresUnicos.length > 0 && (
                      <div className="ci-cal-dots">
                        {coloresUnicos.slice(0, 4).map((c, i) => (
                          <span
                            className="ci-cal-dot"
                            style={{ background: c }}
                            key={i}
                          />
                        ))}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>

            {mes.festivos.length > 0 && (
              <div className="ci-festivo-lista">
                {mes.festivos.map((f, idx) => (
                  <div className="ci-festivo-item" key={idx}>
                    <b>{String(f.dia).padStart(2, "0")}</b>
                    <span>{f.nombre}</span>
                    {f.movido && <span className="mov">· Ley Emiliani</span>}
                  </div>
                ))}
              </div>
            )}

            <div className="ci-leyenda">
              <div className="ci-leyenda-item">
                <span className="ci-leyenda-swatch festivo" />
                Domingo y festivos
              </div>
              {Object.values(TAGS).map((t) => (
                <div className="ci-leyenda-item" key={t.label}>
                  <span className="ci-leyenda-swatch" style={{ background: t.color }} />
                  {t.label}
                </div>
              ))}
            </div>
          </div>
        </div>
      </section>
    </div>
  );
}


// ═══════════════════════════════════════════════════════════════════════════════
// PLANEADOR DE CLASE — I.E. La Amistad · Inglés · 2026
// Componente íntegro del docente (paleta y estructura preservadas)
