// Convierte WEEKS_DATA (tema + 6 columnas Bloom) al formato semanas() del planeador
function semanasFromWeeksData(gradoIdx, mesIdx, fallbackN) {
  const arr = WEEKS_DATA[gradoIdx] && WEEKS_DATA[gradoIdx][mesIdx];
  if (!arr || arr.length === 0) return crearSemanas(fallbackN);
  return arr.map((w, i) => ({
    tema: w.badge ? `${w.tema} [${w.badge}]` : w.tema,
    fechaSemana: w.fecha || "",
    filas: [{
      nota: String(i + 1),
      cells: [w.recordar||"", w.comprender||"", w.aplicar||"", w.analizar||"", w.evaluar||"", w.crear||""]
    }]
  }));
}

