const loadPlayers_JR=()=>{try{return JSON.parse([])||[];}catch{return [];}};
const savePlayers_JR=p=>{_mem_JR=[...p];};
const upsertPlayer_JR=(players,name,delta)=>{
  const i=players.findIndex(p=>p.name===name);
  const blank={name,xp:0,coins:0,lives:5,completedMissions:[],
    answers:{}, // {Q1:{correct,competency,lvl,diff}, ...}
    lastSeen:new Date().toLocaleDateString("es-CO")};
  if(i===-1) return [...players,{...blank,...delta}];
  const u=[...players];
  u[i]={...u[i],...delta,lastSeen:new Date().toLocaleDateString("es-CO")};
  return u;
};

// ══════════════════════════════════════════════════════════
//  GLOBAL CSS_JR
// ══════════════════════════════════════════════════════════
const CSS_JR=`
.egJr-root *{box-sizing:border-box}
.egJr-root{min-height:100%;background:#F0F4FF}
@keyframes pop{0%{transform:scale(.5);opacity:0}70%{transform:scale(1.1)}100%{transform:scale(1);opacity:1}}
@keyframes slideUp{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:translateY(0)}}
@keyframes shake{0%,100%{transform:translateX(0)}25%{transform:translateX(-6px)}75%{transform:translateX(6px)}}
@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}}
@keyframes pulse{0%,100%{box-shadow:0 0 0 0 rgba(91,106,240,.4)}50%{box-shadow:0 0 0 12px rgba(91,106,240,0)}}
@keyframes fw{0%{transform:scale(0);opacity:1}100%{transform:scale(3);opacity:0}}
@keyframes spin{from{transform:rotate(0)}to{transform:rotate(360deg)}}
.pop{animation:pop .35s ease-out both}
.slideUp{animation:slideUp .35s ease-out both}
.shake{animation:shake .4s ease-out}
.float{animation:float 3s ease-in-out infinite}
.pulse{animation:pulse 2s infinite}
::-webkit-scrollbar{width:5px}
::-webkit-scrollbar-thumb{background:#CBD5E1;border-radius:4px}
`;

// ══════════════════════════════════════════════════════════
//  SMALL COMPONENTS
// ══════════════════════════════════════════════════════════
const Toast_JR=({msg,color,onDone})=>{
  useEffect(()=>{const t=setTimeout(onDone,2500);return()=>clearTimeout(t);},[]);
  return <div className="pop" style={{position:"fixed",top:18,left:"50%",transform:"translateX(-50%)",
    zIndex:9999,background:color||P_JR.primary,color:"#fff",padding:"9px 22px",borderRadius:50,
    fontWeight:800,fontSize:14,boxShadow:"0 4px 24px rgba(0,0,0,.15)"}}>{msg}</div>;
};

const Fireworks_JR=()=>{
  const sparks=Array.from({length:18},(_,i)=>({id:i,x:Math.random()*100,y:Math.random()*70,
    c:[P_JR.primary,P_JR.gold,P_JR.accent,P_JR.pink,"#EF4444"][i%5]}));
  return <div style={{position:"fixed",inset:0,pointerEvents:"none",zIndex:8888}}>
    {sparks.map(s=><div key={s.id} style={{position:"absolute",left:`${s.x}%`,top:`${s.y}%`,
      width:14,height:14,borderRadius:"50%",background:s.c,
      animation:`fw ${.6+Math.random()*.8}s ${Math.random()*.5}s ease-out forwards`}}/>)}
  </div>;
};

const XPBar_JR=({xp,max=1000})=>{
  const pct=Math.min((xp/max)*100,100);
  return <div style={{width:"100%"}}>
    <div style={{display:"flex",justifyContent:"space-between",fontSize:10,color:P_JR.muted,marginBottom:3}}>
      <span>⭐ XP</span><span>{xp}/{max}</span>
    </div>
    <div style={{height:9,borderRadius:20,background:"#E2E8F0",overflow:"hidden"}}>
      <div style={{height:"100%",width:`${pct}%`,borderRadius:20,
        background:`linear-gradient(90deg,${P_JR.primary},${P_JR.purple})`,transition:"width 1s ease"}}/>
    </div>
  </div>;
};

