// ══════════════════════════════════════════════════════════
//  WELCOME SCREEN
// ══════════════════════════════════════════════════════════
const WelcomeScreen_JR=({onStart})=>{
  const [name,setName]=useState("");
  const [avatar,setAvatar]=useState(AVATARS_JR[0]);
  const [showPicker,setShowPicker]=useState(false);
  const [err,setErr]=useState(false);
  const go=()=>{
    if(!name.trim()){setErr(true);return;}
    onStart(name.trim(),avatar);
  };
  return(
    <div style={{minHeight:"100%",background:P_JR.bg,display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
      <style>{CSS_JR}</style>
      {showPicker&&<AvatarPicker_JR current={avatar.id} onSelect={a=>{setAvatar(a);setShowPicker(false);}} onClose={()=>setShowPicker(false)}/>}
      <div className="pop" style={{background:P_JR.card,borderRadius:26,padding:32,maxWidth:400,width:"100%",
        boxShadow:"0 8px 48px rgba(91,106,240,.18)",textAlign:"center"}}>
        {/* Logo */}
        <div style={{display:"inline-flex",alignItems:"center",gap:6,background:`${P_JR.primary}12`,
          border:`1px solid ${P_JR.primary}33`,borderRadius:30,padding:"3px 12px",marginBottom:10,
          fontSize:11,color:P_JR.primary,fontWeight:700}}>
          🏫 I.E. La Amistad • Grado 9° • Mg. Anderson
        </div>
        <h1 style={{margin:"0 0 4px",fontWeight:900,fontSize:24,
          background:`linear-gradient(90deg,${P_JR.primary},${P_JR.purple},${P_JR.pink})`,
          WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent"}}>
          ⚔️ The English Guardians Jr.
        </h1>
        <p style={{color:P_JR.muted,fontSize:12,margin:"0 0 26px"}}>Pre A1 · A1 · A2 • Saber 11</p>

        {/* Avatar selector */}
        <div style={{marginBottom:20}}>
          <div style={{fontSize:11,fontWeight:700,color:P_JR.muted,marginBottom:10}}>Elige tu avatar</div>
          <div onClick={()=>setShowPicker(true)} className="float"
            style={{width:80,height:80,borderRadius:"50%",margin:"0 auto 8px",cursor:"pointer",
              background:`linear-gradient(135deg,${P_JR.primary},${P_JR.purple})`,
              display:"flex",alignItems:"center",justifyContent:"center",fontSize:40,
              boxShadow:`0 6px 24px ${P_JR.primary}44`,border:`3px solid ${P_JR.primary}`}}>
            {avatar.emoji}
          </div>
          <button onClick={()=>setShowPicker(true)} style={{background:"none",border:`1.5px solid ${P_JR.border}`,
            borderRadius:20,padding:"4px 14px",color:P_JR.muted,cursor:"pointer",fontSize:12,fontWeight:700}}>
            🎭 Cambiar avatar
          </button>
        </div>

        {/* Name input */}
        <div style={{marginBottom:20,textAlign:"left"}}>
          <div style={{fontSize:11,fontWeight:700,color:P_JR.muted,marginBottom:7}}>¿Cuál es tu nombre?</div>
          <input value={name} onChange={e=>{setName(e.target.value);setErr(false);}}
            onKeyDown={e=>e.key==="Enter"&&go()}
            placeholder="Escribe tu nombre aquí..."
            style={{width:"100%",padding:"13px 16px",borderRadius:14,
              border:`2px solid ${err?P_JR.warn:name?P_JR.primary:P_JR.border}`,
              fontSize:15,fontWeight:700,color:P_JR.text,outline:"none",
              background:err?"#FEF2F2":"#F8FAFF",transition:"border .2s"}}/>
          {err&&<p style={{color:P_JR.warn,fontSize:11,fontWeight:700,margin:"5px 0 0"}}>⚠️ Escribe tu nombre para continuar</p>}
        </div>

        <button onClick={go} style={{width:"100%",padding:"14px 0",borderRadius:16,border:"none",
          background:`linear-gradient(90deg,${P_JR.primary},${P_JR.purple})`,
          color:"#fff",fontWeight:900,fontSize:16,cursor:"pointer",
          boxShadow:`0 4px 20px ${P_JR.primary}44`}}>
          ¡Comenzar Aventura! ⚔️
        </button>

        <p style={{color:P_JR.muted,fontSize:10,marginTop:14}}>
          Si ya jugaste antes, escribe el mismo nombre para recuperar tu progreso.
        </p>
      </div>
    </div>
  );
};

