//  PLAYER HUD
// ══════════════════════════════════════════════════════════
const PlayerHUD_JR=({name,xp,coins,lives,avatar,onNameChange,onAvatarChange})=>{
  const [editing,setEditing]=useState(false);
  const [tmp,setTmp]=useState(name);
  const [showPicker,setShowPicker]=useState(false);
  const level=Math.floor(xp/150)+1;
  return <>
    {showPicker&&<AvatarPicker_JR current={avatar.id} onSelect={a=>{onAvatarChange(a);setShowPicker(false);}} onClose={()=>setShowPicker(false)}/>}
    <div className="slideUp" style={{background:P_JR.card,borderRadius:20,padding:"14px 18px",
      marginBottom:14,boxShadow:"0 2px 14px rgba(91,106,240,.10)",border:`1.5px solid ${P_JR.border}`}}>
    <div style={{display:"flex",alignItems:"center",gap:12,flexWrap:"wrap"}}>
      <div onClick={()=>setShowPicker(true)} className="float"
        style={{width:54,height:54,borderRadius:"50%",flexShrink:0,cursor:"pointer",
          background:`linear-gradient(135deg,${P_JR.primary},${P_JR.purple})`,
          display:"flex",alignItems:"center",justifyContent:"center",fontSize:28,
          boxShadow:`0 2px 10px ${P_JR.primary}33`,position:"relative"}}>
        {avatar.emoji}
        <div style={{position:"absolute",bottom:-2,right:-2,width:18,height:18,borderRadius:"50%",
          background:P_JR.gold,border:"2px solid #fff",display:"flex",alignItems:"center",
          justifyContent:"center",fontSize:9}}>✏️</div>
      </div>
      <div style={{flex:1,minWidth:150}}>
        <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:5}}>
          {editing
            ?<><input value={tmp} onChange={e=>setTmp(e.target.value)}
                onKeyDown={e=>e.key==="Enter"&&(onNameChange(tmp),setEditing(false))}
                autoFocus style={{background:"transparent",border:"none",borderBottom:`2px solid ${P_JR.primary}`,
                fontSize:15,fontWeight:800,color:P_JR.text,outline:"none",width:160}}/>
              <button onClick={()=>{onNameChange(tmp);setEditing(false);}}
                style={{background:P_JR.accent,color:"#fff",border:"none",borderRadius:8,padding:"2px 8px",cursor:"pointer",fontWeight:700}}>✓</button>
            </>
            :<><span style={{fontWeight:900,fontSize:16,color:P_JR.text}}>{name}</span>
              <button onClick={()=>setEditing(true)} style={{background:"none",border:"none",cursor:"pointer",fontSize:12}}>✏️</button>
            </>}
        </div>
        <XPBar_JR xp={xp}/>
      </div>
      <div style={{display:"flex",gap:8,flexShrink:0}}>
        {[{v:`Nv.${level}`,i:"⭐",c:P_JR.primary},{v:coins,i:"🪙",c:P_JR.gold}].map((s,i)=>(
          <div key={i} style={{textAlign:"center",background:`${s.c}12`,border:`1.5px solid ${s.c}33`,
            borderRadius:12,padding:"5px 10px",minWidth:55}}>
            <div style={{fontSize:14}}>{s.i}</div>
            <div style={{fontWeight:900,color:s.c,fontSize:13}}>{s.v}</div>
          </div>
        ))}
        <div style={{textAlign:"center",background:"#FEE2E222",border:"1.5px solid #EF444433",
          borderRadius:12,padding:"5px 10px",minWidth:55}}>
          {Array.from({length:5}).map((_,i)=>(
            <span key={i} style={{fontSize:11,opacity:i<lives?1:.2}}>❤️</span>
          ))}
          <div style={{fontSize:10,color:P_JR.muted,marginTop:1}}>Vidas</div>
        </div>
      </div>
    </div>
  </div>
  </>;
};

