const MissionGrid_JR=({completed,onSelect})=>{
  const mecLabel={quiz:"⚔️ Quiz Boss",wordmatch:"🔤 Word Match",dragdrop:"🎯 Drag & Sort"};
  return <div>
    <h2 style={{fontWeight:900,fontSize:21,color:P_JR.text,marginBottom:14,textAlign:"center"}}>
      🗺️ Elige tu Misión
    </h2>
    <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(280px,1fr))",gap:12}}>
      {MISSIONS_JR.map((m,i)=>{
        const done=completed.includes(m.id);
        const locked=i>0&&!completed.includes(MISSIONS_JR[i-1].id);
        return <div key={m.id} onClick={()=>!locked&&onSelect(m)}
          style={{background:locked?"#F8FAFC":m.bg,borderRadius:18,padding:16,
            cursor:locked?"not-allowed":"pointer",
            border:`2px solid ${done?"#10B981":locked?"#E2E8F0":m.color}44`,
            boxShadow:done?`0 4px 16px #10B98122`:`0 2px 10px ${m.color}18`,
            opacity:locked?.55:1,transition:"all .2s",position:"relative",overflow:"hidden"}}>
          <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:10}}>
            <div style={{fontSize:34}}>{m.emoji}</div>
            <div style={{flex:1}}>
              <div style={{fontWeight:900,color:P_JR.text,fontSize:14}}>{m.name}</div>
              <div style={{fontSize:11,color:m.color,fontWeight:700}}>{m.level}</div>
              <div style={{fontSize:10,color:P_JR.muted}}>{m.topic}</div>
            </div>
            {done&&<span style={{fontSize:20}}>✅</span>}
            {locked&&<span style={{fontSize:20}}>🔒</span>}
          </div>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:6}}>
            <span style={{fontSize:11,background:`${m.color}18`,color:m.color,
              padding:"2px 8px",borderRadius:20,fontWeight:700}}>{mecLabel[m.mechanic]}</span>
            <span style={{fontSize:11,color:P_JR.gold,fontWeight:800}}>🪙{m.coins} +{m.xp}XP</span>
          </div>
          <div style={{fontSize:11,color:P_JR.muted}}>🎁 {m.reward}</div>
        </div>;
      })}
    </div>
  </div>;
};

