// ══════════════════════════════════════════════════════════
//  READING PHASE
// ══════════════════════════════════════════════════════════
const ReadingPhase_JR=({m,onReady,onBack})=>{
  const [speaking,setSpeaking]=useState(false);
  const speak=(rate=0.9)=>{
    if(!("speechSynthesis" in window)) return;
    window.speechSynthesis.cancel();
    const u=new SpeechSynthesisUtterance(m.text);
    u.lang="en-US";u.rate=rate;
    u.onstart=()=>setSpeaking(true);u.onend=()=>setSpeaking(false);
    window.speechSynthesis.speak(u);
  };
  return <div className="slideUp">
    <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:14}}>
      <button onClick={onBack} style={{background:"none",border:"none",color:P_JR.primary,fontWeight:700,cursor:"pointer"}}>← Volver</button>
      <h3 style={{margin:0,fontWeight:900,color:P_JR.text,fontSize:17}}>{m.emoji} {m.name}</h3>
    </div>
    <div style={{background:m.bg,border:`1.5px solid ${m.color}33`,borderRadius:14,
      padding:"8px 14px",marginBottom:12,fontSize:12,color:m.color,fontWeight:700}}>
      🌎 Tema: {m.topic} • {m.level}
    </div>
    <div style={{background:P_JR.card,borderRadius:18,padding:20,marginBottom:14,
      border:`1.5px solid ${P_JR.border}`,boxShadow:"0 2px 10px rgba(0,0,0,.05)"}}>
      <p style={{color:P_JR.text,lineHeight:1.8,fontSize:15,margin:0}}>{m.text}</p>
    </div>
    <div style={{display:"flex",gap:8,marginBottom:18}}>
      <button onClick={()=>speak(0.9)} style={{flex:1,padding:"9px 0",borderRadius:13,border:"none",
        background:speaking?`${m.color}22`:m.bg,color:m.color,fontWeight:700,cursor:"pointer",fontSize:12}}>
        {speaking?"🔊 Reproduciendo...":"🔊 Escuchar"}
      </button>
      <button onClick={()=>speak(0.6)} style={{flex:1,padding:"9px 0",borderRadius:13,border:"none",
        background:"#F0F9FF",color:P_JR.sky,fontWeight:700,cursor:"pointer",fontSize:12}}>🐢 Lento</button>
      {speaking&&<button onClick={()=>window.speechSynthesis.cancel()}
        style={{padding:"9px 12px",borderRadius:13,border:"none",background:"#FEE2E2",color:P_JR.warn,cursor:"pointer",fontWeight:700}}>⏹</button>}
    </div>
    <button onClick={onReady} style={{width:"100%",padding:"13px 0",borderRadius:16,border:"none",
      background:`linear-gradient(90deg,${m.color},${P_JR.primary})`,
      color:"#fff",fontWeight:900,fontSize:15,cursor:"pointer"}}>
      {m.mechanic==="quiz"&&"¡Listo para el Quiz! 🧠"}
      {m.mechanic==="wordmatch"&&"¡Listo para Word Match! 🔤"}
      {m.mechanic==="dragdrop"&&"¡Listo para Clasificar! 🎯"}
    </button>
  </div>;
};

// ══════════════════════════════════════════════════════════
//  QUIZ MECHANIC
// ══════════════════════════════════════════════════════════
const QuizMechanic_JR=({m,onComplete,onRecordAnswer})=>{
  const qs=m.questions;
  const [idx,setIdx]=useState(0);
  const [sel,setSel]=useState(null);
  const [score,setScore]=useState(0);
  const [timeLeft,setTimeLeft]=useState(45);
  const [done,setDone]=useState(false);
  const ref=useRef(null);

  useEffect(()=>{
    if(done||sel!==null) return;
    ref.current=setInterval(()=>setTimeLeft(t=>{
      if(t<=1){clearInterval(ref.current);handleAns(-1);return 0;}
      return t-1;
    }),1000);
    return()=>clearInterval(ref.current);
  },[idx,sel,done]);

  const handleAns=i=>{
    if(sel!==null) return;
    clearInterval(ref.current);
    setSel(i);
    const ok=i===qs[idx].ans;
    if(ok) setScore(s=>s+1);
    onRecordAnswer(qs[idx].id,ok,qs[idx]);
  };
  const next=()=>{
    setSel(null);setTimeLeft(45);
    if(idx+1>=qs.length) setDone(true);
    else setIdx(i=>i+1);
  };
  if(done) return <ResultScreen_JR m={m} score={score} total={qs.length} onContinue={()=>onComplete(score,qs.length)}/>;
  const q=qs[idx];
  const tc=timeLeft>25?P_JR.accent:timeLeft>12?P_JR.gold:P_JR.warn;
  return <div className="slideUp">
    {/* Timer + progress */}
    <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:12}}>
      <div style={{flex:1,height:7,borderRadius:7,background:"#E2E8F0",overflow:"hidden"}}>
        {qs.map((_,i)=><div key={i} style={{position:"absolute"}}/>)}
        <div style={{height:"100%",width:`${((idx)/qs.length)*100}%`,background:m.color,borderRadius:7,transition:"width .5s"}}/>
      </div>
      <span style={{fontSize:11,fontWeight:800,color:P_JR.muted}}>{idx+1}/{qs.length}</span>
      <div style={{display:"flex",alignItems:"center",gap:4}}>
        <div style={{width:50,height:7,borderRadius:7,background:"#E2E8F0",overflow:"hidden"}}>
          <div style={{height:"100%",width:`${(timeLeft/45)*100}%`,background:tc,borderRadius:7,transition:"width 1s linear"}}/>
        </div>
        <span style={{fontSize:12,fontWeight:800,color:tc}}>{timeLeft}s</span>
      </div>
    </div>
    {/* Boss HP */}
    <div style={{background:m.bg,borderRadius:12,padding:"7px 12px",marginBottom:12,
      display:"flex",alignItems:"center",gap:8}}>
      <span style={{fontSize:20}}>{m.bossEmoji}</span>
      <div style={{flex:1,height:8,borderRadius:8,background:"#E2E8F0",overflow:"hidden"}}>
        <div style={{height:"100%",borderRadius:8,background:P_JR.warn,
          width:`${100-((idx/qs.length)*100)}%`,transition:"width .6s"}}/>
      </div>
      <span style={{fontSize:11,fontWeight:700,color:P_JR.warn}}>{qs.length-idx} HP</span>
    </div>
    {/* Question */}
    <div style={{background:P_JR.card,borderRadius:18,padding:18,marginBottom:12,
      border:`1.5px solid ${P_JR.border}`,boxShadow:"0 2px 10px rgba(0,0,0,.05)"}}>
      <div style={{display:"flex",gap:6,marginBottom:8,flexWrap:"wrap"}}>
        <span style={{fontSize:10,background:`${m.color}18`,color:m.color,padding:"2px 7px",borderRadius:20,fontWeight:700}}>{q.competency}</span>
        <span style={{fontSize:10,background:"#F1F5F9",color:P_JR.muted,padding:"2px 7px",borderRadius:20,fontWeight:700}}>{q.lvl}</span>
        <span style={{fontSize:10,background:"#F1F5F9",color:P_JR.muted,padding:"2px 7px",borderRadius:20,fontWeight:700}}>{"⭐".repeat(q.diff)}</span>
      </div>
      <p style={{fontWeight:800,color:P_JR.text,fontSize:15,marginBottom:14}}>{q.q}</p>
      <div style={{display:"flex",flexDirection:"column",gap:7}}>
        {q.opts.map((opt,i)=>{
          let bg=P_JR.bg,border=P_JR.border,col=P_JR.text;
          if(sel!==null){
            if(i===q.ans){bg="#DCFCE7";border="#10B981";col="#065F46";}
            else if(i===sel&&i!==q.ans){bg="#FEE2E2";border=P_JR.warn;col="#991B1B";}
          }
          return <button key={i} onClick={()=>handleAns(i)}
            style={{width:"100%",textAlign:"left",padding:"11px 13px",borderRadius:11,
              background:bg,border:`1.5px solid ${border}`,color:col,
              fontWeight:sel!==null&&i===q.ans?800:600,fontSize:14,cursor:"pointer",transition:"all .2s"}}>
            <span style={{color:m.color,fontWeight:800,marginRight:7}}>{["A","B","C","D"][i]}.</span>{opt}
          </button>;
        })}
      </div>
      {sel!==null&&<div className="slideUp" style={{marginTop:12,padding:"9px 13px",borderRadius:11,
        background:`${P_JR.sky}18`,border:`1.5px solid ${P_JR.sky}44`,color:P_JR.sky,fontSize:12,fontWeight:700}}>
        💡 {q.exp}
      </div>}
    </div>
    {sel!==null&&<button className="pop" onClick={next} style={{width:"100%",padding:"12px 0",borderRadius:14,
      border:"none",background:`linear-gradient(90deg,${m.color},${P_JR.primary})`,
      color:"#fff",fontWeight:900,fontSize:14,cursor:"pointer"}}>
      {idx+1>=qs.length?"🏆 Ver Resultados":"Siguiente →"}
    </button>}
  </div>;
};

// ══════════════════════════════════════════════════════════
//  WORD MATCH MECHANIC  (misión 2)
// ══════════════════════════════════════════════════════════
const WordMatchMechanic_JR=({m,onComplete,onRecordAnswer})=>{
  const pairs=WORDMATCH_PAIRS_JR;
  const [selWord,setSelWord]=useState(null);
  const [selMatch,setSelMatch]=useState(null);
  const [matched,setMatched]=useState({}); // {wordIdx: matchIdx}
  const [wrong,setWrong]=useState([]);
  const [done,setDone]=useState(false);
  const shuffledMatches=useRef([...pairs].sort(()=>Math.random()-.5)).current;

  useEffect(()=>{
    if(selWord!==null&&selMatch!==null){
      const correctMatch=pairs[selWord].match===shuffledMatches[selMatch].match;
      if(correctMatch){
        const nm={...matched,[selWord]:selMatch};
        setMatched(nm);
        // record answers for teacher panel
        m.questions.filter(q=>q.lvl==="A1").slice(0,1).forEach(q=>onRecordAnswer(q.id,true,q));
        if(Object.keys(nm).length===pairs.length) setTimeout(()=>setDone(true),600);
      } else {
        setWrong([selWord+"w",selMatch+"m"]);
        setTimeout(()=>setWrong([]),700);
        m.questions.filter(q=>q.lvl==="A1").slice(0,1).forEach(q=>onRecordAnswer(q.id,false,q));
      }
      setTimeout(()=>{setSelWord(null);setSelMatch(null);},300);
    }
  },[selWord,selMatch]);

  if(done){
    const score=Object.keys(matched).length;
    return <ResultScreen_JR m={m} score={score} total={pairs.length} onContinue={()=>onComplete(score,pairs.length)}/>;
  }
  return <div className="slideUp">
    <div style={{background:m.bg,borderRadius:14,padding:"10px 14px",marginBottom:16,
      display:"flex",justifyContent:"space-between",alignItems:"center"}}>
      <span style={{fontWeight:800,color:m.color,fontSize:14}}>🔤 Word Match — {m.name}</span>
      <span style={{fontSize:12,color:P_JR.muted}}>Conecta cada palabra con su definición</span>
    </div>
    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
      <div>
        <div style={{fontSize:11,fontWeight:700,color:P_JR.muted,marginBottom:8,textAlign:"center"}}>PALABRAS</div>
        {pairs.map((p,i)=>{
          const isMatched=matched[i]!==undefined;
          const isSel=selWord===i;
          const isWrong=wrong.includes(i+"w");
          return <div key={i} onClick={()=>!isMatched&&setSelWord(isSel?null:i)}
            className={isWrong?"shake":""}
            style={{padding:"11px 12px",borderRadius:12,marginBottom:8,cursor:isMatched?"default":"pointer",
              background:isMatched?"#DCFCE7":isSel?`${m.color}22`:"#fff",
              border:`2px solid ${isMatched?"#10B981":isSel?m.color:isWrong?P_JR.warn:P_JR.border}`,
              fontWeight:700,color:P_JR.text,fontSize:13,textAlign:"center",transition:"all .2s"}}>
            {isMatched?"✅ ":"🔵 "}{p.word}
          </div>;
        })}
      </div>
      <div>
        <div style={{fontSize:11,fontWeight:700,color:P_JR.muted,marginBottom:8,textAlign:"center"}}>DEFINICIONES</div>
        {shuffledMatches.map((p,i)=>{
          const isMatchedTo=Object.values(matched).includes(i);
          const isSel=selMatch===i;
          const isWrong=wrong.includes(i+"m");
          return <div key={i} onClick={()=>!isMatchedTo&&setSelMatch(isSel?null:i)}
            className={isWrong?"shake":""}
            style={{padding:"11px 12px",borderRadius:12,marginBottom:8,cursor:isMatchedTo?"default":"pointer",
              background:isMatchedTo?"#DCFCE7":isSel?`${m.color}22`:"#fff",
              border:`2px solid ${isMatchedTo?"#10B981":isSel?m.color:isWrong?P_JR.warn:P_JR.border}`,
              fontWeight:600,color:P_JR.text,fontSize:12,textAlign:"center",transition:"all .2s"}}>
            {isMatchedTo?"✅ ":""}{p.match}
          </div>;
        })}
      </div>
    </div>
    <div style={{marginTop:16,background:`${P_JR.sky}12`,borderRadius:12,padding:"10px 14px",
      fontSize:12,color:P_JR.sky,fontWeight:700}}>
      💡 Toca una palabra y luego su definición para conectarlas. Empareja todas para ganar.
    </div>
  </div>;
};

// ══════════════════════════════════════════════════════════
//  DRAG-DROP / TAP-SORT MECHANIC  (misión 3)
// ══════════════════════════════════════════════════════════
const DragDropMechanic_JR=({m,onComplete,onRecordAnswer})=>{
  const items=DRAGDROP_ITEMS_JR;
  const [placements,setPlacements]=useState({}); // {itemId: category}
  const [feedback,setFeedback]=useState({}); // {itemId: bool}
  const [selItem,setSelItem]=useState(null);
  const [done,setDone]=useState(false);

  const place=(cat)=>{
    if(!selItem) return;
    const correct=items.find(i=>i.id===selItem)?.category===cat;
    setPlacements(p=>({...p,[selItem]:cat}));
    setFeedback(f=>({...f,[selItem]:correct}));
    m.questions.slice(0,1).forEach(q=>onRecordAnswer(q.id,correct,q));
    setSelItem(null);
    const newP={...placements,[selItem]:cat};
    if(Object.keys(newP).length===items.length) setTimeout(()=>setDone(true),600);
  };

  if(done){
    const score=Object.values(feedback).filter(Boolean).length;
    return <ResultScreen_JR m={m} score={score} total={items.length} onContinue={()=>onComplete(score,items.length)}/>;
  }

  const unplaced=items.filter(i=>!placements[i.id]);
  return <div className="slideUp">
    <div style={{background:m.bg,borderRadius:14,padding:"10px 14px",marginBottom:14,
      display:"flex",justifyContent:"space-between",alignItems:"center"}}>
      <span style={{fontWeight:800,color:m.color,fontSize:14}}>🎯 Clasificar — {m.name}</span>
      <span style={{fontSize:12,color:P_JR.muted}}>{Object.keys(placements).length}/{items.length} clasificados</span>
    </div>
    {/* Unplaced items */}
    <div style={{marginBottom:14}}>
      <div style={{fontSize:11,fontWeight:700,color:P_JR.muted,marginBottom:8}}>Toca una palabra para seleccionarla:</div>
      <div style={{display:"flex",flexWrap:"wrap",gap:8}}>
        {unplaced.map(item=>(
          <div key={item.id} onClick={()=>setSelItem(selItem===item.id?null:item.id)}
            style={{padding:"9px 14px",borderRadius:20,cursor:"pointer",fontWeight:700,fontSize:13,
              background:selItem===item.id?`${m.color}22`:"#fff",
              border:`2px solid ${selItem===item.id?m.color:P_JR.border}`,
              color:P_JR.text,transition:"all .2s"}}>
            {selItem===item.id?"👉 ":""}{item.word}
          </div>
        ))}
        {!unplaced.length&&<div style={{color:P_JR.accent,fontWeight:700,fontSize:13}}>✅ ¡Todos clasificados!</div>}
      </div>
    </div>
    {/* Categories */}
    <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:10,marginBottom:14}}>
      {DD_CATEGORIES_JR.map(cat=>{
        const placed=items.filter(i=>placements[i.id]===cat);
        return <div key={cat} onClick={()=>place(cat)}
          style={{background:selItem?"#EEF0FF":"#F8FAFC",border:`2px dashed ${selItem?m.color:P_JR.border}`,
            borderRadius:14,padding:"10px 8px",cursor:selItem?"pointer":"default",
            transition:"all .2s",minHeight:100}}>
          <div style={{fontSize:11,fontWeight:800,color:m.color,marginBottom:8,textAlign:"center"}}>{cat}</div>
          {placed.map(i=>(
            <div key={i.id} style={{padding:"5px 8px",borderRadius:8,marginBottom:4,textAlign:"center",
              background:feedback[i.id]?"#DCFCE7":"#FEE2E2",
              border:`1.5px solid ${feedback[i.id]?"#10B981":P_JR.warn}`,
              fontSize:12,fontWeight:700}}>
              {feedback[i.id]?"✅":"❌"} {i.word}
            </div>
          ))}
        </div>;
      })}
    </div>
    {selItem&&<div style={{textAlign:"center",fontSize:13,color:m.color,fontWeight:700}}>
      👆 Ahora toca una categoría para colocar: <b>{items.find(i=>i.id===selItem)?.word}</b>
    </div>}
  </div>;
};

// ══════════════════════════════════════════════════════════
//  RESULT SCREEN
// ══════════════════════════════════════════════════════════
const ResultScreen_JR=({m,score,total,onContinue})=>{
  const pct=Math.round((score/total)*100);
  const win=pct>=60;
  const stars=pct>=85?3:pct>=60?2:1;
  return <div className="pop" style={{textAlign:"center",padding:"24px 0"}}>
    {win&&<Fireworks_JR/>}
    <div style={{fontSize:68,marginBottom:8,display:"inline-block"}}>{win?"🏆":"💪"}</div>
    <h2 style={{fontWeight:900,fontSize:24,color:P_JR.text,marginBottom:4}}>
      {pct>=85?"¡Boss derrotado! 🎉":pct>=60?"¡Buen trabajo! 👍":"¡Sigue intentando! 💪"}
    </h2>
    <div style={{display:"flex",justifyContent:"center",gap:4,marginBottom:16,fontSize:28}}>
      {Array.from({length:3}).map((_,i)=><span key={i} style={{opacity:i<stars?1:.2}}>⭐</span>)}
    </div>
    <div style={{background:m.bg,border:`2px solid ${m.color}44`,borderRadius:18,
      padding:18,display:"inline-block",minWidth:190,marginBottom:18}}>
      <div style={{fontSize:38,fontWeight:900,color:m.color}}>{score}/{total}</div>
      <div style={{color:P_JR.muted,fontSize:12,marginBottom:6}}>Respuestas correctas</div>
      {win&&<div style={{fontSize:12,fontWeight:700,color:P_JR.gold}}>🎁 {m.reward}</div>}
      <div style={{fontSize:12,fontWeight:700,color:P_JR.gold,marginTop:3}}>🪙 +{win?m.coins:Math.round(m.coins*.3)}</div>
      <div style={{fontSize:12,fontWeight:700,color:P_JR.primary,marginTop:2}}>+{win?m.xp:Math.round(m.xp*.4)} XP</div>
    </div>
    <div style={{display:"flex",gap:10,justifyContent:"center"}}>
      <button onClick={()=>onContinue(win)} style={{padding:"10px 26px",borderRadius:14,border:"none",
        background:`linear-gradient(90deg,${m.color},${P_JR.primary})`,color:"#fff",
        fontWeight:900,cursor:"pointer",fontSize:14}}>
        {win?"🏆 ¡Reclamar premio!":"🔄 Intentar de nuevo"}
      </button>
    </div>
  </div>;
};

// ══════════════════════════════════════════════════════════
//  MISSION DETAIL — orchestrates intro → reading → mechanic
// ══════════════════════════════════════════════════════════
const MissionDetail_JR=({mission,onBack,onEarnReward,onRecordAnswer})=>{
  const [view,setView]=useState("intro");
  const handleComplete=(score,total)=>{
    const win=score/total>=0.6;
    onEarnReward(mission,win);
  };
  if(view==="intro") return <BossIntro_JR m={mission} onStart={()=>setView("reading")} onBack={onBack}/>;
  if(view==="reading") return <ReadingPhase_JR m={mission} onReady={()=>setView("mechanic")} onBack={()=>setView("intro")}/>;
  if(view==="mechanic"){
    const props={m:mission,onComplete:handleComplete,onRecordAnswer};
    if(mission.mechanic==="quiz") return <QuizMechanic_JR {...props}/>;
    if(mission.mechanic==="wordmatch") return <WordMatchMechanic_JR {...props}/>;
    if(mission.mechanic==="dragdrop") return <DragDropMechanic_JR {...props}/>;
  }
  return null;
};

// ══════════════════════════════════════════════════════════
//  RANKING
