//  ANALYTICS — TEACHER PANEL
// ══════════════════════════════════════════════════════════

// Competency radar using SVG
const RadarChart_JR=({data,labels,color})=>{
  const n=data.length,cx=90,cy=90,r=70;
  const angle=(i)=>((i/n)*2*Math.PI)-Math.PI/2;
  const pts=data.map((v,i)=>{
    const a=angle(i);const rv=(v/100)*r;
    return [cx+rv*Math.cos(a),cy+rv*Math.sin(a)];
  });
  const poly=pts.map(p=>p.join(",")).join(" ");
  const labelPts=labels.map((_,i)=>{
    const a=angle(i);return [cx+(r+18)*Math.cos(a),cy+(r+18)*Math.sin(a)];
  });
  const gridLines=[20,40,60,80,100].map(pct=>{
    const gpts=Array.from({length:n},(_,i)=>{
      const a=angle(i);const rv=(pct/100)*r;
      return `${cx+rv*Math.cos(a)},${cy+rv*Math.sin(a)}`;
    });
    return gpts.join(" ");
  });
  return <svg viewBox="0 0 180 180" style={{width:"100%",maxWidth:200,display:"block",margin:"0 auto"}}>
    {gridLines.map((pts,i)=><polygon key={i} points={pts} fill="none" stroke="#E2E8F0" strokeWidth={1}/>)}
    {Array.from({length:n}).map((_,i)=>{
      const [x,y]=[cx+(r)*Math.cos(angle(i)),cy+(r)*Math.sin(angle(i))];
      return <line key={i} x1={cx} y1={cy} x2={x} y2={y} stroke="#E2E8F0" strokeWidth={1}/>;
    })}
    <polygon points={poly} fill={`${color}44`} stroke={color} strokeWidth={2}/>
    {labelPts.map(([x,y],i)=>(
      <text key={i} x={x} y={y} fontSize={7} textAnchor="middle" dominantBaseline="middle"
        fill={P_JR.text} fontWeight="700">{labels[i]}</text>
    ))}
  </svg>;
};

const AnalyticsPanel_JR=({players})=>{
  const allQ=MISSIONS_JR.flatMap(m=>m.questions);
  const competencies=["Comprensión literal","Competencia lingüística","Vocabulario contextual","Pragmática básica","Gramática básica"];

  // per-question stats
  const qStats=allQ.map(q=>{
    const attempts=players.map(p=>(p.answers||{})[q.id]).filter(Boolean);
    const correct=attempts.filter(a=>a.correct).length;
    const pct=attempts.length?Math.round((correct/attempts.length)*100):null;
    return {q,attempts:attempts.length,correct,pct};
  });

  // competency aggregates
  const compData=competencies.map(comp=>{
    const relevant=qStats.filter(s=>s.q.competency===comp&&s.pct!==null);
    if(!relevant.length) return 0;
    return Math.round(relevant.reduce((s,r)=>s+r.pct,0)/relevant.length);
  });

  // per-level stats
  const levelStats=["Pre A1","A1","A2"].map(lvl=>{
    const rel=qStats.filter(s=>s.q.lvl===lvl&&s.pct!==null);
    return {lvl,avg:rel.length?Math.round(rel.reduce((s,r)=>s+r.pct,0)/rel.length):null};
  });

  // risk alerts
  const alerts=players.filter(p=>{
    const ans=Object.values(p.answers||{});
    if(!ans.length) return false;
    const pct=Math.round((ans.filter(a=>a.correct).length/ans.length)*100);
    return pct<50;
  });

  // per-mission stats
  const missionStats=MISSIONS_JR.map(m=>{
    const mQ=m.questions;
    const mPct=mQ.map(q=>{
      const attempts=players.map(p=>(p.answers||{})[q.id]).filter(Boolean);
      const correct=attempts.filter(a=>a.correct).length;
      return attempts.length?Math.round((correct/attempts.length)*100):null;
    }).filter(v=>v!==null);
    const avg=mPct.length?Math.round(mPct.reduce((s,v)=>s+v,0)/mPct.length):null;
    const comp=players.filter(p=>(p.completedMissions||[]).includes(m.id)).length;
    return {m,avg,comp};
  });

  const weakQ=qStats.filter(s=>s.pct!==null&&s.pct<50).sort((a,b)=>a.pct-b.pct).slice(0,5);
  const strongQ=qStats.filter(s=>s.pct!==null&&s.pct>=70).slice(0,3);

  return <div className="slideUp">
    {/* Resumen general */}
    <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",gap:10,marginBottom:16}}>
      {[
        {v:players.length,l:"Estudiantes",c:P_JR.primary,i:"👥"},
        {v:`${qStats.filter(s=>s.pct!==null).length>0?
          Math.round(qStats.filter(s=>s.pct!==null).reduce((s,r)=>s+r.pct,0)/qStats.filter(s=>s.pct!==null).length):0}%`,
          l:"Aciertos global",c:P_JR.accent,i:"🎯"},
        {v:players.reduce((s,p)=>s+Object.values(p.answers||{}).filter(a=>a.correct).length,0),l:"Respuestas correctas",c:P_JR.accent,i:"✅"},
        {v:alerts.length,l:"Estudiantes en riesgo",c:P_JR.warn,i:"🚨"},
      ].map((s,i)=>(
        <div key={i} style={{background:P_JR.card,borderRadius:14,padding:"14px 16px",
          border:`1.5px solid ${s.c}33`,boxShadow:`0 2px 10px ${s.c}12`}}>
          <div style={{fontSize:20,marginBottom:4}}>{s.i}</div>
          <div style={{fontWeight:900,fontSize:22,color:s.c}}>{s.v}</div>
          <div style={{fontSize:11,color:P_JR.muted}}>{s.l}</div>
        </div>
      ))}
    </div>

    {/* Radar de competencias */}
    <div style={{background:P_JR.card,borderRadius:18,padding:18,marginBottom:14,border:`1.5px solid ${P_JR.border}`}}>
      <div style={{fontWeight:800,fontSize:14,color:P_JR.text,marginBottom:12}}>🧠 Radar de Competencias</div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12,alignItems:"center"}}>
        <RadarChart_JR data={compData} labels={["Literal","Lingüística","Vocab.","Pragmática","Gramática"]} color={P_JR.primary}/>
        <div>
          {competencies.map((c,i)=>(
            <div key={c} style={{marginBottom:10}}>
              <div style={{display:"flex",justifyContent:"space-between",marginBottom:3}}>
                <span style={{fontSize:11,fontWeight:700,color:P_JR.text}}>{c}</span>
                <span style={{fontSize:11,fontWeight:800,color:compData[i]>=70?P_JR.accent:compData[i]>=50?P_JR.gold:P_JR.warn}}>
                  {compData[i]}%
                </span>
              </div>
              <div style={{height:7,borderRadius:7,background:"#E2E8F0",overflow:"hidden"}}>
                <div style={{height:"100%",borderRadius:7,
                  background:compData[i]>=70?P_JR.accent:compData[i]>=50?P_JR.gold:P_JR.warn,
                  width:`${compData[i]||0}%`,transition:"width .8s"}}/>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>

    {/* Niveles A1/A2 */}
    <div style={{background:P_JR.card,borderRadius:18,padding:18,marginBottom:14,border:`1.5px solid ${P_JR.border}`}}>
      <div style={{fontWeight:800,fontSize:14,color:P_JR.text,marginBottom:12}}>📊 Desempeño por Nivel CEFR</div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:10}}>
        {levelStats.map(ls=>(
          <div key={ls.lvl} style={{textAlign:"center",padding:"14px 8px",borderRadius:14,
            background:ls.avg===null?"#F8FAFC":ls.avg>=70?`${P_JR.accent}12`:ls.avg>=50?`${P_JR.gold}12`:`${P_JR.warn}12`,
            border:`1.5px solid ${ls.avg===null?P_JR.border:ls.avg>=70?P_JR.accent:ls.avg>=50?P_JR.gold:P_JR.warn}44`}}>
            <div style={{fontSize:14,fontWeight:900,
              color:ls.avg===null?P_JR.muted:ls.avg>=70?P_JR.accent:ls.avg>=50?P_JR.gold:P_JR.warn}}>
              {ls.avg===null?"—":ls.avg+"%"}
            </div>
            <div style={{fontSize:10,fontWeight:700,color:P_JR.muted,marginTop:3}}>{ls.lvl}</div>
          </div>
        ))}
      </div>
    </div>

    {/* Por misión */}
    <div style={{background:P_JR.card,borderRadius:18,padding:18,marginBottom:14,border:`1.5px solid ${P_JR.border}`}}>
      <div style={{fontWeight:800,fontSize:14,color:P_JR.text,marginBottom:12}}>🗺️ Progreso por Misión</div>
      {missionStats.map(({m,avg,comp})=>(
        <div key={m.id} style={{marginBottom:12}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:4}}>
            <span style={{fontSize:13,fontWeight:700,color:P_JR.text}}>{m.emoji} {m.name}</span>
            <span style={{fontSize:11,color:P_JR.muted}}>{comp} completaron • {avg!==null?avg+"%":"sin datos"}</span>
          </div>
          <div style={{height:8,borderRadius:8,background:"#E2E8F0",overflow:"hidden"}}>
            <div style={{height:"100%",borderRadius:8,
              background:avg===null?P_JR.muted:avg>=70?P_JR.accent:avg>=50?P_JR.gold:P_JR.warn,
              width:`${avg||0}%`,transition:"width .8s"}}/>
          </div>
        </div>
      ))}
    </div>

    {/* Heatmap por pregunta */}
    <div style={{background:P_JR.card,borderRadius:18,padding:18,marginBottom:14,border:`1.5px solid ${P_JR.border}`}}>
      <div style={{fontWeight:800,fontSize:14,color:P_JR.text,marginBottom:12}}>🔥 Heatmap de Preguntas</div>
      <div style={{overflowX:"auto"}}>
        <div style={{display:"flex",gap:4,flexWrap:"wrap"}}>
          {qStats.map(s=>{
            const bg=s.pct===null?"#F1F5F9":s.pct>=80?"#DCFCE7":s.pct>=60?"#FEF9C3":s.pct>=40?"#FFEDD5":"#FEE2E2";
            const bc=s.pct===null?P_JR.border:s.pct>=80?"#10B981":s.pct>=60?P_JR.gold:s.pct>=40?"#F97316":P_JR.warn;
            return <div key={s.q.id} title={`${s.q.id}: ${s.pct===null?"sin datos":s.pct+"%"}`}
              style={{width:44,height:44,borderRadius:10,background:bg,border:`1.5px solid ${bc}`,
                display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:1}}>
              <span style={{fontSize:8,fontWeight:700,color:P_JR.muted}}>{s.q.id}</span>
              <span style={{fontSize:10,fontWeight:900,color:bc}}>{s.pct===null?"—":s.pct+"%"}</span>
            </div>;
          })}
        </div>
        <div style={{display:"flex",gap:8,marginTop:10,flexWrap:"wrap",fontSize:10,color:P_JR.muted}}>
          {[{c:"#DCFCE7",l:"≥80%"},{c:"#FEF9C3",l:"60-79%"},{c:"#FFEDD5",l:"40-59%"},{c:"#FEE2E2",l:"<40%"},{c:"#F1F5F9",l:"Sin datos"}].map(x=>(
            <div key={x.l} style={{display:"flex",alignItems:"center",gap:4}}>
              <div style={{width:12,height:12,borderRadius:3,background:x.c}}/>
              <span>{x.l}</span>
            </div>
          ))}
        </div>
      </div>
    </div>

    {/* Fortalezas y Debilidades */}
    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12,marginBottom:14}}>
      <div style={{background:"#ECFDF5",borderRadius:16,padding:14,border:"1.5px solid #10B98133"}}>
        <div style={{fontWeight:800,fontSize:13,color:P_JR.accent,marginBottom:10}}>✅ Fortalezas</div>
        {strongQ.length?strongQ.map(s=>(
          <div key={s.q.id} style={{fontSize:11,color:"#065F46",marginBottom:6}}>
            <span style={{fontWeight:700}}>{s.q.id}</span> — {s.q.competency}
            <div style={{fontSize:10,color:P_JR.muted}}>{s.pct}% aciertos</div>
          </div>
        )):<div style={{fontSize:12,color:P_JR.muted}}>Sin datos suficientes</div>}
      </div>
      <div style={{background:"#FEF2F2",borderRadius:16,padding:14,border:"1.5px solid #EF444433"}}>
        <div style={{fontWeight:800,fontSize:13,color:P_JR.warn,marginBottom:10}}>❌ Debilidades</div>
        {weakQ.length?weakQ.map(s=>(
          <div key={s.q.id} style={{fontSize:11,color:"#991B1B",marginBottom:6}}>
            <span style={{fontWeight:700}}>{s.q.id}</span> — {s.q.competency}
            <div style={{fontSize:10,color:P_JR.muted}}>{s.pct}% aciertos • {s.q.skill}</div>
          </div>
        )):<div style={{fontSize:12,color:P_JR.muted}}>Sin datos suficientes</div>}
      </div>
    </div>

    {/* Alertas pedagógicas */}
    {alerts.length>0&&<div style={{background:"#FEF2F2",border:`2px solid ${P_JR.warn}44`,borderRadius:16,padding:16,marginBottom:14}}>
      <div style={{fontWeight:800,fontSize:14,color:P_JR.warn,marginBottom:10}}>🚨 Alertas Pedagógicas — Estudiantes en Riesgo</div>
      {alerts.map(p=>{
        const ans=Object.values(p.answers||{});
        const pct=ans.length?Math.round((ans.filter(a=>a.correct).length/ans.length)*100):0;
        const weak=Object.entries(p.answers||{})
          .filter(([,a])=>!a.correct)
          .map(([id])=>id).join(", ");
        return <div key={p.name} style={{background:"#fff",borderRadius:12,padding:"10px 14px",marginBottom:8}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:4}}>
            <span style={{fontWeight:800,color:P_JR.text}}>{p.name}</span>
            <span style={{fontWeight:900,color:P_JR.warn,fontSize:14}}>{pct}% aciertos</span>
          </div>
          <div style={{fontSize:11,color:P_JR.muted}}>Errores en: {weak||"sin intentos"}</div>
        </div>;
      })}
    </div>}
  </div>;
};

