const QuestionTable_JR=()=>(
  <div className="slideUp">
    {MISSIONS_JR.map(m=>(
      <div key={m.id} style={{background:P_JR.card,borderRadius:18,padding:18,marginBottom:14,
        border:`1.5px solid ${m.color}33`}}>
        <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:14}}>
          <span style={{fontSize:26}}>{m.emoji}</span>
          <div>
            <div style={{fontWeight:900,color:P_JR.text,fontSize:15}}>{m.num}. {m.name}</div>
            <span style={{fontSize:11,background:`${m.color}18`,color:m.color,padding:"2px 8px",borderRadius:20,fontWeight:700}}>
              {m.level} • {m.topic}
            </span>
          </div>
        </div>
        <div style={{fontSize:13,color:P_JR.muted,fontStyle:"italic",marginBottom:12,
          background:m.bg,borderRadius:10,padding:"8px 12px"}}>{m.text}</div>
        <div style={{overflowX:"auto"}}>
          <table style={{width:"100%",borderCollapse:"collapse",fontSize:11}}>
            <thead>
              <tr style={{background:`${m.color}12`}}>
                {["ID","Pregunta","Respuesta","Competencia","Nivel","Tipo","Dif.","Habilidad evaluada"].map(h=>(
                  <th key={h} style={{padding:"7px 8px",textAlign:"left",fontWeight:700,
                    color:m.color,borderBottom:`1.5px solid ${P_JR.border}`,whiteSpace:"nowrap"}}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {m.questions.map((q,i)=>(
                <tr key={q.id} style={{background:i%2===0?"#fff":"#F8FAFC"}}>
                  <td style={{padding:"7px 8px",fontWeight:800,color:P_JR.primary,whiteSpace:"nowrap"}}>{q.id}</td>
                  <td style={{padding:"7px 8px",color:P_JR.text,maxWidth:200}}>{q.q}</td>
                  <td style={{padding:"7px 8px",fontWeight:700,color:P_JR.accent,whiteSpace:"nowrap"}}>
                    {["A","B","C","D"][q.ans]}. {q.opts[q.ans]}
                  </td>
                  <td style={{padding:"7px 8px",color:P_JR.purple,fontWeight:700,whiteSpace:"nowrap"}}>{q.competency}</td>
                  <td style={{padding:"7px 8px",whiteSpace:"nowrap"}}>
                    <span style={{background:`${m.color}18`,color:m.color,padding:"2px 6px",borderRadius:20,fontWeight:700,fontSize:10}}>{q.lvl}</span>
                  </td>
                  <td style={{padding:"7px 8px",color:P_JR.muted,whiteSpace:"nowrap"}}>{q.type}</td>
                  <td style={{padding:"7px 8px",textAlign:"center"}}>{"⭐".repeat(q.diff)}</td>
                  <td style={{padding:"7px 8px",color:P_JR.muted,fontSize:10,maxWidth:180}}>{q.skill}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    ))}
  </div>
);

