const StudentList_JR=({players,setPlayers})=>{
  const [sel,setSel]=useState(null);
  const [confirmDel,setConfirmDel]=useState(null);
  const [confirmClear,setConfirmClear]=useState(false);
  const sorted=[...players].sort((a,b)=>(b.xp||0)-(a.xp||0));
  const del=(name)=>{
    const u=players.filter(p=>p.name!==name);
    savePlayers_JR(u);setPlayers(u);setSel(null);
  };
  const clearAll=()=>{savePlayers_JR([]);setPlayers([]);setConfirmClear(false);};
  const allQ=MISSIONS_JR.flatMap(m=>m.questions);
  return <div className="slideUp">
    {!sorted.length&&<div style={{textAlign:"center",padding:48,color:P_JR.muted,background:P_JR.card,borderRadius:18}}>
      <div style={{fontSize:44,marginBottom:10}}>👥</div><p style={{fontWeight:700}}>Sin estudiantes registrados.</p>
    </div>}
    <div style={{display:"flex",flexDirection:"column",gap:8}}>
      {sorted.map((p,i)=>{
        const ans=Object.values(p.answers||{});
        const tc=ans.filter(a=>a.correct).length;
        const pct=ans.length?Math.round((tc/ans.length)*100):0;
        const lv=Math.floor((p.xp||0)/150)+1;
        const comp=(p.completedMissions||[]).length;
        const isOpen=sel===p.name;
        return <div key={p.name}>
          <div onClick={()=>setSel(isOpen?null:p.name)} style={{background:P_JR.card,borderRadius:14,
            padding:"12px 16px",cursor:"pointer",border:`1.5px solid ${isOpen?P_JR.primary:P_JR.border}`,
            boxShadow:isOpen?`0 2px 14px ${P_JR.primary}22`:"none",transition:"all .2s"}}>
            <div style={{display:"flex",alignItems:"center",gap:10}}>
              <div style={{width:38,height:38,borderRadius:"50%",flexShrink:0,
                background:`linear-gradient(135deg,${P_JR.primary},${P_JR.purple})`,
                display:"flex",alignItems:"center",justifyContent:"center",fontWeight:900,color:"#fff",fontSize:13}}>
                {i===0?"🥇":i===1?"🥈":i===2?"🥉":`#${i+1}`}
              </div>
              <div style={{flex:1,minWidth:0}}>
                <div style={{fontWeight:800,color:P_JR.text,fontSize:14}}>{p.name}</div>
                <div style={{fontSize:10,color:P_JR.muted}}>Nv.{lv} • {p.lastSeen}</div>
              </div>
              <div style={{textAlign:"right",flexShrink:0}}>
                <div style={{fontWeight:900,color:P_JR.gold,fontSize:13}}>⭐ {p.xp||0} XP</div>
                <div style={{fontSize:10,fontWeight:700,
                  color:pct>=70?P_JR.accent:pct>=50?P_JR.gold:P_JR.warn}}>{pct}% aciertos</div>
              </div>
              <span style={{color:P_JR.muted,fontSize:11}}>{isOpen?"▲":"▼"}</span>
            </div>
          </div>
          {isOpen&&<div className="slideUp" style={{background:"#F8FAFC",borderRadius:14,padding:14,
            marginTop:2,border:`1.5px solid ${P_JR.border}`}}>
            {/* Per-question answers */}
            <div style={{fontSize:11,fontWeight:700,color:P_JR.muted,marginBottom:10,textTransform:"uppercase"}}>Respuestas por Pregunta</div>
            <div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:14}}>
              {allQ.map(q=>{
                const a=(p.answers||{})[q.id];
                const bg=!a?"#F1F5F9":a.correct?"#DCFCE7":"#FEE2E2";
                const bc=!a?P_JR.border:a.correct?"#10B981":P_JR.warn;
                return <div key={q.id} title={q.q}
                  style={{padding:"4px 8px",borderRadius:8,background:bg,border:`1.5px solid ${bc}`,
                    fontSize:10,fontWeight:700,color:bc}}>
                  {q.id} {!a?"—":a.correct?"✅":"❌"}
                </div>;
              })}
            </div>
            {/* Stats */}
            <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8,marginBottom:12}}>
              {[{v:tc,l:"Correctas",c:P_JR.accent},{v:ans.length-tc,l:"Erradas",c:P_JR.warn},{v:p.coins||0,l:"🪙 Monedas",c:P_JR.gold}].map((s,j)=>(
                <div key={j} style={{textAlign:"center",background:`${s.c}12`,border:`1.5px solid ${s.c}33`,borderRadius:11,padding:9}}>
                  <div style={{fontWeight:900,color:s.c,fontSize:15}}>{s.v}</div>
                  <div style={{fontSize:10,color:P_JR.muted}}>{s.l}</div>
                </div>
              ))}
            </div>
            {/* Misiones */}
            <div style={{marginBottom:12}}>
              {MISSIONS_JR.map(m=>{
                const done=(p.completedMissions||[]).includes(m.id);
                const mAns=m.questions.map(q=>(p.answers||{})[q.id]).filter(Boolean);
                const mPct=mAns.length?Math.round((mAns.filter(a=>a.correct).length/mAns.length)*100):null;
                return <div key={m.id} style={{display:"flex",justifyContent:"space-between",alignItems:"center",
                  padding:"5px 0",borderBottom:`1px solid ${P_JR.border}`}}>
                  <span style={{fontSize:12,fontWeight:600}}>{m.emoji} {m.name}</span>
                  <span style={{fontSize:11,fontWeight:700,
                    color:done?P_JR.accent:mPct!==null?(mPct>=60?P_JR.accent:P_JR.warn):P_JR.muted}}>
                    {done?"✅ Completada":mPct!==null?`${mPct}%`:"Sin intentos"}
                  </span>
                </div>;
              })}
            </div>
            {confirmDel===p.name
              ?<div style={{background:"#FEF2F2",border:`1.5px solid ${P_JR.warn}44`,borderRadius:11,padding:10}}>
                <p style={{color:P_JR.warn,fontWeight:700,fontSize:12,margin:"0 0 8px",textAlign:"center"}}>¿Eliminar a {p.name}?</p>
                <div style={{display:"flex",gap:7}}>
                  <button onClick={()=>setConfirmDel(null)} style={{flex:1,padding:"7px 0",borderRadius:9,border:`1.5px solid ${P_JR.border}`,background:"#fff",color:P_JR.muted,fontWeight:700,cursor:"pointer",fontSize:12}}>Cancelar</button>
                  <button onClick={()=>{del(p.name);setConfirmDel(null);}} style={{flex:1,padding:"7px 0",borderRadius:9,border:"none",background:P_JR.warn,color:"#fff",fontWeight:700,cursor:"pointer",fontSize:12}}>Eliminar</button>
                </div>
              </div>
              :<button onClick={()=>setConfirmDel(p.name)} style={{width:"100%",padding:"8px 0",borderRadius:11,
                border:`1.5px solid ${P_JR.warn}44`,background:"#FEF2F2",color:P_JR.warn,
                fontWeight:700,cursor:"pointer",fontSize:12}}>🗑️ Eliminar registro</button>}
          </div>}
        </div>;
      })}
    </div>
    {players.length>0&&<div style={{marginTop:14}}>
      {!confirmClear
        ?<button onClick={()=>setConfirmClear(true)} style={{width:"100%",padding:"9px 0",borderRadius:13,
          border:`1.5px solid ${P_JR.warn}44`,background:"#FEF2F2",color:P_JR.warn,fontWeight:700,cursor:"pointer",fontSize:12}}>
          🗑️ Limpiar todos los registros
        </button>
        :<div style={{background:"#FEF2F2",border:`2px solid ${P_JR.warn}66`,borderRadius:14,padding:14}}>
          <p style={{color:P_JR.warn,fontWeight:800,textAlign:"center",fontSize:13,margin:"0 0 10px"}}>⚠️ ¿Eliminar TODOS? No se puede deshacer.</p>
          <div style={{display:"flex",gap:8}}>
            <button onClick={()=>setConfirmClear(false)} style={{flex:1,padding:"9px 0",borderRadius:11,border:`1.5px solid ${P_JR.border}`,background:"#fff",color:P_JR.muted,fontWeight:700,cursor:"pointer",fontSize:12}}>Cancelar</button>
            <button onClick={clearAll} style={{flex:1,padding:"9px 0",borderRadius:11,border:"none",background:P_JR.warn,color:"#fff",fontWeight:800,cursor:"pointer",fontSize:12}}>Sí, eliminar</button>
          </div>
        </div>}
    </div>}
  </div>;
};

