// ══════════════════════════════════════════════════════════
const ExportPanel_JR=({players})=>{
  const [done,setDone]=useState(null);
  const go=(type)=>{
    if(type==="csv") exportCSV_JR(players);
    else if(type==="json") exportJSON_JR(players);
    else printReport_JR(players);
    setDone(type);setTimeout(()=>setDone(null),2500);
  };
  return <div className="slideUp">
    <div style={{background:P_JR.card,borderRadius:18,padding:18,marginBottom:14,border:`1.5px solid ${P_JR.border}`}}>
      <div style={{fontWeight:800,fontSize:14,color:P_JR.text,marginBottom:4}}>📤 Exportar datos</div>
      <p style={{fontSize:12,color:P_JR.muted,margin:"0 0 16px"}}>{players.length} estudiantes registrados.</p>
      {[
        {id:"csv",  icon:"📊", label:"Excel / CSV",   sub:"Abre directo en Excel",         c:P_JR.accent},
        {id:"json", icon:"🗂️", label:"JSON completo",  sub:"Backup de todos los datos",     c:P_JR.primary},
        {id:"print",icon:"🖨️", label:"Imprimir PDF",   sub:"Reporte visual con preguntas",  c:P_JR.purple},
      ].map(o=>(
        <button key={o.id} onClick={()=>go(o.id)} style={{display:"flex",alignItems:"center",gap:12,
          width:"100%",padding:"13px 16px",borderRadius:14,marginBottom:9,
          border:`2px solid ${done===o.id?"transparent":o.c+"44"}`,
          background:done===o.id?o.c:`${o.c}0D`,
          color:done===o.id?"#fff":P_JR.text,cursor:"pointer",textAlign:"left",transition:"all .25s"}}>
          <span style={{fontSize:26}}>{o.icon}</span>
          <div style={{flex:1}}>
            <div style={{fontWeight:800,fontSize:13}}>{o.label}</div>
            <div style={{fontSize:11,opacity:.7}}>{o.sub}</div>
          </div>
          {done===o.id?<span style={{fontWeight:800}}>✅ ¡Listo!</span>:<span style={{color:o.c,fontSize:16}}>↓</span>}
        </button>
      ))}
    </div>
    {/* Quick table preview */}
    <div style={{background:P_JR.card,borderRadius:18,padding:18,border:`1.5px solid ${P_JR.border}`}}>
      <div style={{fontWeight:800,fontSize:13,color:P_JR.text,marginBottom:10}}>👀 Vista previa</div>
      <div style={{overflowX:"auto"}}>
        <table style={{width:"100%",borderCollapse:"collapse",fontSize:11}}>
          <thead><tr style={{background:`${P_JR.primary}12`}}>
            {["Estudiante","Nv","XP","🪙","% Aciertos","Misiones","Última Sesión"].map(h=>(
              <th key={h} style={{padding:"6px 9px",textAlign:"left",fontWeight:700,color:P_JR.primary,borderBottom:`1.5px solid ${P_JR.border}`}}>{h}</th>
            ))}
          </tr></thead>
          <tbody>
            {[...players].sort((a,b)=>(b.xp||0)-(a.xp||0)).map((p,i)=>{
              const ans=Object.values(p.answers||{});
              const pct=ans.length?Math.round((ans.filter(a=>a.correct).length/ans.length)*100):0;
              return <tr key={p.name} style={{background:i%2?"#fff":"#F8FAFC"}}>
                <td style={{padding:"6px 9px",fontWeight:700}}>{p.name}</td>
                <td style={{padding:"6px 9px",color:P_JR.primary,fontWeight:700}}>{Math.floor((p.xp||0)/150)+1}</td>
                <td style={{padding:"6px 9px",color:P_JR.primary,fontWeight:700}}>{p.xp||0}</td>
                <td style={{padding:"6px 9px",color:P_JR.gold,fontWeight:700}}>{p.coins||0}</td>
                <td style={{padding:"6px 9px",fontWeight:700,color:pct>=70?P_JR.accent:pct>=50?P_JR.gold:P_JR.warn}}>{pct}%</td>
                <td style={{padding:"6px 9px"}}>{(p.completedMissions||[]).length}/4</td>
                <td style={{padding:"6px 9px",color:P_JR.muted,fontSize:10}}>{p.lastSeen||"—"}</td>
              </tr>;
            })}
            {!players.length&&<tr><td colSpan={7} style={{padding:24,textAlign:"center",color:P_JR.muted}}>Sin datos</td></tr>}
          </tbody>
        </table>
      </div>
    </div>
  </div>;
};

