// ══════════════════════════════════════════════════════════
//  MAIN APP
// ══════════════════════════════════════════════════════════
function EnglishGuardiansJr(){
  const [started,setStarted]=useState(false);
  const [playerName,setPlayerName]=useState("Estudiante");
  const [avatar,setAvatar]=useState(AVATARS_JR[0]);
  const [xp,setXp]=useState(0);
  const [coins,setCoins]=useState(0);
  const [lives,setLives]=useState(5);
  const [completed,setCompleted]=useState([]);
  const [answers,setAnswers]=useState({});
  const [screen,setScreen]=useState("home");
  const [selMission,setSelMission]=useState(null);
  const [showLogin,setShowLogin]=useState(false);
  const [showAdmin,setShowAdmin]=useState(false);
  const [toast,setToast]=useState(null);

  const showToast=(msg,color)=>setToast({msg,color});

  // Called from WelcomeScreen_JR on first entry
  const handleStart=(name,av)=>{
    setPlayerName(name);
    setAvatar(av);
    // Load existing progress if player exists
    const players=loadPlayers_JR();
    const ex=players.find(p=>p.name===name);
    if(ex){
      setXp(ex.xp||0);setCoins(ex.coins||0);setLives(ex.lives||5);
      setCompleted(ex.completedMissions||[]);setAnswers(ex.answers||{});
      if(ex.avatarId) setAvatar(AVATARS_JR.find(a=>a.id===ex.avatarId)||av);
    }
    setStarted(true);
  };

  const handleNameChange=(name)=>{
    setPlayerName(name);
    const players=loadPlayers_JR();
    const ex=players.find(p=>p.name===name);
    if(ex){
      setXp(ex.xp||0);setCoins(ex.coins||0);setLives(ex.lives||5);
      setCompleted(ex.completedMissions||[]);setAnswers(ex.answers||{});
    }
  };

  const handleAvatarChange=(av)=>{
    setAvatar(av);
    // persist
    const players=loadPlayers_JR();
    const updated=upsertPlayer_JR(players,playerName,{xp,coins,lives,completedMissions:completed,answers,avatarId:av.id});
    savePlayers_JR(updated);
    showToast(`${av.emoji} ¡Avatar cambiado!`,P_JR.purple);
  };

  const handleRecordAnswer=(qId,correct,qData)=>{
    const newAns={...answers,[qId]:{correct,competency:qData.competency,lvl:qData.lvl,diff:qData.diff}};
    setAnswers(newAns);
    const players=loadPlayers_JR();
    const updated=upsertPlayer_JR(players,playerName,{xp,coins,lives,completedMissions:completed,answers:newAns,avatarId:avatar.id});
    savePlayers_JR(updated);
  };

  const handleEarnReward=(mission,win)=>{
    const eXp=win?mission.xp:Math.round(mission.xp*.4);
    const eCoins=win?mission.coins:Math.round(mission.coins*.3);
    const nXp=xp+eXp, nCoins=coins+eCoins;
    const nComp=win&&!completed.includes(mission.id)?[...completed,mission.id]:completed;
    setXp(nXp);setCoins(nCoins);
    if(win) setCompleted(nComp);
    else setLives(l=>Math.max(0,l-1));
    const players=loadPlayers_JR();
    const updated=upsertPlayer_JR(players,playerName,{xp:nXp,coins:nCoins,lives,completedMissions:nComp,answers,avatarId:avatar.id});
    savePlayers_JR(updated);
    showToast(win?`🏆 +${eXp} XP • 🪙 +${eCoins}`:`💪 +${eXp} XP de práctica`, win?P_JR.accent:P_JR.gold);
    setScreen("home");setSelMission(null);
  };

  // Show welcome screen before anything
  if(!started) return <WelcomeScreen_JR onStart={handleStart}/>;

  if(showAdmin) return <AdminPanel_JR onClose={()=>setShowAdmin(false)}/>;

  return <div style={{minHeight:"100%",background:P_JR.bg}}>
    <style>{CSS_JR}</style>
    {showLogin&&<AdminLogin_JR onSuccess={()=>{setShowLogin(false);setShowAdmin(true);}} onCancel={()=>setShowLogin(false)}/>}
    {toast&&<Toast_JR msg={toast.msg} color={toast.color} onDone={()=>setToast(null)}/>}

    <div style={{maxWidth:720,margin:"0 auto",padding:"14px 13px"}}>
      {/* Header */}
      <div style={{textAlign:"center",marginBottom:16}}>
        <div style={{display:"inline-flex",alignItems:"center",gap:6,background:`${P_JR.primary}12`,
          border:`1px solid ${P_JR.primary}33`,borderRadius:30,padding:"3px 12px",marginBottom:7,
          fontSize:11,color:P_JR.primary,fontWeight:700}}>
          🏫 I.E. La Amistad • Grado 9° • Mg. Anderson
        </div>
        <h1 style={{margin:0,fontWeight:900,fontSize:26,
          background:`linear-gradient(90deg,${P_JR.primary},${P_JR.purple},${P_JR.pink})`,
          WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",lineHeight:1.2}}>
          ⚔️ The English Guardians Jr.
        </h1>
        <p style={{color:P_JR.muted,fontSize:12,margin:"3px 0 0"}}>Preparación Saber 11 • Pre A1 · A1 · A2</p>
      </div>

      {/* Nav */}
      <div style={{display:"flex",gap:7,marginBottom:14}}>
        {[{id:"home",l:"🏠 Misiones"},{id:"ranking",l:"🏆 Ranking"}].map(t=>(
          <button key={t.id} onClick={()=>{setScreen(t.id);setSelMission(null);}}
            style={{padding:"8px 16px",borderRadius:13,border:"none",
              background:screen===t.id?P_JR.primary:"#fff",color:screen===t.id?"#fff":P_JR.muted,
              fontWeight:700,cursor:"pointer",fontSize:12,
              boxShadow:screen===t.id?`0 2px 10px ${P_JR.primary}44`:"0 1px 4px rgba(0,0,0,.06)"}}>
            {t.l}
          </button>
        ))}
        <button onClick={()=>setShowLogin(true)} style={{marginLeft:"auto",padding:"8px 11px",borderRadius:13,
          border:"none",background:"#fff",color:"#94A3B8",cursor:"pointer",fontSize:11,
          boxShadow:"0 1px 4px rgba(0,0,0,.06)"}}>🔐</button>
      </div>

      {/* HUD */}
      {screen!=="mission"&&<PlayerHUD_JR name={playerName} xp={xp} coins={coins} lives={lives}
        avatar={avatar} onNameChange={handleNameChange} onAvatarChange={handleAvatarChange}/>}

      {/* Screens */}
      {screen==="home"&&!selMission&&(
        <MissionGrid_JR completed={completed} onSelect={m=>{setSelMission(m);setScreen("mission");}}/>
      )}
      {screen==="ranking"&&<RankingPanel_JR playerName={playerName}/>}
      {screen==="mission"&&selMission&&(
        <MissionDetail_JR mission={selMission}
          onBack={()=>{setScreen("home");setSelMission(null);}}
          onEarnReward={handleEarnReward}
          onRecordAnswer={handleRecordAnswer}/>
      )}

      <div style={{textAlign:"center",marginTop:28,color:"#CBD5E1",fontSize:10}}>
        English Guardians Jr. © 2026 • Grado 9° • I.E. La Amistad
      </div>
    </div>
  </div>;
}

