// ─── IN-MEMORY STORE ──────────────────────────────────────────────────────────
let _storeV3 = [];
const loadPlayers = () => _storeV3;
const savePlayers = (p) => { _storeV3 = p; };

function upsertPlayer(name, patch) {
  const players = loadPlayers();
  const idx = players.findIndex(p => p.name === name);
  const blank = { name, xp:0, coins:0, lives:5, avatar:"🐼", missionsDone:[], answers:{}, lastSeen:new Date().toLocaleDateString("es-CO") };
  if (idx === -1) { savePlayers([...players, { ...blank, ...patch }]); return; }
  const arr = [...players]; arr[idx] = { ...arr[idx], ...patch, lastSeen:new Date().toLocaleDateString("es-CO") };
  savePlayers(arr);
}

function recordAnswer(playerName, qid, correct) {
  const players = loadPlayers();
  const idx = players.findIndex(p => p.name === playerName);
  if (idx === -1) return;
  const arr = [...players];
  if (!arr[idx].answers[qid]) arr[idx].answers[qid] = [];
  arr[idx].answers[qid].push({ correct, ts: Date.now() });
  savePlayers(arr);
}

