// ─── GLOBAL STYLES ────────────────────────────────────────────────────────────
const G = `
@keyframes floatUp{0%{transform:translateY(0) rotate(0);opacity:.15}100%{transform:translateY(-55px) rotate(360deg);opacity:0}}
@keyframes slideIn{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:translateY(0)}}
@keyframes bounceIn{0%{transform:scale(.3);opacity:0}60%{transform:scale(1.1)}100%{transform:scale(1);opacity:1}}
@keyframes glow{0%,100%{box-shadow:0 0 8px currentColor}50%{box-shadow:0 0 26px currentColor,0 0 50px currentColor}}
@keyframes shake{0%,100%{transform:translateX(0)}25%{transform:translateX(-5px)}75%{transform:translateX(5px)}}
@keyframes starPop{0%{transform:scale(0) rotate(-30deg)}70%{transform:scale(1.3)}100%{transform:scale(1)}}
@keyframes heartBeat{0%,100%{transform:scale(1)}14%{transform:scale(1.25)}28%{transform:scale(1)}42%{transform:scale(1.25)}70%{transform:scale(1)}}
.si{animation:slideIn .32s ease-out forwards}
.bi{animation:bounceIn .42s cubic-bezier(.175,.885,.32,1.275) forwards}
.btn{cursor:pointer;border:none;outline:none;transition:transform .15s ease,filter .15s ease}
.btn:hover{transform:scale(1.05) translateY(-1px);filter:brightness(1.15)}
.btn:active{transform:scale(.97)}
.card{border-radius:18px;transition:transform .2s ease}
.card:hover{transform:translateY(-4px)}
::-webkit-scrollbar{width:5px}::-webkit-scrollbar-thumb{background:#7C3AED;border-radius:3px}
`;

const shuffle = arr => [...arr].sort(() => Math.random() - .5);

// ─── PARTICLES ────────────────────────────────────────────────────────────────
function GameParticles() {
  const pts = Array.from({length:18},(_,i)=>({id:i,x:Math.random()*100,y:Math.random()*100,s:Math.random()*4+2,d:Math.random()*8+6,delay:Math.random()*4,c:["#00C896","#7C3AED","#F59E0B","#EC4899","#00E5FF"][i%5]}));
  return (
    <div style={{position:"fixed",inset:0,overflow:"hidden",pointerEvents:"none",zIndex:0}}>
      {pts.map(p=><div key={p.id} style={{position:"absolute",left:`${p.x}%`,top:`${p.y}%`,width:p.s,height:p.s,borderRadius:"50%",background:p.c,animation:`floatUp ${p.d}s ${p.delay}s ease-in-out infinite`}}/>)}
    </div>
  );
}

// ─── TOAST ────────────────────────────────────────────────────────────────────
function Toast({msg,color,onDone}){
  useEffect(()=>{const t=setTimeout(onDone,2200);return()=>clearTimeout(t);},[]);
  return <div className="bi" style={{position:"fixed",top:16,right:16,zIndex:999,padding:"11px 17px",borderRadius:13,background:`${color}22`,border:`2px solid ${color}66`,color,fontWeight:800,fontSize:14,boxShadow:`0 0 16px ${color}44`,pointerEvents:"none"}}>{msg}</div>;
}

// ─── LIVES BAR ────────────────────────────────────────────────────────────────
function LivesBar({lives}){
  return(
    <div style={{display:"flex",gap:4,justifyContent:"center",marginBottom:8}}>
      {Array.from({length:5}).map((_,i)=>(
        <span key={i} style={{fontSize:20,filter:i<lives?"none":"grayscale(1) opacity(.3)",animation:i<lives?"heartBeat 2s infinite":"none",animationDelay:`${i*.15}s`}}>❤️</span>
      ))}
    </div>
  );
}

// ─── HUD ──────────────────────────────────────────────────────────────────────
function HUD({name,xp,coins,lives,avatar,onEditName,onChangeAvatar}){
  const [editing,setEditing]=useState(false);
  const [tmp,setTmp]=useState(name);
  const [showAv,setShowAv]=useState(false);
  const maxXp=2000; const pct=Math.min((xp/maxXp)*100,100);
  const level=Math.floor(xp/200)+1;
  const cur=AVATARS.find(a=>a.emoji===avatar)||AVATARS[0];
  return(
    <div className="si" style={{background:"linear-gradient(135deg,#0d0521,#1a0a3d,#0a1a0d)",border:"2px solid #7C3AED44",borderRadius:20,padding:"12px 14px",marginBottom:14,boxShadow:"0 0 26px #7C3AED22"}}>
      <div style={{display:"flex",alignItems:"center",gap:12,flexWrap:"wrap"}}>
        <div style={{position:"relative",flexShrink:0}}>
          <div onClick={()=>setShowAv(s=>!s)} style={{width:54,height:54,borderRadius:"50%",background:`linear-gradient(135deg,${cur.color}66,#1a0a3d)`,border:`3px solid ${cur.color}`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:27,boxShadow:`0 0 16px ${cur.color}66`,cursor:"pointer",animation:"glow 3s ease-in-out infinite"}}>
            {cur.emoji}
          </div>
          <div style={{position:"absolute",bottom:-4,right:-4,background:"#F59E0B",color:"#000",borderRadius:"50%",width:20,height:20,display:"flex",alignItems:"center",justifyContent:"center",fontSize:10,fontWeight:900}}>{level}</div>
        </div>
        <div style={{flex:1,minWidth:130}}>
          <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:2}}>
            {editing?(
              <><input value={tmp} onChange={e=>setTmp(e.target.value)} onKeyDown={e=>e.key==="Enter"&&(onEditName(tmp),setEditing(false))} autoFocus style={{background:"transparent",border:"none",borderBottom:`2px solid ${cur.color}`,color:"#fff",fontSize:15,fontWeight:800,outline:"none",width:130}}/><button onClick={()=>{onEditName(tmp);setEditing(false);}} style={{color:"#00C896",background:"none",border:"none",cursor:"pointer",fontSize:16}}>✓</button></>
            ):(
              <><span style={{color:"#fff",fontWeight:800,fontSize:15}}>{name}</span><button onClick={()=>setEditing(true)} style={{background:"none",border:"none",cursor:"pointer",fontSize:12}}>✏️</button></>
            )}
          </div>
          <button onClick={()=>setShowAv(s=>!s)} style={{background:"none",border:"none",cursor:"pointer",padding:0,marginBottom:4,display:"flex",alignItems:"center",gap:4}}>
            <span style={{fontSize:11,color:cur.color,fontWeight:700}}>{cur.emoji} {cur.name}</span>
            <span style={{fontSize:10,color:"#4a4a6a"}}>· change</span>
          </button>
          <div style={{background:"#1a0a3d",borderRadius:6,overflow:"hidden",height:8}}>
            <div style={{height:"100%",background:`linear-gradient(90deg,${cur.color},#00C896)`,width:`${pct}%`,transition:"width 1s ease",boxShadow:`0 0 6px ${cur.color}`}}/>
          </div>
          <div style={{color:"#7C3AED",fontSize:10,marginTop:2}}>{xp}/{maxXp} XP</div>
        </div>
        <div style={{display:"flex",gap:6}}>
          {[{icon:"🪙",val:coins,c:"#F59E0B"},{icon:"❤️",val:lives,c:"#EC4899"}].map((s,i)=>(
            <div key={i} style={{background:`${s.c}11`,border:`1px solid ${s.c}33`,borderRadius:10,padding:"5px 8px",textAlign:"center",minWidth:44}}>
              <div style={{fontSize:15}}>{s.icon}</div>
              <div style={{color:s.c,fontWeight:900,fontSize:13}}>{s.val}</div>
            </div>
          ))}
        </div>
      </div>
      {showAv&&(
        <div className="si" style={{marginTop:10,paddingTop:10,borderTop:"1px solid #7C3AED33"}}>
          <p style={{color:"#a78bfa",fontSize:11,fontWeight:700,marginBottom:6}}>🎨 Choose your Guardian:</p>
          <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
            {AVATARS.map(a=>(
              <button key={a.emoji} className="btn" onClick={()=>{onChangeAvatar(a.emoji);setShowAv(false);}} title={a.name}
                style={{width:40,height:40,borderRadius:10,fontSize:21,background:avatar===a.emoji?`${a.color}33`:"#1a0a3d",border:`2px solid ${avatar===a.emoji?a.color:"#7C3AED22"}`,boxShadow:avatar===a.emoji?`0 0 10px ${a.color}88`:"none"}}>
                {a.emoji}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

// ─── WORLD MAP ────────────────────────────────────────────────────────────────
function WorldMap({missions,completed,onSelect}){
  return(
    <div className="si">
      <div style={{textAlign:"center",marginBottom:12}}>
        <p style={{color:"#a78bfa",fontSize:13,fontStyle:"italic",marginBottom:3}}>"The Silence Shadow stole the Crystal Words..."</p>
        <p style={{color:"#F59E0B",fontWeight:800,fontSize:12}}>⚔️ Recover them in each zone!</p>
      </div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
        {missions.map((m,i)=>{
          const done=completed.includes(m.id);
          const unlocked=i===0||completed.includes(missions[i-1].id);
          return(
            <div key={m.id} className={unlocked?"card":""} onClick={()=>unlocked&&onSelect(m)}
              style={{background:unlocked?`linear-gradient(135deg,#0d0521,${m.color}22)`:"#0a0a14",border:`2px solid ${done?"#00C896":unlocked?m.color:"#2a2a3a"}66`,borderRadius:18,padding:14,cursor:unlocked?"pointer":"not-allowed",position:"relative",overflow:"hidden",opacity:unlocked?1:.45,boxShadow:done?`0 0 16px #00C89633`:unlocked?`0 0 10px ${m.color}22`:"none"}}>
              <div style={{position:"absolute",top:7,right:9,fontSize:10,color:done?"#00C896":unlocked?"#a78bfa":"#4a4a6a",fontWeight:800}}>{done?"✅ DONE":unlocked?`Lv.${m.level}`:"🔒 LOCKED"}</div>
              <div style={{fontSize:34,marginBottom:4,filter:unlocked?`drop-shadow(0 0 8px ${m.color})`:"grayscale(1)"}}>{unlocked?m.emoji:"🔒"}</div>
              <h3 style={{color:unlocked?"#fff":"#4a4a6a",fontWeight:900,fontSize:13,marginBottom:2}}>{m.name}</h3>
              <div style={{fontSize:10,color:"#a78bfa",marginBottom:5}}>Zone {i+1}</div>
              {unlocked?(
                <span style={{fontSize:10,padding:"2px 7px",borderRadius:20,background:`${m.color}33`,color:m.color,border:`1px solid ${m.color}44`}}>+{m.xp} XP</span>
              ):(
                <p style={{fontSize:10,color:"#4a4a6a"}}>Complete previous zone</p>
              )}
              <div style={{position:"absolute",bottom:-6,right:-6,fontSize:32,opacity:.07}}>{m.emoji}</div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── FLASHCARDS ───────────────────────────────────────────────────────────────
function FlashCards({vocab,color,onDone}){
  const [idx,setIdx]=useState(0);
  const [flipped,setFlipped]=useState(false);
  const [done,setDone]=useState(false);
  const next=()=>{ setFlipped(false); setTimeout(()=>{ if(idx+1>=vocab.length) setDone(true); else setIdx(i=>i+1); },180); };
  if(done) return(
    <div className="bi" style={{textAlign:"center",padding:24}}>
      <div style={{fontSize:54,marginBottom:8}}>🎉</div>
      <p style={{color:"#00C896",fontWeight:900,fontSize:20,marginBottom:16}}>Vocabulary learned!</p>
      <button className="btn" onClick={onDone} style={{background:`linear-gradient(90deg,${color},#7C3AED)`,color:"#000",borderRadius:13,padding:"12px 26px",fontWeight:900,fontSize:16}}>Let's Play! 🎮</button>
    </div>
  );
  const card=vocab[idx];
  return(
    <div className="si" style={{textAlign:"center"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12}}>
        <span style={{color:"#a78bfa",fontSize:12}}>Card {idx+1}/{vocab.length}</span>
        <div style={{display:"flex",gap:3}}>{vocab.map((_,i)=><div key={i} style={{width:13,height:5,borderRadius:3,background:i<=idx?color:"#1a0a3d"}}/>)}</div>
        <button className="btn" onClick={onDone} style={{background:"none",border:"none",color:"#4a4a6a",fontSize:11,cursor:"pointer"}}>Skip →</button>
      </div>
      <div onClick={()=>setFlipped(f=>!f)} style={{background:`linear-gradient(135deg,#0d0521,${color}22)`,border:`2px solid ${color}66`,borderRadius:22,padding:"26px 18px",marginBottom:13,cursor:"pointer",minHeight:175,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",boxShadow:`0 0 18px ${color}33`}}>
        <div style={{fontSize:68,marginBottom:9}}>{card.emoji}</div>
        {!flipped?(
          <><div style={{fontSize:24,fontWeight:900,color:"#fff",marginBottom:5}}>{card.word}</div><p style={{color:"#a78bfa",fontSize:12}}>Tap to see definition</p></>
        ):(
          <><div style={{fontSize:20,fontWeight:900,color,marginBottom:5}}>{card.word}</div><p style={{color:"#e2e8f0",fontSize:14,maxWidth:250}}>{card.def}</p></>
        )}
      </div>
      <div style={{display:"flex",gap:9,justifyContent:"center"}}>
        <button className="btn" onClick={()=>{setFlipped(false);setIdx(i=>Math.max(0,i-1));}} style={{padding:"9px 18px",borderRadius:11,background:"#1a0a3d",border:"1px solid #7C3AED33",color:"#a78bfa",fontWeight:700,fontSize:13}}>← Back</button>
        <button className="btn" onClick={next} style={{padding:"9px 22px",borderRadius:11,background:color,color:"#000",fontWeight:900,fontSize:14}}>Next →</button>
      </div>
    </div>
  );
}

// ─── PARAGRAPH READER ─────────────────────────────────────────────────────────
function ParagraphReader({paragraphs,color,onDone}){
  const [idx,setIdx]=useState(0);
  const [speaking,setSpeaking]=useState(false);
  const speak=(text)=>{
    if("speechSynthesis" in window){
      window.speechSynthesis.cancel();
      const u=new SpeechSynthesisUtterance(text);u.lang="en-US";u.rate=.85;
      u.onstart=()=>setSpeaking(true);u.onend=()=>setSpeaking(false);
      window.speechSynthesis.speak(u);
    }
  };
  const p=paragraphs[idx]; const isLast=idx===paragraphs.length-1;
  return(
    <div className="si">
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:9}}>
        <span style={{color:"#a78bfa",fontSize:12,fontWeight:700}}>📖 Paragraph {idx+1} of {paragraphs.length}</span>
        <div style={{display:"flex",gap:3}}>{paragraphs.map((_,i)=><div key={i} style={{width:15,height:5,borderRadius:3,background:i<=idx?color:"#1a0a3d"}}/>)}</div>
      </div>
      <div style={{background:"#0d0521",border:`2px solid ${color}44`,borderRadius:15,padding:16,marginBottom:11}}>
        <p style={{color:"#e2e8f0",fontSize:15,lineHeight:1.75}}>{p.text}</p>
      </div>
      <div style={{marginBottom:11}}>
        <p style={{color:"#F59E0B",fontSize:11,fontWeight:700,marginBottom:5}}>🔑 Key words:</p>
        <div style={{display:"flex",flexWrap:"wrap",gap:5}}>
          {p.key.map(k=><span key={k} style={{padding:"3px 9px",borderRadius:20,background:"#F59E0B22",border:"1px solid #F59E0B44",color:"#F59E0B",fontSize:11,fontWeight:700}}>{k}</span>)}
        </div>
      </div>
      <div style={{display:"flex",gap:7,marginBottom:13}}>
        <button className="btn" onClick={()=>speak(p.text)} style={{flex:1,padding:8,borderRadius:10,background:"#7C3AED22",border:"1px solid #7C3AED44",color:"#a78bfa",fontWeight:700,fontSize:12}}>{speaking?"🔊 Playing...":"🔊 Listen"}</button>
        <button className="btn" onClick={()=>{const u=new SpeechSynthesisUtterance(p.text);u.lang="en-US";u.rate=.6;window.speechSynthesis.speak(u);}} style={{padding:"8px 13px",borderRadius:10,background:"#00C89611",border:"1px solid #00C89633",color:"#00C896",fontWeight:700,fontSize:12}}>🐢</button>
        {speaking&&<button className="btn" onClick={()=>window.speechSynthesis.cancel()} style={{padding:"8px 11px",borderRadius:10,background:"#FF444411",border:"1px solid #FF444433",color:"#FF4444"}}>⏹</button>}
      </div>
      <button className="btn" onClick={()=>{window.speechSynthesis.cancel();isLast?onDone():setIdx(i=>i+1);}}
        style={{width:"100%",padding:13,borderRadius:13,background:`linear-gradient(90deg,${color},#7C3AED)`,color:"#000",fontWeight:900,fontSize:15}}>
        {isLast?"I've read it all! ✅":"Next Paragraph →"}
      </button>
    </div>
  );
}

// ─── FULL TEXT READER ─────────────────────────────────────────────────────────
function FullTextReader({mission,onDone}){
  const [speaking,setSpeaking]=useState(false);
  const fullText=mission.paragraphs.map(p=>p.text).join(" ");
  const speak=()=>{
    if("speechSynthesis" in window){
      window.speechSynthesis.cancel();
      const u=new SpeechSynthesisUtterance(fullText);u.lang="en-US";u.rate=.85;
      u.onstart=()=>setSpeaking(true);u.onend=()=>setSpeaking(false);
      window.speechSynthesis.speak(u);
    }
  };
  return(
    <div className="si">
      <h3 style={{color:"#fff",fontWeight:900,fontSize:17,textAlign:"center",marginBottom:4}}>📖 Full Text</h3>
      <p style={{color:"#a78bfa",fontSize:12,textAlign:"center",marginBottom:11}}>Read it carefully before the Premiación 🏆</p>
      <div style={{background:"#0d0521",border:`2px solid ${mission.color}44`,borderRadius:15,padding:16,marginBottom:11,maxHeight:260,overflowY:"auto"}}>
        {mission.paragraphs.map((p,i)=>(
          <div key={i} style={{marginBottom:13}}>
            <span style={{color:mission.color,fontSize:11,fontWeight:800,marginBottom:3,display:"block"}}>¶ {i+1}</span>
            <p style={{color:"#e2e8f0",fontSize:14,lineHeight:1.75}}>{p.text}</p>
          </div>
        ))}
      </div>
      <div style={{display:"flex",gap:7,marginBottom:11}}>
        <button className="btn" onClick={speak} style={{flex:1,padding:8,borderRadius:10,background:"#7C3AED22",border:"1px solid #7C3AED44",color:"#a78bfa",fontWeight:700,fontSize:12}}>{speaking?"🔊 Playing...":"🔊 Listen full text"}</button>
        {speaking&&<button className="btn" onClick={()=>window.speechSynthesis.cancel()} style={{padding:"8px 11px",borderRadius:10,background:"#FF444411",border:"1px solid #FF444433",color:"#FF4444"}}>⏹</button>}
      </div>
      <button className="btn" onClick={()=>{window.speechSynthesis.cancel();onDone();}}
        style={{width:"100%",padding:13,borderRadius:13,background:`linear-gradient(90deg,${mission.color},#7C3AED)`,color:"#000",fontWeight:900,fontSize:16}}>
        🏆 Ready for Premiación!
      </button>
    </div>
  );
}

// ─── GAME: HANGMAN ────────────────────────────────────────────────────────────
function Hangman({words,color,onWin,onBack}){
  const pool=words.filter(w=>w.length>3&&!w.includes(" ")).map(w=>w.toUpperCase());
  const [word]=useState(()=>pool[Math.floor(Math.random()*pool.length)]||"DOCTOR");
  const [guessed,setGuessed]=useState(new Set());
  const [wrong,setWrong]=useState(0);
  const maxW=6;
  const LETTERS="ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");
  const won=word.split("").every(c=>guessed.has(c));
  const lost=wrong>=maxW;
  const guess=l=>{ if(guessed.has(l)||won||lost) return; const ng=new Set(guessed);ng.add(l);setGuessed(ng);if(!word.includes(l))setWrong(w=>w+1); };
  return(
    <div className="si">
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:13}}>
        <button className="btn" onClick={onBack} style={{background:"#7C3AED22",border:"1px solid #7C3AED44",color:"#a78bfa",borderRadius:9,padding:"5px 11px",fontSize:12}}>← Back</button>
        <h3 style={{color:"#fff",fontWeight:800,flex:1,fontSize:16}}>🎯 Hangman</h3>
        <span style={{color:"#FF4444",fontWeight:800,fontSize:13}}>💀 {wrong}/{maxW}</span>
      </div>
      <div style={{background:"#0d0521",borderRadius:15,padding:17,marginBottom:13,border:`2px solid ${color}33`,textAlign:"center"}}>
        <div style={{fontSize:50,marginBottom:7}}>{lost?"😵":won?"🎉":["😊","🤔","😰","😨","😱","💀"][wrong]}</div>
        <div style={{display:"flex",justifyContent:"center",gap:5,marginBottom:9}}>
          {word.split("").map((c,i)=><div key={i} style={{width:27,height:34,borderBottom:`3px solid ${color}`,display:"flex",alignItems:"flex-end",justifyContent:"center",fontSize:17,fontWeight:900,color:"#fff",paddingBottom:2}}>{guessed.has(c)?c:" "}</div>)}
        </div>
        <div style={{display:"flex",gap:3,justifyContent:"center"}}>{Array.from({length:maxW}).map((_,i)=><span key={i} style={{fontSize:13,opacity:i<wrong?1:.2}}>💀</span>)}</div>
      </div>
      {!won&&!lost&&(
        <div style={{display:"flex",flexWrap:"wrap",gap:4,justifyContent:"center",marginBottom:11}}>
          {LETTERS.map(l=>(
            <button key={l} className="btn" onClick={()=>guess(l)} style={{width:29,height:29,borderRadius:7,fontWeight:800,fontSize:11,background:guessed.has(l)?(word.includes(l)?"#00C89622":"#FF444422"):"#1a0a3d",border:`2px solid ${guessed.has(l)?(word.includes(l)?"#00C896":"#FF4444"):"#7C3AED33"}`,color:guessed.has(l)?(word.includes(l)?"#00C896":"#FF4444"):"#a78bfa",opacity:guessed.has(l)?.6:1}}>{l}</button>
          ))}
        </div>
      )}
      {won&&<div className="bi" style={{textAlign:"center"}}><p style={{color:"#00C896",fontSize:19,fontWeight:900,marginBottom:9}}>🎉 Perfect! +80 🪙</p><button className="btn" onClick={onWin} style={{background:"#00C896",color:"#000",borderRadius:12,padding:"10px 22px",fontWeight:900,fontSize:14}}>Claim!</button></div>}
      {lost&&<div className="bi" style={{textAlign:"center"}}><p style={{color:"#FF4444",fontSize:17,fontWeight:800,marginBottom:4}}>Word was: <span style={{color:"#F59E0B"}}>{word}</span></p><button className="btn" onClick={onWin} style={{background:"#7C3AED",color:"#fff",borderRadius:12,padding:"9px 20px",fontWeight:800}}>Continue</button></div>}
    </div>
  );
}

// ─── GAME: WORD MATCH ─────────────────────────────────────────────────────────
function WordMatch({vocab,color,onWin,onBack}){
  const items=vocab.slice(0,6);
  const [matched,setMatched]=useState([]);
  const [selWord,setSelWord]=useState(null);
  const [selDef,setSelDef]=useState(null);
  const [shake,setShake]=useState(false);
  const [shuffledDefs]=useState(()=>shuffle(items));
  useEffect(()=>{
    if(selWord&&selDef){
      const w=items.find(i=>i.word===selWord);
      if(w&&w.def===selDef){ const nm=[...matched,selWord];setMatched(nm);setSelWord(null);setSelDef(null);if(nm.length>=items.length)setTimeout(onWin,500); }
      else{ setShake(true);setTimeout(()=>{setSelWord(null);setSelDef(null);setShake(false);},800); }
    }
  },[selWord,selDef]);
  return(
    <div className="si">
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:13}}>
        <button className="btn" onClick={onBack} style={{background:"#7C3AED22",border:"1px solid #7C3AED44",color:"#a78bfa",borderRadius:9,padding:"5px 11px",fontSize:12}}>← Back</button>
        <h3 style={{color:"#fff",fontWeight:800,flex:1,fontSize:16}}>🔗 Word Match</h3>
        <span style={{color:color,fontWeight:800,fontSize:13}}>{matched.length}/{items.length}</span>
      </div>
      {shake&&<p style={{color:"#FF4444",fontWeight:800,textAlign:"center",marginBottom:7,animation:"shake .3s ease"}}>❌ Try again!</p>}
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:7}}>
        <div>
          <p style={{color:"#a78bfa",fontSize:10,fontWeight:700,marginBottom:5}}>WORDS</p>
          {items.map(item=>(
            <button key={item.word} className="btn" onClick={()=>!matched.includes(item.word)&&setSelWord(item.word)}
              style={{width:"100%",padding:"8px 9px",borderRadius:10,marginBottom:4,fontWeight:800,fontSize:12,textAlign:"left",background:matched.includes(item.word)?"#00C89622":selWord===item.word?`${color}33`:"#0d0521",border:`2px solid ${matched.includes(item.word)?"#00C896":selWord===item.word?color:"#7C3AED22"}`,color:matched.includes(item.word)?"#00C896":"#fff"}}>
              {item.emoji} {item.word}
            </button>
          ))}
        </div>
        <div>
          <p style={{color:"#a78bfa",fontSize:10,fontWeight:700,marginBottom:5}}>DEFINITIONS</p>
          {shuffledDefs.map(item=>(
            <button key={item.def} className="btn" onClick={()=>!matched.includes(item.word)&&setSelDef(item.def)}
              style={{width:"100%",padding:"8px 9px",borderRadius:10,marginBottom:4,fontWeight:600,fontSize:10,textAlign:"left",background:matched.includes(item.word)?"#00C89622":selDef===item.def?`${color}33`:"#0d0521",border:`2px solid ${matched.includes(item.word)?"#00C896":selDef===item.def?color:"#7C3AED22"}`,color:matched.includes(item.word)?"#00C896":"#e2e8f0"}}>
              {item.def}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

// ─── GAME: WORD SEARCH ────────────────────────────────────────────────────────
function WordSearch({words,color,onWin,onBack}){
  const targets=words.map(w=>w.toUpperCase().replace(/[^A-Z]/g,"")).filter(w=>w.length>=3&&w.length<=8).slice(0,4);
  const SIZE=9;
  const [found,setFound]=useState([]);
  const [sel,setSel]=useState([]);
  const [timeLeft,setTimeLeft]=useState(60);
  const [grid]=useState(()=>{
    const g=Array.from({length:SIZE},()=>Array(SIZE).fill(""));
    const alpha="ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    targets.forEach(word=>{
      for(let a=0;a<80;a++){
        const r=Math.floor(Math.random()*SIZE),c=Math.floor(Math.random()*(SIZE-word.length));
        let ok=true; for(let j=0;j<word.length;j++) if(g[r][c+j]&&g[r][c+j]!==word[j]){ok=false;break;}
        if(ok){for(let j=0;j<word.length;j++) g[r][c+j]=word[j];break;}
      }
    });
    for(let r=0;r<SIZE;r++) for(let c=0;c<SIZE;c++) if(!g[r][c]) g[r][c]=alpha[Math.floor(Math.random()*26)];
    return g;
  });
  useEffect(()=>{if(timeLeft<=0) return;const t=setInterval(()=>setTimeLeft(x=>x-1),1000);return()=>clearInterval(t);},[timeLeft]);
  const ck=(r,c)=>`${r}-${c}`;
  const click=(r,c)=>{
    const k=ck(r,c),ns=[...sel,k]; setSel(ns);
    const letters=ns.map(k=>{const[rr,cc]=k.split("-").map(Number);return g[rr][cc];}).join("");
    const hit=targets.find(w=>letters.includes(w)&&!found.includes(w));
    if(hit){const nf=[...found,hit];setFound(nf);setSel([]);if(nf.length>=targets.length)setTimeout(onWin,500);}
    else if(ns.length>9) setSel([]);
  };
  const g=grid; const tc=timeLeft>30?"#00C896":timeLeft>15?"#F59E0B":"#FF4444";
  return(
    <div className="si">
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:9}}>
        <button className="btn" onClick={onBack} style={{background:"#7C3AED22",border:"1px solid #7C3AED44",color:"#a78bfa",borderRadius:9,padding:"5px 11px",fontSize:12}}>← Back</button>
        <h3 style={{color:"#fff",fontWeight:800,flex:1,fontSize:16}}>🔍 Word Search</h3>
        <div style={{color:tc,fontWeight:900,fontSize:17}}>⏱{timeLeft}s</div>
      </div>
      <div style={{display:"flex",gap:5,flexWrap:"wrap",marginBottom:9}}>
        {targets.map(w=><span key={w} style={{padding:"3px 8px",borderRadius:20,fontSize:10,fontWeight:800,background:found.includes(w)?"#00C89622":"#7C3AED22",color:found.includes(w)?"#00C896":color,border:`1px solid ${found.includes(w)?"#00C896":color}44`,textDecoration:found.includes(w)?"line-through":"none"}}>{found.includes(w)?"✓ ":""}{w}</span>)}
      </div>
      <div style={{display:"inline-block"}}>
        {g.map((row,r)=>(
          <div key={r} style={{display:"flex"}}>
            {row.map((cell,c)=>{
              const isS=sel.includes(ck(r,c));
              return <button key={c} className="btn" onClick={()=>click(r,c)} style={{width:32,height:32,margin:1,borderRadius:6,fontWeight:900,fontSize:11,background:isS?color:"#0d0521",color:isS?"#000":"#a78bfa",border:`1px solid ${isS?color:"#7C3AED22"}`}}>{cell}</button>;
            })}
          </div>
        ))}
      </div>
      {timeLeft<=0&&<div className="bi" style={{textAlign:"center",marginTop:9}}><p style={{color:"#FF4444",fontWeight:800,fontSize:16}}>⏰ Time's up!</p><button className="btn" onClick={onWin} style={{background:"#7C3AED",color:"#fff",borderRadius:11,padding:"9px 20px",fontWeight:800,marginTop:7}}>Continue</button></div>}
    </div>
  );
}

// ─── GAME: CHAT SIMULATOR ─────────────────────────────────────────────────────
function ChatSimulator({color,onWin,onBack}){
  const chats=[
    {sit:"Your friend says: 'I don't think I'm going to enter the poster competition.'",opts:["Certainly!","Good luck!","What a pity!"],ans:2,fb:"'What a pity!' shows regret for someone's decision."},
    {sit:"Your classmate asks: 'What do you think of my hat?'",opts:["Don't come.","Very well.","It's too big."],ans:2,fb:"'It's too big' gives an honest opinion about size."},
    {sit:"Your partner says: 'We haven't discussed our tour plans yet.'",opts:["You poor thing.","Let's do it now.","As late as possible."],ans:1,fb:"'Let's do it now' encourages immediate action."},
  ];
  const [idx,setIdx]=useState(0);
  const [chosen,setChosen]=useState(null);
  const [msgs,setMsgs]=useState([{from:"other",text:chats[0].sit}]);
  const answer=i=>{
    if(chosen!==null) return; setChosen(i);
    const correct=i===chats[idx].ans;
    const nm=[...msgs,{from:"me",text:chats[idx].opts[i],correct},{from:"sys",text:chats[idx].fb}];
    setMsgs(nm);
    setTimeout(()=>{
      setChosen(null);
      const ni=idx+1;
      if(ni>=chats.length) onWin();
      else{setIdx(ni);setMsgs([{from:"other",text:chats[ni].sit}]);}
    },1400);
  };
  return(
    <div className="si">
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:9}}>
        <button className="btn" onClick={onBack} style={{background:"#7C3AED22",border:"1px solid #7C3AED44",color:"#a78bfa",borderRadius:9,padding:"5px 11px",fontSize:12}}>← Back</button>
        <h3 style={{color:"#fff",fontWeight:800,flex:1,fontSize:16}}>💬 Chat Simulator</h3>
        <span style={{color:"#00C896",fontWeight:800,fontSize:12}}>{idx+1}/{chats.length}</span>
      </div>
      <div style={{background:"#0a0a14",borderRadius:13,padding:11,marginBottom:11,minHeight:150,border:`1px solid ${color}33`}}>
        {msgs.map((m,i)=>(
          <div key={i} style={{display:"flex",justifyContent:m.from==="me"?"flex-end":"flex-start",marginBottom:5}}>
            <div style={{maxWidth:"80%",padding:"7px 11px",borderRadius:m.from==="me"?"13px 13px 4px 13px":"13px 13px 13px 4px",background:m.from==="sys"?"#F59E0B22":m.from==="me"?(m.correct?"#00C89633":"#FF444433"):"#1a0a3d",border:m.from==="sys"?"1px solid #F59E0B44":"none",fontSize:12,color:m.from==="sys"?"#F59E0B":"#fff",fontWeight:m.from==="sys"?700:500}}>
              {m.text}
            </div>
          </div>
        ))}
      </div>
      {chosen===null&&(
        <div style={{display:"flex",flexDirection:"column",gap:6}}>
          {chats[idx].opts.map((opt,i)=>(
            <button key={i} className="btn" onClick={()=>answer(i)} style={{padding:"10px 13px",borderRadius:11,textAlign:"left",fontWeight:700,fontSize:13,background:"#1a0a3d",border:`2px solid ${color}33`,color:"#e2e8f0"}}>
              💬 {opt}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

// ─── GAME: BUILD SENTENCE ─────────────────────────────────────────────────────
function BuildSentence({sentences,color,onWin,onBack}){
  const [idx,setIdx]=useState(0);
  const sentence=sentences[idx];
  const words=sentence.split(" ");
  const [pool,setPool]=useState(()=>shuffle(words));
  const [built,setBuilt]=useState([]);
  const [result,setResult]=useState(null);
  const add=(w,i)=>{const np=[...pool];np.splice(i,1);setPool(np);setBuilt(b=>[...b,w]);};
  const remove=(w,i)=>{const nb=[...built];nb.splice(i,1);setBuilt(nb);setPool(p=>[...p,w]);};
  const check=()=>{
    const ok=built.join(" ")===words.join(" ");
    setResult(ok?"correct":"wrong");
    setTimeout(()=>{
      setResult(null);setPool(shuffle(words));setBuilt([]);
      if(idx+1>=sentences.length) onWin(); else setIdx(i=>i+1);
    },900);
  };
  return(
    <div className="si">
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:13}}>
        <button className="btn" onClick={onBack} style={{background:"#7C3AED22",border:"1px solid #7C3AED44",color:"#a78bfa",borderRadius:9,padding:"5px 11px",fontSize:12}}>← Back</button>
        <h3 style={{color:"#fff",fontWeight:800,flex:1,fontSize:16}}>🧩 Build Sentence</h3>
        <span style={{color:"#F59E0B",fontWeight:800,fontSize:12}}>{idx+1}/{sentences.length}</span>
      </div>
      <div style={{background:"#0d0521",borderRadius:13,padding:13,marginBottom:9,border:`2px solid ${color}33`,minHeight:55}}>
        <p style={{color:"#a78bfa",fontSize:10,marginBottom:5}}>Your sentence:</p>
        <div style={{display:"flex",flexWrap:"wrap",gap:5,minHeight:30}}>
          {built.map((w,i)=><button key={i} className="btn" onClick={()=>remove(w,i)} style={{padding:"4px 11px",borderRadius:8,background:color,color:"#000",fontWeight:800,fontSize:12}}>{w}</button>)}
        </div>
      </div>
      <div style={{display:"flex",flexWrap:"wrap",gap:5,marginBottom:13}}>
        {pool.map((w,i)=><button key={i} className="btn" onClick={()=>add(w,i)} style={{padding:"4px 11px",borderRadius:8,background:"#1a0a3d",border:`1px solid ${color}44`,color:"#fff",fontWeight:700,fontSize:12}}>{w}</button>)}
      </div>
      {result&&<div className="bi" style={{textAlign:"center",fontSize:19,fontWeight:900,color:result==="correct"?"#00C896":"#FF4444",marginBottom:7}}>{result==="correct"?"✅ Correct!":"❌ Not quite..."}</div>}
      {built.length>0&&!result&&<button className="btn" onClick={check} style={{width:"100%",padding:12,borderRadius:12,background:`linear-gradient(90deg,${color},#7C3AED)`,color:"#000",fontWeight:900,fontSize:15}}>Check! ✓</button>}
    </div>
  );
}

// ─── GAME: TRUE/FALSE ─────────────────────────────────────────────────────────
function TrueFalse({statements,color,onWin,onBack}){
  const [idx,setIdx]=useState(0);
  const [result,setResult]=useState(null);
  const answer=ans=>{
    const correct=ans===statements[idx].answer;
    setResult(correct?"correct":"wrong");
    setTimeout(()=>{setResult(null);if(idx+1>=statements.length) onWin();else setIdx(i=>i+1);},900);
  };
  const s=statements[idx];
  return(
    <div className="si">
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:13}}>
        <button className="btn" onClick={onBack} style={{background:"#7C3AED22",border:"1px solid #7C3AED44",color:"#a78bfa",borderRadius:9,padding:"5px 11px",fontSize:12}}>← Back</button>
        <h3 style={{color:"#FF4444",fontWeight:900,flex:1,fontSize:16}}>⚔️ True or False?</h3>
        <span style={{color:color,fontWeight:800,fontSize:12}}>{idx+1}/{statements.length}</span>
      </div>
      <div style={{background:"#0d0521",borderRadius:15,padding:17,marginBottom:13,border:`2px solid ${color}44`,textAlign:"center"}}>
        <div style={{fontSize:40,marginBottom:7}}>🗺️</div>
        <p style={{color:"#fff",fontWeight:700,fontSize:15,lineHeight:1.5}}>{s.text}</p>
      </div>
      {result&&<div className="bi" style={{textAlign:"center",fontSize:21,fontWeight:900,color:result==="correct"?"#00C896":"#FF4444",marginBottom:9}}>{result==="correct"?"✅ Correct!":"❌ Wrong!"}</div>}
      {!result&&(
        <div style={{display:"flex",gap:9}}>
          <button className="btn" onClick={()=>answer(true)} style={{flex:1,padding:13,borderRadius:12,background:"#00C89622",border:"2px solid #00C89644",color:"#00C896",fontWeight:900,fontSize:16}}>✅ TRUE</button>
          <button className="btn" onClick={()=>answer(false)} style={{flex:1,padding:13,borderRadius:12,background:"#FF444422",border:"2px solid #FF444444",color:"#FF4444",fontWeight:900,fontSize:16}}>❌ FALSE</button>
        </div>
      )}
    </div>
  );
}

// ─── GAME: RUNNER ─────────────────────────────────────────────────────────────
function Runner({good,color,onWin,onBack}){
  const allItems=shuffle([...good.map(w=>({word:w,correct:true})),...good.map(w=>({word:w.split("").reverse().join(""),correct:false}))]).slice(0,8);
  const [idx,setIdx]=useState(0);
  const [score,setScore]=useState(0);
  const [fb,setFb]=useState(null);
  const answer=collect=>{
    if(fb||idx>=allItems.length) return;
    const correct=allItems[idx].correct===collect;
    setFb(correct?"correct":"wrong");
    if(correct) setScore(s=>s+1);
    setTimeout(()=>{setFb(null);if(idx+1>=allItems.length) onWin();else setIdx(i=>i+1);},700);
  };
  if(idx>=allItems.length) return null;
  const cur=allItems[idx];
  return(
    <div className="si" style={{textAlign:"center"}}>
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:11}}>
        <button className="btn" onClick={onBack} style={{background:"#7C3AED22",border:"1px solid #7C3AED44",color:"#a78bfa",borderRadius:9,padding:"5px 11px",fontSize:12}}>← Back</button>
        <h3 style={{color:"#fff",fontWeight:800,flex:1,fontSize:16}}>🏃 Guardian Runner</h3>
        <span style={{color:"#F59E0B",fontWeight:800}}>{score}/{allItems.length}</span>
      </div>
      <div style={{background:"#1a0a3d",borderRadius:5,height:7,marginBottom:13,overflow:"hidden"}}>
        <div style={{height:"100%",background:`linear-gradient(90deg,${color},#7C3AED)`,width:`${(idx/allItems.length)*100}%`,transition:"width .4s ease"}}/>
      </div>
      <div style={{background:"#0d0521",borderRadius:15,padding:20,marginBottom:13,border:`2px solid ${color}33`,position:"relative",overflow:"hidden"}}>
        <div style={{position:"absolute",bottom:0,left:0,right:0,height:3,background:`linear-gradient(90deg,${color},#7C3AED)`}}/>
        <div style={{fontSize:50,marginBottom:7}}>🛡️</div>
        <div style={{background:`${color}22`,border:`2px solid ${color}`,borderRadius:11,padding:"9px 18px",display:"inline-block"}}>
          <span style={{color:"#fff",fontWeight:900,fontSize:19}}>{cur.word}</span>
        </div>
        <p style={{color:"#a78bfa",fontSize:11,marginTop:7}}>Is this a real mission word?</p>
      </div>
      {fb&&<div className="bi" style={{fontSize:21,fontWeight:900,color:fb==="correct"?"#00C896":"#FF4444",marginBottom:7}}>{fb==="correct"?"✅ Great!":"❌ Oops!"}</div>}
      {!fb&&(
        <div style={{display:"flex",gap:9}}>
          <button className="btn" onClick={()=>answer(true)} style={{flex:1,padding:12,borderRadius:12,background:"#00C89622",border:"2px solid #00C89644",color:"#00C896",fontWeight:900,fontSize:14}}>✅ Collect!</button>
          <button className="btn" onClick={()=>answer(false)} style={{flex:1,padding:12,borderRadius:12,background:"#FF444422",border:"2px solid #FF444444",color:"#FF4444",fontWeight:900,fontSize:14}}>❌ Avoid!</button>
        </div>
      )}
    </div>
  );
}

// ─── BOSS BATTLE ─────────────────────────────────────────────────────────────
function BossBattle({mission,onWin,onBack}){
  const bosses={
    m1:{name:"Virus Monster",emoji:"🦠",qs:[{q:"What do you take for a headache?",opts:["medicine","hospital","cry"],ans:0},{q:"Where do sick people go?",opts:["school","hospital","park"],ans:1},{q:"Who helps sick people?",opts:["teacher","doctor","police"],ans:1}]},
    m2:{name:"Time Shadow",emoji:"⏰",qs:[{q:"'What a pity!' expresses:",opts:["happiness","regret","surprise"],ans:1},{q:"'Let's do it now' means:",opts:["do it later","start immediately","don't do it"],ans:1},{q:"'Good luck!' is used to:",opts:["say goodbye","wish success","ask a question"],ans:1}]},
    m3:{name:"Marco Polo Myth",emoji:"🗺️",qs:[{q:"Who ACTUALLY brought pasta to Italy?",opts:["Marco Polo","Arabs","Chinese"],ans:1},{q:"Italy is followed by __ in pasta eating.",opts:["Mexico","Philippines","Venezuela"],ans:2},{q:"Pasta became popular in the US because Italians...",opts:["arrived there","were famous","liked pizza"],ans:0}]},
    m4:{name:"Stress Monster",emoji:"😡",qs:[{q:"Smiling can REDUCE...",opts:["energy","stress","happiness"],ans:1},{q:"The text ENCOURAGES people to...",opts:["avoid stress","smile more","eat better"],ans:1},{q:"Smiling makes others feel...",opts:["jealous","comfortable","tired"],ans:1}]},
    m5:{name:"Shadow Referee",emoji:"🕵️",qs:[{q:"'Take place' means:",opts:["take something","happen/occur","take position"],ans:1},{q:"Which relative pronoun is correct for things?",opts:["who","when","which"],ans:2},{q:"Soccer 'means' far more — 'means' here expresses:",opts:["a definition","significance/importance","a direction"],ans:1}]},
  };
  const boss=bosses[mission.id]||bosses.m1;
  const [hp,setHp]=useState(3);
  const [qIdx,setQIdx]=useState(0);
  const [chosen,setChosen]=useState(null);
  const [shake,setShake]=useState(false);
  const [won,setWon]=useState(false);
  const answer=i=>{
    if(chosen!==null) return; setChosen(i);
    if(i===boss.qs[qIdx].ans){const nb=hp-1;setHp(nb);setShake(true);setTimeout(()=>setShake(false),500);if(nb<=0){setTimeout(()=>setWon(true),600);return;}}
    setTimeout(()=>{setChosen(null);setQIdx(x=>(x+1)%boss.qs.length);},900);
  };
  if(won) return(
    <div className="bi" style={{textAlign:"center",padding:26}}>
      <div style={{fontSize:68,marginBottom:9}}>🏆</div>
      <h2 style={{color:"#F59E0B",fontSize:30,fontWeight:900,marginBottom:7}}>BOSS DEFEATED!</h2>
      <p style={{color:"#00C896",fontSize:16,fontWeight:800,marginBottom:16}}>+150 XP  +120 🪙</p>
      <button className="btn" onClick={onWin} style={{background:"linear-gradient(90deg,#F59E0B,#EC4899)",color:"#000",borderRadius:13,padding:"12px 28px",fontWeight:900,fontSize:16}}>Claim Victory! →</button>
    </div>
  );
  const q=boss.qs[qIdx];
  return(
    <div className="si">
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:13}}>
        <button className="btn" onClick={onBack} style={{background:"#7C3AED22",border:"1px solid #7C3AED44",color:"#a78bfa",borderRadius:9,padding:"5px 11px",fontSize:12}}>← Back</button>
        <h3 style={{color:"#FF4444",fontWeight:900,flex:1,fontSize:16}}>⚔️ BOSS: {boss.name}</h3>
      </div>
      <div style={{background:"#0d0521",borderRadius:15,padding:17,marginBottom:13,border:"2px solid #FF444433",textAlign:"center"}}>
        <div style={{fontSize:60,marginBottom:5,animation:shake?"shake .4s ease":"none"}}>{boss.emoji}</div>
        <div style={{background:"#1a0a3d",borderRadius:7,overflow:"hidden",height:13,marginBottom:3}}>
          <div style={{height:"100%",background:"linear-gradient(90deg,#FF4444,#FF8800)",width:`${(hp/3)*100}%`,transition:"width .5s ease"}}/>
        </div>
        <p style={{color:"#FF4444",fontSize:11,fontWeight:800}}>HP: {hp}/3</p>
      </div>
      <div style={{background:"#0d0521",borderRadius:13,padding:13,marginBottom:11,border:`2px solid ${mission.color}44`}}>
        <p style={{color:"#fff",fontWeight:800,fontSize:14,marginBottom:11}}>⚔️ {q.q}</p>
        <div style={{display:"flex",flexDirection:"column",gap:6}}>
          {q.opts.map((opt,i)=>{
            let bg="#1a0a3d",border="#7C3AED33",col="#e2e8f0";
            if(chosen!==null){if(i===q.ans){bg="#00C89622";border="#00C896";col="#00C896";}else if(i===chosen&&i!==q.ans){bg="#FF444422";border="#FF4444";col="#FF4444";}}
            return <button key={i} className="btn" onClick={()=>answer(i)} style={{padding:"10px 13px",borderRadius:10,textAlign:"left",fontWeight:700,fontSize:13,background:bg,border:`2px solid ${border}`,color:col}}>{["⚔️","🗡️","🛡️"][i]} {opt}</button>;
          })}
        </div>
      </div>
    </div>
  );
}

// ─── PREMIACIÓN ───────────────────────────────────────────────────────────────
function Premiacion({mission,playerName,lives,onComplete,onBack,onLoseLife}){
  const qs=mission.questions;
  const [idx,setIdx]=useState(0);
  const [chosen,setChosen]=useState(null);
  const [score,setScore]=useState(0);
  const [timeLeft,setTimeLeft]=useState(35);
  const [unlocked,setUnlocked]=useState(null);
  const timerRef=useRef(null);
  useEffect(()=>{
    timerRef.current=setInterval(()=>{
      setTimeLeft(t=>{if(t<=1){clearInterval(timerRef.current);handleAnswer("TIMEOUT");return 0;}return t-1;});
    },1000);
    return()=>clearInterval(timerRef.current);
  },[idx]);
  const handleAnswer=opt=>{
    if(chosen) return;
    clearInterval(timerRef.current);
    const q=qs[idx];
    const correct=opt===q.ans;
    setChosen(opt);
    recordAnswer(playerName,q.id,correct);
    if(!correct) onLoseLife();
    else{ setUnlocked(mission.reward.items[idx%mission.reward.items.length]); }
    setTimeout(()=>{
      setUnlocked(null);setChosen(null);setTimeLeft(35);
      const ns=score+(correct?1:0);
      if(idx+1>=qs.length) onComplete(ns,qs.length);
      else{setScore(ns);setIdx(i=>i+1);}
    },1400);
  };
  const q=qs[idx];
  const tc=timeLeft>20?"#00C896":timeLeft>10?"#F59E0B":"#FF4444";
  return(
    <div className="si">
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:9}}>
        <button className="btn" onClick={onBack} style={{background:"#7C3AED22",border:"1px solid #7C3AED44",color:"#a78bfa",borderRadius:9,padding:"5px 11px",fontSize:12}}>← Back</button>
        <h3 style={{color:"#FFD700",fontWeight:900,flex:1,fontSize:16}}>🏆 Premiación ICFES</h3>
        <div style={{color:tc,fontWeight:900,fontSize:16}}>⏱{timeLeft}s</div>
      </div>
      <LivesBar lives={lives}/>
      <div style={{background:"#1a0a3d",borderRadius:5,height:6,marginBottom:9,overflow:"hidden"}}>
        <div style={{height:"100%",background:tc,width:`${(timeLeft/35)*100}%`,transition:"width 1s linear"}}/>
      </div>
      <div style={{display:"flex",gap:4,marginBottom:11,justifyContent:"center"}}>
        {qs.map((_,i)=><div key={i} style={{width:19,height:5,borderRadius:3,background:i<idx?mission.color:i===idx?"#FFD700":"#1a0a3d"}}/>)}
      </div>
      {unlocked&&<div className="bi" style={{background:"#FFD70022",border:"2px solid #FFD70066",borderRadius:11,padding:"7px 13px",marginBottom:9,textAlign:"center",color:"#FFD700",fontWeight:800,fontSize:13}}>🎁 Unlocked: {unlocked}</div>}
      <div style={{background:"#0d0521",borderRadius:15,padding:15,marginBottom:11,border:`2px solid ${mission.color}44`}}>
        <div style={{display:"flex",gap:6,alignItems:"flex-start",marginBottom:9}}>
          <span style={{background:"#FFD70022",border:"1px solid #FFD70044",color:"#FFD700",borderRadius:7,padding:"2px 7px",fontWeight:900,fontSize:10,flexShrink:0}}>#{q.n}</span>
          <p style={{color:"#fff",fontWeight:700,fontSize:14,lineHeight:1.55}}>{q.text}</p>
        </div>
        <div style={{display:"flex",gap:4,marginBottom:9}}>
          <span style={{fontSize:9,padding:"2px 7px",borderRadius:20,background:`${mission.color}22`,color:mission.color,border:`1px solid ${mission.color}44`}}>{q.competencia}</span>
          <span style={{fontSize:9,padding:"2px 7px",borderRadius:20,background:"#F59E0B22",color:"#F59E0B",border:"1px solid #F59E0B44"}}>{q.nivel}</span>
          <span style={{fontSize:9,padding:"2px 7px",borderRadius:20,background:"#EC489922",color:"#EC4899",border:"1px solid #EC489933"}}>{"⭐".repeat(q.dificultad)}</span>
        </div>
        <div style={{display:"flex",flexDirection:"column",gap:6}}>
          {q.opts.map((opt,i)=>{
            const letter=["A","B","C","D"][i];
            let bg="#1a0a3d",border="#7C3AED33",col="#e2e8f0";
            if(chosen){if(letter===q.ans){bg="#00C89622";border="#00C896";col="#00C896";}else if(letter===chosen&&letter!==q.ans){bg="#FF444422";border="#FF4444";col="#FF4444";}}
            return(
              <button key={i} className="btn" onClick={()=>handleAnswer(letter)} style={{padding:"9px 12px",borderRadius:10,textAlign:"left",fontWeight:700,fontSize:13,background:bg,border:`2px solid ${border}`,color:col}}>
                <span style={{fontWeight:900,marginRight:6,color:mission.color}}>{letter}.</span>{opt}
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

// ─── REWARD SCREEN ────────────────────────────────────────────────────────────
function RewardScreen({mission,score,total,onContinue}){
  const pct=Math.round((score/total)*100);
  const stars=pct>=80?3:pct>=60?2:1;
  const xpEarned=score*50+(pct===100?100:0);
  const coinsEarned=score*30+mission.coins;
  const msg=pct>=80?"EXCELLENT! 🎉":pct>=60?"GOOD JOB! 👍":"KEEP GOING! 💪";
  return(
    <div className="bi" style={{textAlign:"center",padding:11}}>
      <div style={{fontSize:58,marginBottom:5,filter:`drop-shadow(0 0 13px ${mission.color})`}}>{mission.emoji}</div>
      <h2 style={{fontSize:30,fontWeight:900,marginBottom:4,background:`linear-gradient(90deg,${mission.color},#F59E0B)`,WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent"}}>{msg}</h2>
      <div style={{display:"flex",justifyContent:"center",gap:5,marginBottom:13}}>
        {Array.from({length:3}).map((_,i)=><span key={i} style={{fontSize:30,opacity:i<stars?1:.2,animation:i<stars?`starPop .5s ${i*.2}s both`:"none"}}>⭐</span>)}
      </div>
      <div style={{background:"#0d0521",borderRadius:16,padding:"16px 22px",marginBottom:13,border:`2px solid ${mission.color}44`,display:"inline-block"}}>
        <div style={{fontSize:34,fontWeight:900,color:mission.color,marginBottom:4}}>{score}/{total}</div>
        <div style={{display:"flex",gap:11,justifyContent:"center",marginBottom:7}}>
          <span style={{color:"#F59E0B",fontWeight:800}}>+{xpEarned} XP</span>
          <span style={{color:"#F59E0B",fontWeight:800}}>+{coinsEarned} 🪙</span>
        </div>
        <div style={{background:"#FFD70022",border:"1px solid #FFD70044",borderRadius:9,padding:"7px 13px"}}>
          <p style={{color:"#FFD700",fontSize:11,fontWeight:700,marginBottom:3}}>🎁 New Guardian Unlocked!</p>
          <span style={{fontSize:34}}>{mission.rewardAvatar}</span>
        </div>
      </div>
      <div style={{background:"#0d0521",borderRadius:13,padding:13,marginBottom:13,border:"1px solid #F59E0B33"}}>
        <p style={{color:"#F59E0B",fontWeight:800,fontSize:12,marginBottom:7}}>🎁 REWARDS UNLOCKED</p>
        <div style={{display:"flex",flexWrap:"wrap",gap:5,justifyContent:"center"}}>
          {mission.reward.items.map((item,i)=><span key={i} style={{padding:"4px 11px",borderRadius:20,background:"#F59E0B22",border:"1px solid #F59E0B44",color:"#F59E0B",fontSize:11,fontWeight:700}}>{item}</span>)}
        </div>
      </div>
      <button className="btn" onClick={onContinue} style={{background:`linear-gradient(90deg,${mission.color},#7C3AED)`,color:"#000",borderRadius:13,padding:"12px 30px",fontWeight:900,fontSize:16,boxShadow:`0 0 16px ${mission.color}66`}}>
        Claim All Rewards! 🏆
      </button>
    </div>
  );
}

