const G67_AvatarPicker=({current,onSelect,onClose})=>(
  <div style={{position:"fixed",inset:0,background:"rgba(30,41,59,.6)",zIndex:6000,
    display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
    <div className="pop" style={{background:G67_P.card,borderRadius:22,padding:24,maxWidth:380,width:"100%",
      boxShadow:"0 8px 48px rgba(34,197,94,.2)"}}>
      <div style={{fontWeight:900,fontSize:17,color:G67_P.text,marginBottom:4,textAlign:"center"}}>🎭 Elige tu Avatar</div>
      <p style={{color:G67_P.muted,fontSize:12,textAlign:"center",margin:"0 0 16px"}}>Toca el que más te guste</p>
      <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:9,marginBottom:14}}>
        {G67_AVATARS.map(a=>(
          <div key={a.id} onClick={()=>onSelect(a)}
            style={{textAlign:"center",padding:"9px 4px",borderRadius:13,cursor:"pointer",
              border:`2px solid ${current===a.id?G67_P.primary:G67_P.border}`,
              background:current===a.id?`${G67_P.primary}18`:"#F0FDF4",transition:"all .2s"}}>
            <div style={{fontSize:26,marginBottom:2}}>{a.emoji}</div>
            <div style={{fontSize:9,color:G67_P.muted,fontWeight:700}}>{a.label}</div>
          </div>
        ))}
      </div>
      <button onClick={onClose} style={{width:"100%",padding:"10px 0",borderRadius:13,border:"none",
        background:G67_P.primary,color:"#fff",fontWeight:900,cursor:"pointer",fontSize:14}}>✓ Listo</button>
    </div>
  </div>
);

// ══════════════════════════════════════════════════════════════
//  WELCOME SCREEN
// ══════════════════════════════════════════════════════════════
const G67_WelcomeScreen=({onStart})=>{
  const [name,setName]=useState("");
  const [avatar,setAvatar]=useState(G67_AVATARS[0]);
  const [showPicker,setShowPicker]=useState(false);
  const [err,setErr]=useState(false);
  const go=()=>{if(!name.trim()){setErr(true);return;}onStart(name.trim(),avatar);};
  return(
    <div style={{minHeight:"100vh",background:G67_P.bg,display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
      <style>{G67_CSS}</style>
      {showPicker&&<G67_AvatarPicker current={avatar.id} onSelect={a=>{setAvatar(a);setShowPicker(false);}} onClose={()=>setShowPicker(false)}/>}
      <div className="pop" style={{background:G67_P.card,borderRadius:26,padding:30,maxWidth:400,width:"100%",
        boxShadow:"0 8px 48px rgba(34,197,94,.18)",textAlign:"center"}}>
        <div style={{display:"inline-flex",alignItems:"center",gap:6,background:`${G67_P.primary}12`,
          border:`1px solid ${G67_P.primary}33`,borderRadius:30,padding:"3px 12px",marginBottom:10,
          fontSize:11,color:G67_P.primary,fontWeight:700}}>
          🏫 I.E. La Amistad • Grados 6° y 7° • Mg. Anderson
        </div>
        <h1 style={{margin:"0 0 4px",fontWeight:900,fontSize:22,
          background:`linear-gradient(90deg,${G67_P.primary},${G67_P.accent},${G67_P.purple})`,
          WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent"}}>
          🌟 English Guardians G6-G7
        </h1>
        <p style={{color:G67_P.muted,fontSize:12,margin:"0 0 22px"}}>Presente Simple • Vocabulario Básico • Pre A1 / A1</p>
        <div style={{marginBottom:20}}>
          <div style={{fontSize:11,fontWeight:700,color:G67_P.muted,marginBottom:9}}>Elige tu avatar</div>
          <div onClick={()=>setShowPicker(true)} className="float"
            style={{width:78,height:78,borderRadius:"50%",margin:"0 auto 8px",cursor:"pointer",
              background:`linear-gradient(135deg,${G67_P.primary},${G67_P.accent})`,
              display:"flex",alignItems:"center",justifyContent:"center",fontSize:38,
              boxShadow:`0 6px 22px ${G67_P.primary}44`,border:`3px solid ${G67_P.primary}`}}>
            {avatar.emoji}
          </div>
          <button onClick={()=>setShowPicker(true)} style={{background:"none",border:`1.5px solid ${G67_P.border}`,
            borderRadius:20,padding:"4px 14px",color:G67_P.muted,cursor:"pointer",fontSize:12,fontWeight:700}}>
            🎭 Cambiar avatar
          </button>
        </div>
        <div style={{marginBottom:20,textAlign:"left"}}>
          <div style={{fontSize:11,fontWeight:700,color:G67_P.muted,marginBottom:7}}>¿Cuál es tu nombre?</div>
          <input value={name} onChange={e=>{setName(e.target.value);setErr(false);}}
            onKeyDown={e=>e.key==="Enter"&&go()} placeholder="Escribe tu nombre..."
            style={{width:"100%",padding:"12px 15px",borderRadius:13,
              border:`2px solid ${err?G67_P.warn:name?G67_P.primary:G67_P.border}`,
              fontSize:15,fontWeight:700,color:G67_P.text,outline:"none",background:"#F0FDF4"}}/>
          {err&&<p style={{color:G67_P.warn,fontSize:11,fontWeight:700,margin:"5px 0 0"}}>⚠️ Escribe tu nombre para continuar</p>}
        </div>
        <button onClick={go} style={{width:"100%",padding:"13px 0",borderRadius:15,border:"none",
          background:`linear-gradient(90deg,${G67_P.primary},${G67_P.accent})`,
          color:"#fff",fontWeight:900,fontSize:15,cursor:"pointer",
          boxShadow:`0 4px 18px ${G67_P.primary}44`}}>¡Comenzar Aventura! 🌟</button>
        <p style={{color:G67_P.muted,fontSize:10,marginTop:12}}>Si ya jugaste antes, escribe el mismo nombre para recuperar tu progreso.</p>
      </div>
    </div>
  );
};

// ══════════════════════════════════════════════════════════════
//  PLAYER HUD
// ══════════════════════════════════════════════════════════════
const G67_PlayerHUD=({name,xp,coins,lives,avatar,onNameChange,onAvatarChange})=>{
  const [editing,setEditing]=useState(false);
  const [tmp,setTmp]=useState(name);
  const [showPicker,setShowPicker]=useState(false);
  const level=Math.floor(xp/120)+1;
  return <>
    {showPicker&&<G67_AvatarPicker current={avatar.id} onSelect={a=>{onAvatarChange(a);setShowPicker(false);}} onClose={()=>setShowPicker(false)}/>}
    <div className="slideUp" style={{background:G67_P.card,borderRadius:20,padding:"13px 17px",
      marginBottom:13,boxShadow:"0 2px 14px rgba(34,197,94,.10)",border:`1.5px solid ${G67_P.border}`}}>
    <div style={{display:"flex",alignItems:"center",gap:11,flexWrap:"wrap"}}>
      <div onClick={()=>setShowPicker(true)} className="float"
        style={{width:52,height:52,borderRadius:"50%",flexShrink:0,cursor:"pointer",
          background:`linear-gradient(135deg,${G67_P.primary},${G67_P.accent})`,
          display:"flex",alignItems:"center",justifyContent:"center",fontSize:26,position:"relative",
          boxShadow:`0 2px 10px ${G67_P.primary}33`}}>
        {avatar.emoji}
        <div style={{position:"absolute",bottom:-2,right:-2,width:17,height:17,borderRadius:"50%",
          background:G67_P.gold,border:"2px solid #fff",display:"flex",alignItems:"center",
          justifyContent:"center",fontSize:8}}>✏️</div>
      </div>
      <div style={{flex:1,minWidth:140}}>
        <div style={{display:"flex",alignItems:"center",gap:7,marginBottom:5}}>
          {editing
            ?<><input value={tmp} onChange={e=>setTmp(e.target.value)}
                onKeyDown={e=>e.key==="Enter"&&(onNameChange(tmp),setEditing(false))} autoFocus
                style={{background:"transparent",border:"none",borderBottom:`2px solid ${G67_P.primary}`,
                fontSize:14,fontWeight:800,color:G67_P.text,outline:"none",width:150}}/>
              <button onClick={()=>{onNameChange(tmp);setEditing(false);}}
                style={{background:G67_P.accent,color:"#fff",border:"none",borderRadius:8,padding:"2px 7px",cursor:"pointer",fontWeight:700}}>✓</button>
            </>
            :<><span style={{fontWeight:900,fontSize:15,color:G67_P.text}}>{name}</span>
              <button onClick={()=>setEditing(true)} style={{background:"none",border:"none",cursor:"pointer",fontSize:12}}>✏️</button>
            </>}
        </div>
        <G67_XPBar xp={xp}/>
      </div>
      <div style={{display:"flex",gap:7,flexShrink:0}}>
        {[{v:`Nv.${level}`,i:"⭐",c:G67_P.primary},{v:coins,i:"🪙",c:G67_P.gold}].map((s,i)=>(
          <div key={i} style={{textAlign:"center",background:`${s.c}12`,border:`1.5px solid ${s.c}33`,
            borderRadius:11,padding:"5px 9px",minWidth:52}}>
            <div style={{fontSize:13}}>{s.i}</div>
            <div style={{fontWeight:900,color:s.c,fontSize:12}}>{s.v}</div>
          </div>
        ))}
        <div style={{textAlign:"center",background:"#FEE2E222",border:"1.5px solid #EF444433",
          borderRadius:11,padding:"5px 9px",minWidth:52}}>
          {Array.from({length:5}).map((_,i)=>(
            <span key={i} style={{fontSize:11,opacity:i<lives?1:.2}}>❤️</span>
          ))}
          <div style={{fontSize:9,color:G67_P.muted,marginTop:1}}>Vidas</div>
        </div>
      </div>
    </div>
  </div>
  </>;
};

// ══════════════════════════════════════════════════════════════
//  MISSION GRID
// ══════════════════════════════════════════════════════════════
const G67_MissionGrid=({completed,onSelect})=>{
  const mecLabel={quiz:"⚔️ Quiz Boss",wordmatch:"🔤 Word Match",dragdrop:"🎯 Clasificar",fillblank:"✏️ Completar"};
  return <div>
    <h2 style={{fontWeight:900,fontSize:20,color:G67_P.text,marginBottom:13,textAlign:"center"}}>🗺️ Elige tu Misión</h2>
    <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(270px,1fr))",gap:11}}>
      {G67_MISSIONS.map((m,i)=>{
        const done=completed.includes(m.id),locked=i>0&&!completed.includes(G67_MISSIONS[i-1].id);
        return <div key={m.id} onClick={()=>!locked&&onSelect(m)}
          style={{background:locked?"#F0FDF4":m.bg,borderRadius:17,padding:15,cursor:locked?"not-allowed":"pointer",
            border:`2px solid ${done?"#22C55E":locked?"#BBF7D0":m.color}44`,
            boxShadow:done?`0 4px 14px #22C55E22`:`0 2px 10px ${m.color}18`,
            opacity:locked?.55:1,transition:"all .2s",position:"relative",overflow:"hidden"}}>
          <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:9}}>
            <div style={{fontSize:32}}>{m.emoji}</div>
            <div style={{flex:1}}>
              <div style={{fontWeight:900,color:G67_P.text,fontSize:14}}>{m.name}</div>
              <div style={{fontSize:11,color:m.color,fontWeight:700}}>{m.level}</div>
              <div style={{fontSize:10,color:G67_P.muted}}>{m.topic}</div>
            </div>
            {done&&<span style={{fontSize:19}}>✅</span>}
            {locked&&<span style={{fontSize:19}}>🔒</span>}
          </div>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:5}}>
            <span style={{fontSize:10,background:`${m.color}18`,color:m.color,
              padding:"2px 7px",borderRadius:20,fontWeight:700}}>{mecLabel[m.mechanic]}</span>
            <span style={{fontSize:10,color:G67_P.gold,fontWeight:800}}>🪙{m.coins} +{m.xp}XP</span>
          </div>
          <div style={{fontSize:10,color:G67_P.muted}}>🎁 {m.reward}</div>
        </div>;
      })}
    </div>
  </div>;
};

// ══════════════════════════════════════════════════════════════
//  BOSS INTRO
// ══════════════════════════════════════════════════════════════
const G67_BossIntro=({m,onStart,onBack})=>(
  <div className="slideUp" style={{textAlign:"center",padding:"18px 0"}}>
    <div className="shake" style={{fontSize:68,display:"inline-block",marginBottom:8}}>{m.bossEmoji}</div>
    <div style={{background:m.bg,border:`2px solid ${m.color}44`,borderRadius:17,padding:16,marginBottom:14}}>
      <div style={{fontSize:12,fontWeight:700,color:m.color,marginBottom:5}}>⚔️ {m.bossName} aparece!</div>
      <p style={{color:G67_P.text,fontWeight:700,fontSize:13,margin:0}}>
        {m.mechanic==="quiz"&&"¡Lee el texto y responde las preguntas para derrotar al Boss!"}
        {m.mechanic==="wordmatch"&&"¡Conecta cada palabra con su significado! Al final leerás el texto."}
        {m.mechanic==="dragdrop"&&"¡Clasifica las palabras! Al final leerás el texto."}
        {m.mechanic==="fillblank"&&"¡Lee el texto y luego completa las oraciones con la palabra correcta!"}
      </p>
    </div>
    <div style={{fontSize:12,color:G67_P.muted,marginBottom:16}}>
      📖 Nivel: <b>{m.level}</b> • 📚 <b>{m.topic}</b> • 🎁 <b>{m.reward}</b>
    </div>
    <div style={{display:"flex",gap:9,justifyContent:"center"}}>
      <button onClick={onBack} style={{padding:"8px 17px",borderRadius:13,border:`2px solid ${G67_P.border}`,
        background:"#fff",color:G67_P.muted,fontWeight:700,cursor:"pointer",fontSize:13}}>← Volver</button>
      <button onClick={onStart} className="pulse" style={{padding:"8px 22px",borderRadius:13,border:"none",
        background:`linear-gradient(90deg,${m.color},${G67_P.accent})`,color:"#fff",
        fontWeight:900,cursor:"pointer",fontSize:14}}>¡Iniciar Batalla! ⚔️</button>
    </div>
  </div>
);

// ══════════════════════════════════════════════════════════════
//  QUIZ MECHANIC  (text first, then questions)
// ══════════════════════════════════════════════════════════════
const G67_QuizMechanic=({m,onComplete,onRecordAnswer})=>{
  const qs=m.questions;
  const [idx,setIdx]=useState(0);
  const [sel,setSel]=useState(null);
  const [score,setScore]=useState(0);
  const [timeLeft,setTimeLeft]=useState(50);
  const [phase,setPhase]=useState("textIntro"); // "textIntro" | "quiz" | "done"
  const [speaking,setSpeaking]=useState(false);
  const ref=useRef(null);
  useEffect(()=>{
    if(phase!=="quiz"||sel!==null)return;
    ref.current=setInterval(()=>setTimeLeft(t=>{
      if(t<=1){clearInterval(ref.current);handleAns(-1);return 0;}return t-1;
    }),1000);
    return()=>clearInterval(ref.current);
  },[idx,sel,phase]);
  const handleAns=i=>{
    if(sel!==null)return;
    clearInterval(ref.current);setSel(i);
    const ok=i===qs[idx].ans;
    if(ok)setScore(s=>s+1);
    onRecordAnswer(qs[idx].id,ok,qs[idx]);
  };
  const next=()=>{
    setSel(null);setTimeLeft(50);
    if(idx+1>=qs.length)setPhase("done");
    else setIdx(i=>i+1);
  };
  const speak=(rate=0.85)=>{
    if(!("speechSynthesis"in window))return;
    window.speechSynthesis.cancel();
    const u=new SpeechSynthesisUtterance(m.text);u.lang="en-US";u.rate=rate;
    u.onstart=()=>setSpeaking(true);u.onend=()=>setSpeaking(false);
    window.speechSynthesis.speak(u);
  };

  // TEXT INTRO — shown first, before any questions
  if(phase==="textIntro") return (
    <div className="slideUp">
      <div style={{background:`${m.color}18`,borderRadius:14,padding:"10px 15px",marginBottom:12,
        display:"flex",alignItems:"center",gap:8}}>
        <span style={{fontSize:22}}>📖</span>
        <div>
          <div style={{fontWeight:900,color:m.color,fontSize:14}}>Lee el texto con atención</div>
          <div style={{fontSize:11,color:G67_P.muted}}>Después responderás preguntas sobre lo que leíste</div>
        </div>
      </div>
      <div style={{background:G67_P.card,borderRadius:17,padding:18,marginBottom:14,
        border:`1.5px solid ${G67_P.border}`,boxShadow:"0 2px 10px rgba(0,0,0,.05)"}}>
        <p style={{color:G67_P.text,lineHeight:1.9,fontSize:15,margin:0}}>{m.text}</p>
      </div>
      <div style={{display:"flex",gap:7,marginBottom:14}}>
        <button onClick={()=>speak(0.85)} style={{flex:1,padding:"8px 0",borderRadius:12,border:"none",
          background:speaking?`${m.color}22`:m.bg,color:m.color,fontWeight:700,cursor:"pointer",fontSize:12}}>
          {speaking?"🔊 Reproduciendo...":"🔊 Escuchar texto"}
        </button>
        <button onClick={()=>speak(0.6)} style={{flex:1,padding:"8px 0",borderRadius:12,border:"none",
          background:"#F0F9FF",color:G67_P.sky,fontWeight:700,cursor:"pointer",fontSize:12}}>
          🐢 Lento
        </button>
        {speaking&&<button onClick={()=>window.speechSynthesis.cancel()}
          style={{padding:"8px 12px",borderRadius:12,border:"none",background:"#FEE2E2",color:G67_P.warn,cursor:"pointer",fontWeight:700}}>⏹</button>}
      </div>
      <button onClick={()=>setPhase("quiz")} style={{width:"100%",padding:"12px 0",borderRadius:15,
        border:"none",background:`linear-gradient(90deg,${m.color},${G67_P.accent})`,
        color:"#fff",fontWeight:900,fontSize:14,cursor:"pointer"}}>
        🧠 ¡Listo para las Preguntas!
      </button>
    </div>
  );

  if(phase==="done")return <G67_ResultScreen m={m} score={score} total={qs.length} onContinue={()=>onComplete(score,qs.length)}/>;

  const q=qs[idx];
  const tc=timeLeft>30?G67_P.primary:timeLeft>15?G67_P.gold:G67_P.warn;
  return <div className="slideUp">
    <div style={{display:"flex",alignItems:"center",gap:9,marginBottom:11}}>
      <div style={{flex:1,height:6,borderRadius:6,background:"#BBF7D0",overflow:"hidden"}}>
        <div style={{height:"100%",width:`${(idx/qs.length)*100}%`,background:m.color,borderRadius:6,transition:"width .5s"}}/>
      </div>
      <span style={{fontSize:10,fontWeight:800,color:G67_P.muted}}>{idx+1}/{qs.length}</span>
      <div style={{display:"flex",alignItems:"center",gap:4}}>
        <div style={{width:48,height:6,borderRadius:6,background:"#BBF7D0",overflow:"hidden"}}>
          <div style={{height:"100%",width:`${(timeLeft/50)*100}%`,background:tc,borderRadius:6,transition:"width 1s linear"}}/>
        </div>
        <span style={{fontSize:11,fontWeight:800,color:tc}}>{timeLeft}s</span>
      </div>
    </div>
    <div style={{background:m.bg,borderRadius:11,padding:"6px 11px",marginBottom:11,
      display:"flex",alignItems:"center",gap:7}}>
      <span style={{fontSize:19}}>{m.bossEmoji}</span>
      <div style={{flex:1,height:7,borderRadius:7,background:"#BBF7D0",overflow:"hidden"}}>
        <div style={{height:"100%",borderRadius:7,background:G67_P.warn,
          width:`${100-((idx/qs.length)*100)}%`,transition:"width .6s"}}/>
      </div>
      <span style={{fontSize:10,fontWeight:700,color:G67_P.warn}}>{qs.length-idx} HP</span>
    </div>
    <div style={{background:G67_P.card,borderRadius:17,padding:17,marginBottom:11,
      border:`1.5px solid ${G67_P.border}`,boxShadow:"0 2px 8px rgba(0,0,0,.05)"}}>
      <div style={{display:"flex",gap:5,marginBottom:7,flexWrap:"wrap"}}>
        <span style={{fontSize:10,background:`${m.color}18`,color:m.color,padding:"2px 7px",borderRadius:20,fontWeight:700}}>{q.competency}</span>
        <span style={{fontSize:10,background:"#F1F5F9",color:G67_P.muted,padding:"2px 7px",borderRadius:20,fontWeight:700}}>{q.lvl}</span>
      </div>
      <p style={{fontWeight:800,color:G67_P.text,fontSize:16,marginBottom:13}}>{q.q}</p>
      <div style={{display:"flex",flexDirection:"column",gap:8}}>
        {q.opts.map((opt,i)=>{
          let bg=G67_P.bg,border=G67_P.border,col=G67_P.text;
          if(sel!==null){
            if(i===q.ans){bg="#DCFCE7";border="#22C55E";col="#065F46";}
            else if(i===sel&&i!==q.ans){bg="#FEE2E2";border=G67_P.warn;col="#991B1B";}
          }
          return <button key={i} onClick={()=>handleAns(i)}
            style={{width:"100%",textAlign:"left",padding:"12px 14px",borderRadius:12,
              background:bg,border:`2px solid ${border}`,color:col,
              fontWeight:sel!==null&&i===q.ans?800:600,fontSize:15,cursor:"pointer",transition:"all .2s"}}>
            <span style={{color:m.color,fontWeight:900,marginRight:8}}>{["A","B","C","D"][i]}.</span>{opt}
          </button>;
        })}
      </div>
      {sel!==null&&<div className="slideUp" style={{marginTop:11,padding:"8px 12px",borderRadius:10,
        background:`${G67_P.sky}18`,border:`1.5px solid ${G67_P.sky}44`,color:G67_P.sky,fontSize:12,fontWeight:700}}>
        💡 {q.exp}
      </div>}
    </div>
    {sel!==null&&<button className="pop" onClick={next} style={{width:"100%",padding:"12px 0",borderRadius:13,
      border:"none",background:`linear-gradient(90deg,${m.color},${G67_P.accent})`,
      color:"#fff",fontWeight:900,fontSize:14,cursor:"pointer"}}>
      {idx+1>=qs.length?"🏆 Ver Resultados":"Siguiente →"}
    </button>}
  </div>;
};

// ══════════════════════════════════════════════════════════════
//  WORD MATCH MECHANIC (misión 2)
// ══════════════════════════════════════════════════════════════
const G67_WordMatchMechanic=({m,onComplete,onRecordAnswer})=>{
  const pairs=G67_WORDMATCH_PAIRS;
  const [selWord,setSelWord]=useState(null);
  const [selMatch,setSelMatch]=useState(null);
  const [matched,setMatched]=useState({});
  const [wrong,setWrong]=useState([]);
  const [phase,setPhase]=useState("game"); // "game" | "text"
  const shuffled=useRef([...pairs].sort(()=>Math.random()-.5)).current;
  useEffect(()=>{
    if(selWord!==null&&selMatch!==null){
      const ok=pairs[selWord].match===shuffled[selMatch].match;
      if(ok){
        const nm={...matched,[selWord]:selMatch};setMatched(nm);
        m.questions.slice(0,1).forEach(q=>onRecordAnswer(q.id,true,q));
        if(Object.keys(nm).length===pairs.length)setTimeout(()=>setPhase("text"),600);
      }else{
        setWrong([selWord+"w",selMatch+"m"]);
        setTimeout(()=>setWrong([]),700);
        m.questions.slice(0,1).forEach(q=>onRecordAnswer(q.id,false,q));
      }
      setTimeout(()=>{setSelWord(null);setSelMatch(null);},300);
    }
  },[selWord,selMatch]);

  if(phase==="text") return(
    <div className="slideUp">
      <div style={{background:`${m.color}18`,borderRadius:14,padding:"10px 15px",marginBottom:12,
        display:"flex",alignItems:"center",gap:8}}>
        <span style={{fontSize:22}}>📖</span>
        <div>
          <div style={{fontWeight:900,color:m.color,fontSize:14}}>¡Todas conectadas! Ahora lee el texto</div>
          <div style={{fontSize:11,color:G67_P.muted}}>Encontrarás las palabras del juego en el párrafo</div>
        </div>
      </div>
      <div style={{background:G67_P.card,borderRadius:17,padding:18,marginBottom:14,
        border:`1.5px solid ${G67_P.border}`,boxShadow:"0 2px 10px rgba(0,0,0,.05)"}}>
        <p style={{color:G67_P.text,lineHeight:1.9,fontSize:15,margin:0}}>{m.text}</p>
      </div>
      <button onClick={()=>onComplete(Object.keys(matched).length,pairs.length)}
        style={{width:"100%",padding:"12px 0",borderRadius:15,border:"none",
          background:`linear-gradient(90deg,${m.color},${G67_P.accent})`,
          color:"#fff",fontWeight:900,fontSize:14,cursor:"pointer"}}>
        🏆 Ver mis Resultados
      </button>
    </div>
  );

  return <div className="slideUp">
    <div style={{background:m.bg,borderRadius:13,padding:"9px 13px",marginBottom:14,
      display:"flex",justifyContent:"space-between",alignItems:"center"}}>
      <span style={{fontWeight:800,color:m.color,fontSize:13}}>🔤 Word Match — {m.name}</span>
      <span style={{fontSize:11,color:G67_P.muted}}>{Object.keys(matched).length}/{pairs.length} conectadas</span>
    </div>
    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:11}}>
      <div>
        <div style={{fontSize:10,fontWeight:700,color:G67_P.muted,marginBottom:7,textAlign:"center"}}>PALABRAS</div>
        {pairs.map((p,i)=>{
          const isM=matched[i]!==undefined,isSel=selWord===i,isW=wrong.includes(i+"w");
          return <div key={i} onClick={()=>!isM&&setSelWord(isSel?null:i)}
            className={isW?"shake":""}
            style={{padding:"11px 10px",borderRadius:11,marginBottom:7,cursor:isM?"default":"pointer",
              background:isM?"#DCFCE7":isSel?`${m.color}22`:"#fff",
              border:`2px solid ${isM?"#22C55E":isSel?m.color:isW?G67_P.warn:G67_P.border}`,
              fontWeight:700,color:G67_P.text,fontSize:14,textAlign:"center",transition:"all .2s"}}>
            {isM?"✅ ":"🔵 "}{p.word}
          </div>;
        })}
      </div>
      <div>
        <div style={{fontSize:10,fontWeight:700,color:G67_P.muted,marginBottom:7,textAlign:"center"}}>DEFINICIONES</div>
        {shuffled.map((p,i)=>{
          const isM=Object.values(matched).includes(i),isSel=selMatch===i,isW=wrong.includes(i+"m");
          return <div key={i} onClick={()=>!isM&&setSelMatch(isSel?null:i)}
            className={isW?"shake":""}
            style={{padding:"11px 10px",borderRadius:11,marginBottom:7,cursor:isM?"default":"pointer",
              background:isM?"#DCFCE7":isSel?`${m.color}22`:"#fff",
              border:`2px solid ${isM?"#22C55E":isSel?m.color:isW?G67_P.warn:G67_P.border}`,
              fontWeight:600,color:G67_P.text,fontSize:12,textAlign:"center",transition:"all .2s"}}>
            {isM?"✅ ":""}{p.match}
          </div>;
        })}
      </div>
    </div>
    <div style={{marginTop:12,background:`${G67_P.sky}12`,borderRadius:11,padding:"8px 12px",
      fontSize:12,color:G67_P.sky,fontWeight:700}}>
      💡 Toca una palabra y luego su definición para conectarlas.
    </div>
  </div>;
};

// ══════════════════════════════════════════════════════════════
//  DRAG-DROP MECHANIC (misión 3)
// ══════════════════════════════════════════════════════════════
const G67_DragDropMechanic=({m,onComplete,onRecordAnswer})=>{
  const items=G67_DRAGDROP_ITEMS;
  const [placements,setPlacements]=useState({});
  const [feedback,setFeedback]=useState({});
  const [selItem,setSelItem]=useState(null);
  const [phase,setPhase]=useState("game");
  const place=cat=>{
    if(!selItem)return;
    const ok=items.find(i=>i.id===selItem)?.category===cat;
    const np={...placements,[selItem]:cat};
    const nf={...feedback,[selItem]:ok};
    setPlacements(np);setFeedback(nf);
    m.questions.slice(0,1).forEach(q=>onRecordAnswer(q.id,ok,q));
    setSelItem(null);
    if(Object.keys(np).length===items.length)setTimeout(()=>setPhase("text"),600);
  };
  if(phase==="text")return(
    <div className="slideUp">
      <div style={{background:`${m.color}18`,borderRadius:14,padding:"10px 15px",marginBottom:12,
        display:"flex",alignItems:"center",gap:8}}>
        <span style={{fontSize:22}}>📖</span>
        <div>
          <div style={{fontWeight:900,color:m.color,fontSize:14}}>¡Clasificado! Ahora lee el texto</div>
          <div style={{fontSize:11,color:G67_P.muted}}>Encontrarás las palabras clasificadas en el párrafo</div>
        </div>
      </div>
      <div style={{background:G67_P.card,borderRadius:17,padding:18,marginBottom:14,
        border:`1.5px solid ${G67_P.border}`,boxShadow:"0 2px 10px rgba(0,0,0,.05)"}}>
        <p style={{color:G67_P.text,lineHeight:1.9,fontSize:15,margin:0}}>{m.text}</p>
      </div>
      <button onClick={()=>onComplete(Object.values(feedback).filter(Boolean).length,items.length)}
        style={{width:"100%",padding:"12px 0",borderRadius:15,border:"none",
          background:`linear-gradient(90deg,${m.color},${G67_P.accent})`,
          color:"#fff",fontWeight:900,fontSize:14,cursor:"pointer"}}>
        🏆 Ver mis Resultados
      </button>
    </div>
  );
  const unplaced=items.filter(i=>!placements[i.id]);
  return <div className="slideUp">
    <div style={{background:m.bg,borderRadius:13,padding:"9px 13px",marginBottom:13,
      display:"flex",justifyContent:"space-between"}}>
      <span style={{fontWeight:800,color:m.color,fontSize:13}}>🎯 Clasificar — {m.name}</span>
      <span style={{fontSize:11,color:G67_P.muted}}>{Object.keys(placements).length}/{items.length}</span>
    </div>
    <div style={{marginBottom:13}}>
      <div style={{fontSize:10,fontWeight:700,color:G67_P.muted,marginBottom:7}}>Toca para seleccionar:</div>
      <div style={{display:"flex",flexWrap:"wrap",gap:7}}>
        {unplaced.map(item=>(
          <div key={item.id} onClick={()=>setSelItem(selItem===item.id?null:item.id)}
            style={{padding:"9px 14px",borderRadius:20,cursor:"pointer",fontWeight:700,fontSize:14,
              background:selItem===item.id?`${m.color}22`:"#fff",
              border:`2px solid ${selItem===item.id?m.color:G67_P.border}`,color:G67_P.text,transition:"all .2s"}}>
            {selItem===item.id?"👉 ":""}{item.word}
          </div>
        ))}
        {!unplaced.length&&<div style={{color:G67_P.primary,fontWeight:700,fontSize:13}}>✅ ¡Todos clasificados!</div>}
      </div>
    </div>
    <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:9,marginBottom:12}}>
      {G67_DD_CATEGORIES.map(cat=>{
        const placed=items.filter(i=>placements[i.id]===cat);
        return <div key={cat} onClick={()=>place(cat)}
          style={{background:selItem?"#F0FDF4":"#F8FAFC",border:`2px dashed ${selItem?m.color:G67_P.border}`,
            borderRadius:13,padding:"8px 6px",cursor:selItem?"pointer":"default",minHeight:80,transition:"all .2s"}}>
          <div style={{fontSize:11,fontWeight:800,color:m.color,marginBottom:6,textAlign:"center"}}>{cat}</div>
          {placed.map(i=>(
            <div key={i.id} style={{padding:"4px 6px",borderRadius:7,marginBottom:3,textAlign:"center",
              background:feedback[i.id]?"#DCFCE7":"#FEE2E2",
              border:`1.5px solid ${feedback[i.id]?"#22C55E":G67_P.warn}`,fontSize:11,fontWeight:700}}>
              {feedback[i.id]?"✅":"❌"} {i.word}
            </div>
          ))}
        </div>;
      })}
    </div>
    {selItem&&<div style={{textAlign:"center",fontSize:12,color:m.color,fontWeight:700}}>
      👆 Toca una categoría: <b>{items.find(i=>i.id===selItem)?.word}</b>
    </div>}
  </div>;
};

// ══════════════════════════════════════════════════════════════
//  FILL-IN-THE-BLANK MECHANIC (misión 4 — nivel más avanzado)
// ══════════════════════════════════════════════════════════════
const G67_FillBlankMechanic=({m,onComplete,onRecordAnswer})=>{
  const items=G67_FILLBLANK_ITEMS;
  const [phase,setPhase]=useState("textIntro"); // textIntro | game | done
  const [idx,setIdx]=useState(0);
  const [sel,setSel]=useState(null);
  const [score,setScore]=useState(0);
  const [speaking,setSpeaking]=useState(false);
  const speak=(rate=0.85)=>{
    if(!("speechSynthesis"in window))return;
    window.speechSynthesis.cancel();
    const u=new SpeechSynthesisUtterance(m.text);u.lang="en-US";u.rate=rate;
    u.onstart=()=>setSpeaking(true);u.onend=()=>setSpeaking(false);
    window.speechSynthesis.speak(u);
  };
  const handlePick=opt=>{
    if(sel!==null)return;
    setSel(opt);
    const ok=opt===items[idx].answer;
    if(ok)setScore(s=>s+1);
    m.questions.slice(idx,idx+1).forEach(q=>onRecordAnswer(q.id,ok,q));
  };
  const next=()=>{
    setSel(null);
    if(idx+1>=items.length)setPhase("done");else setIdx(i=>i+1);
  };

  if(phase==="textIntro") return (
    <div className="slideUp">
      <div style={{background:`${m.color}18`,borderRadius:14,padding:"10px 15px",marginBottom:12,
        display:"flex",alignItems:"center",gap:8}}>
        <span style={{fontSize:22}}>📖</span>
        <div>
          <div style={{fontWeight:900,color:m.color,fontSize:14}}>Lee el texto primero</div>
          <div style={{fontSize:11,color:G67_P.muted}}>Luego completarás oraciones con palabras del texto</div>
        </div>
      </div>
      <div style={{background:G67_P.card,borderRadius:17,padding:18,marginBottom:14,
        border:`1.5px solid ${G67_P.border}`,boxShadow:"0 2px 10px rgba(0,0,0,.05)"}}>
        <p style={{color:G67_P.text,lineHeight:1.9,fontSize:15,margin:0}}>{m.text}</p>
      </div>
      <div style={{display:"flex",gap:7,marginBottom:14}}>
        <button onClick={()=>speak(0.85)} style={{flex:1,padding:"8px 0",borderRadius:12,border:"none",
          background:speaking?`${m.color}22`:m.bg,color:m.color,fontWeight:700,cursor:"pointer",fontSize:12}}>
          {speaking?"🔊 Reproduciendo...":"🔊 Escuchar texto"}
        </button>
        <button onClick={()=>speak(0.6)} style={{flex:1,padding:"8px 0",borderRadius:12,border:"none",
          background:"#F0F9FF",color:G67_P.sky,fontWeight:700,cursor:"pointer",fontSize:12}}>🐢 Lento</button>
      </div>
      <button onClick={()=>setPhase("game")} style={{width:"100%",padding:"12px 0",borderRadius:15,
        border:"none",background:`linear-gradient(90deg,${m.color},${G67_P.accent})`,
        color:"#fff",fontWeight:900,fontSize:14,cursor:"pointer"}}>✏️ ¡Completar oraciones!</button>
    </div>
  );

  if(phase==="done")return <G67_ResultScreen m={m} score={score} total={items.length} onContinue={()=>onComplete(score,items.length)}/>;

  const it=items[idx];
  const parts=it.sentence.split("___");
  return <div className="slideUp">
    <div style={{background:m.bg,borderRadius:13,padding:"9px 13px",marginBottom:14,
      display:"flex",justifyContent:"space-between",alignItems:"center"}}>
      <span style={{fontWeight:800,color:m.color,fontSize:13}}>✏️ Completa — {m.name}</span>
      <span style={{fontSize:11,color:G67_P.muted}}>{idx+1}/{items.length}</span>
    </div>
    <div style={{background:G67_P.card,borderRadius:17,padding:20,marginBottom:14,
      border:`1.5px solid ${G67_P.border}`,textAlign:"center"}}>
      <p style={{fontSize:18,fontWeight:800,color:G67_P.text,lineHeight:1.8,margin:0}}>
        {parts[0]}
        <span style={{display:"inline-block",minWidth:70,borderBottom:`3px solid ${m.color}`,
          color:sel?(sel===it.answer?G67_P.accent:G67_P.warn):m.color,fontWeight:900,padding:"0 6px",fontSize:20}}>
          {sel||"_____"}
        </span>
        {parts[1]}
      </p>
    </div>
    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:9,marginBottom:14}}>
      {it.options.map((opt,i)=>{
        let bg="#fff",border=G67_P.border,col=G67_P.text;
        if(sel!==null){
          if(opt===it.answer){bg="#DCFCE7";border="#22C55E";col="#065F46";}
          else if(opt===sel){bg="#FEE2E2";border=G67_P.warn;col="#991B1B";}
        }
        return <button key={i} onClick={()=>handlePick(opt)} disabled={sel!==null}
          style={{padding:"14px 10px",borderRadius:13,border:`2px solid ${border}`,
            background:bg,color:col,fontWeight:800,fontSize:15,cursor:sel!==null?"default":"pointer",transition:"all .2s"}}>
          {opt}
        </button>;
      })}
    </div>
    {sel!==null&&<div className="slideUp" style={{marginBottom:10,padding:"8px 12px",borderRadius:10,
      background:`${G67_P.sky}18`,border:`1.5px solid ${G67_P.sky}44`,color:G67_P.sky,fontSize:12,fontWeight:700}}>
      {sel===it.answer?"✅ ¡Correcto!":"❌ La respuesta correcta es: "+it.answer}
    </div>}
    {sel!==null&&<button className="pop" onClick={next} style={{width:"100%",padding:"12px 0",borderRadius:13,
      border:"none",background:`linear-gradient(90deg,${m.color},${G67_P.accent})`,
      color:"#fff",fontWeight:900,fontSize:14,cursor:"pointer"}}>
      {idx+1>=items.length?"🏆 Ver Resultados":"Siguiente →"}
    </button>}
  </div>;
};


const G67_ResultScreen=({m,score,total,onContinue})=>{
  const pct=Math.round((score/total)*100);
  const win=pct>=60;
  const stars=pct>=85?3:pct>=60?2:1;
  return <div className="pop" style={{textAlign:"center",padding:"22px 0"}}>
    {win&&<G67_Fireworks/>}
    <div style={{fontSize:64,marginBottom:7,display:"inline-block"}}>{win?"🏆":"💪"}</div>
    <h2 style={{fontWeight:900,fontSize:22,color:G67_P.text,marginBottom:4}}>
      {pct>=85?"¡Campeón! 🎉":pct>=60?"¡Muy bien! 👍":"¡Sigue practicando! 💪"}
    </h2>
    <div style={{display:"flex",justifyContent:"center",gap:4,marginBottom:14,fontSize:26}}>
      {Array.from({length:3}).map((_,i)=><span key={i} style={{opacity:i<stars?1:.2}}>⭐</span>)}
    </div>
    <div style={{background:m.bg,border:`2px solid ${m.color}44`,borderRadius:17,
      padding:16,display:"inline-block",minWidth:180,marginBottom:16}}>
      <div style={{fontSize:36,fontWeight:900,color:m.color}}>{score}/{total}</div>
      <div style={{color:G67_P.muted,fontSize:12,marginBottom:5}}>Respuestas correctas</div>
      {win&&<div style={{fontSize:11,fontWeight:700,color:G67_P.gold}}>🎁 {m.reward}</div>}
      <div style={{fontSize:11,fontWeight:700,color:G67_P.gold,marginTop:3}}>🪙 +{win?m.coins:Math.round(m.coins*.3)}</div>
      <div style={{fontSize:11,fontWeight:700,color:G67_P.primary,marginTop:2}}>+{win?m.xp:Math.round(m.xp*.4)} XP</div>
    </div>
    <div style={{display:"flex",gap:9,justifyContent:"center"}}>
      <button onClick={()=>onContinue(win)} style={{padding:"9px 24px",borderRadius:13,border:"none",
        background:`linear-gradient(90deg,${m.color},${G67_P.accent})`,color:"#fff",
        fontWeight:900,cursor:"pointer",fontSize:14}}>
        {win?"🏆 ¡Reclamar premio!":"🔄 Intentar de nuevo"}
      </button>
    </div>
  </div>;
};

// ══════════════════════════════════════════════════════════════
//  MISSION DETAIL
// ══════════════════════════════════════════════════════════════
const G67_MissionDetail=({mission,onBack,onEarnReward,onRecordAnswer})=>{
  const [view,setView]=useState("intro");
  const handleComplete=(score,total)=>onEarnReward(mission,score/total>=0.6);
  if(view==="intro")return <G67_BossIntro m={mission} onStart={()=>setView("mechanic")} onBack={onBack}/>;
  if(view==="mechanic"){
    const props={m:mission,onComplete:handleComplete,onRecordAnswer};
    if(mission.mechanic==="quiz")return <G67_QuizMechanic {...props}/>;
    if(mission.mechanic==="wordmatch")return <G67_WordMatchMechanic {...props}/>;
    if(mission.mechanic==="dragdrop")return <G67_DragDropMechanic {...props}/>;
    if(mission.mechanic==="fillblank")return <G67_FillBlankMechanic {...props}/>;
  }
  return null;
};

// ══════════════════════════════════════════════════════════════
//  RANKING
// ══════════════════════════════════════════════════════════════
const G67_RankingPanel=({playerName})=>{
  const players=[...G67_loadPlayers()].sort((a,b)=>(b.xp||0)-(a.xp||0));
  const myRank=players.findIndex(p=>p.name===playerName)+1;
  return <div className="slideUp">
    <h2 style={{fontWeight:900,fontSize:20,color:G67_P.text,marginBottom:13,textAlign:"center"}}>🏆 Ranking — G6 y G7</h2>
    {myRank>0&&<div style={{background:`${G67_P.primary}12`,border:`2px solid ${G67_P.primary}33`,borderRadius:13,
      padding:"9px 15px",marginBottom:13,textAlign:"center"}}>
      Tu posición: <span style={{fontWeight:900,fontSize:21,color:G67_P.primary}}>#{myRank}</span>
      <span style={{color:G67_P.muted,fontSize:12}}> de {players.length}</span>
    </div>}
    <div style={{display:"flex",flexDirection:"column",gap:6}}>
      {players.map((p,i)=>(
        <div key={p.name} style={{display:"flex",alignItems:"center",gap:9,padding:"10px 14px",borderRadius:12,
          background:p.name===playerName?`${G67_P.primary}12`:G67_P.card,
          border:`1.5px solid ${p.name===playerName?G67_P.primary:i<3?"#F59E0B33":G67_P.border}`}}>
          <span style={{fontSize:15,fontWeight:900,width:28,textAlign:"center",
            color:i===0?G67_P.gold:i===1?"#94A3B8":i===2?"#CD7F32":G67_P.muted}}>
            {i===0?"🥇":i===1?"🥈":i===2?"🥉":`#${i+1}`}
          </span>
          <span style={{flex:1,fontWeight:700,color:G67_P.text,fontSize:13}}>{p.name}</span>
          <span style={{fontWeight:900,color:G67_P.gold,fontSize:12}}>🪙 {p.coins||0}</span>
          <span style={{fontWeight:900,color:G67_P.primary,fontSize:12}}>⭐ {p.xp||0}</span>
        </div>
      ))}
      {!players.length&&<div style={{textAlign:"center",padding:32,color:G67_P.muted}}>¡Sé el primero! 🌟</div>}
    </div>
  </div>;
};

// ══════════════════════════════════════════════════════════════
//  ADMIN LOGIN
// ══════════════════════════════════════════════════════════════
const G67_AdminLogin=({onSuccess,onCancel})=>{
  const [pw,setPw]=useState("");const [err,setErr]=useState(false);
  const submit=()=>{if(pw===G67_TEACHER_PASSWORD){setErr(false);onSuccess();}else{setErr(true);setPw("");}};
  return <div style={{position:"fixed",inset:0,background:"rgba(30,41,59,.55)",zIndex:5000,
    display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
    <div className="pop" style={{background:G67_P.card,borderRadius:21,padding:28,maxWidth:330,width:"100%",
      boxShadow:"0 8px 44px rgba(34,197,94,.2)"}}>
      <div style={{textAlign:"center",marginBottom:20}}>
        <div style={{fontSize:42,marginBottom:7}}>🔐</div>
        <h2 style={{margin:0,fontWeight:900,color:G67_P.text,fontSize:18}}>Panel Docente</h2>
        <p style={{color:G67_P.muted,fontSize:11,marginTop:5}}>Grados 6° y 7° • I.E. La Amistad</p>
      </div>
      <input type="password" value={pw} onChange={e=>setPw(e.target.value)}
        onKeyDown={e=>e.key==="Enter"&&submit()} placeholder="Contraseña..."
        style={{width:"100%",padding:"11px 14px",borderRadius:12,border:`2px solid ${err?G67_P.warn:G67_P.border}`,
          fontSize:14,fontWeight:700,outline:"none",color:G67_P.text,marginBottom:7}}/>
      {err&&<p style={{color:G67_P.warn,fontSize:11,fontWeight:700,margin:"0 0 9px"}}>⚠️ Contraseña incorrecta</p>}
      <div style={{display:"flex",gap:7,marginTop:5}}>
        <button onClick={onCancel} style={{flex:1,padding:"9px 0",borderRadius:12,border:`2px solid ${G67_P.border}`,
          background:"#fff",color:G67_P.muted,fontWeight:700,cursor:"pointer"}}>Cancelar</button>
        <button onClick={submit} style={{flex:1,padding:"9px 0",borderRadius:12,border:"none",
          background:G67_P.primary,color:"#fff",fontWeight:900,cursor:"pointer"}}>Entrar</button>
      </div>
    </div>
  </div>;
};

// ══════════════════════════════════════════════════════════════
//  ADMIN PANEL
// ══════════════════════════════════════════════════════════════
const G67_AdminPanel=({onClose})=>{
  const [players,setPlayers]=useState(G67_loadPlayers);
  const [tab,setTab]=useState("stats");
  const allQ=G67_MISSIONS.flatMap(m=>m.questions);
  const qStats=allQ.map(q=>{
    const attempts=players.map(p=>(p.answers||{})[q.id]).filter(Boolean);
    const correct=attempts.filter(a=>a.correct).length;
    const pct=attempts.length?Math.round((correct/attempts.length)*100):null;
    return{q,attempts:attempts.length,correct,pct};
  });
  // ICFES-style domain breakdown
  const DOMAINS=["Vocabulario","Gramática","Semántica"];
  const domainStats=DOMAINS.map(dom=>{
    const qs=qStats.filter(s=>(s.q.domain||"Semántica")===dom&&s.pct!==null);
    const avg=qs.length?Math.round(qs.reduce((s,r)=>s+r.pct,0)/qs.length):null;
    return{domain:dom,avg,count:qs.length};
  });
  const LEVELS=["Pre A1","A1"];
  const levelStats=LEVELS.map(lvl=>{
    const qs=qStats.filter(s=>s.q.lvl===lvl&&s.pct!==null);
    const avg=qs.length?Math.round(qs.reduce((s,r)=>s+r.pct,0)/qs.length):null;
    return{lvl,avg};
  });
  const domainLevelMatrix=DOMAINS.map(dom=>({
    domain:dom,
    levels:LEVELS.map(lvl=>{
      const qs=qStats.filter(s=>(s.q.domain||"Semántica")===dom&&s.q.lvl===lvl&&s.pct!==null);
      const avg=qs.length?Math.round(qs.reduce((s,r)=>s+r.pct,0)/qs.length):null;
      return{lvl,avg};
    })
  }));
  const weakSkills=qStats.filter(s=>s.pct!==null&&s.pct<60).sort((a,b)=>a.pct-b.pct).slice(0,6);
  const strongSkills=qStats.filter(s=>s.pct!==null&&s.pct>=80).slice(0,4);
  const alerts=players.filter(p=>{
    const ans=Object.values(p.answers||{});
    if(!ans.length)return false;
    return Math.round((ans.filter(a=>a.correct).length/ans.length)*100)<50;
  });
  const exportCSV=()=>{
    if(!players.length){alert("Sin datos.");return;}
    const header=`Nombre,XP,Monedas,Misiones,Total Correctas,% Global,Ultima Sesion`;
    const rows=players.map(p=>{
      const ans=Object.values(p.answers||{});const tc=ans.filter(a=>a.correct).length;
      const pct=ans.length?Math.round((tc/ans.length)*100):0;
      return`"${p.name}",${p.xp||0},${p.coins||0},${(p.completedMissions||[]).length},${tc},${pct}%,"${p.lastSeen||""}"`;
    });
    const csv="\uFEFF"+[header,...rows].join("\n");
    const blob=new Blob([csv],{type:"text/csv;charset=utf-8;"});
    const url=URL.createObjectURL(blob);const a=document.createElement("a");
    a.href=url;a.download=`Guardians_G67_${new Date().toLocaleDateString("es-CO").replace(/\//g,"-")}.csv`;
    document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);
  };
  return <div style={{minHeight:"100vh",background:G67_P.bg,padding:13}}>
    <style>{G67_CSS}</style>
    <div style={{maxWidth:860,margin:"0 auto"}}>
      <div style={{display:"flex",alignItems:"center",gap:11,marginBottom:14,
        background:G67_P.card,borderRadius:17,padding:"13px 17px",
        boxShadow:"0 2px 13px rgba(34,197,94,.08)"}}>
        <div style={{width:44,height:44,borderRadius:"50%",flexShrink:0,
          background:`linear-gradient(135deg,${G67_P.primary},${G67_P.accent})`,
          display:"flex",alignItems:"center",justifyContent:"center",fontSize:20}}>👨‍🏫</div>
        <div style={{flex:1}}>
          <div style={{fontWeight:900,fontSize:15,color:G67_P.text}}>English Guardians G6-G7 — Panel Docente</div>
          <div style={{fontSize:11,color:G67_P.muted}}>I.E. La Amistad • Grados 6° y 7° • Mg. Anderson</div>
        </div>
        <button onClick={onClose} style={{background:"#FEE2E2",border:"none",borderRadius:9,
          padding:"6px 13px",color:G67_P.warn,fontWeight:700,cursor:"pointer",fontSize:12}}>✕ Salir</button>
      </div>
      <div style={{display:"flex",gap:6,marginBottom:13,flexWrap:"wrap"}}>
        {[{id:"stats",l:"📊 Estadísticas"},{id:"students",l:"👥 Estudiantes"},{id:"questions",l:"📋 Preguntas"},{id:"export",l:"📤 Exportar"}].map(t=>(
          <button key={t.id} onClick={()=>setTab(t.id)} style={{padding:"7px 15px",borderRadius:12,border:"none",
            background:tab===t.id?G67_P.primary:"#fff",color:tab===t.id?"#fff":G67_P.muted,
            fontWeight:700,cursor:"pointer",fontSize:12,
            boxShadow:tab===t.id?`0 2px 9px ${G67_P.primary}44`:"0 1px 3px rgba(0,0,0,.05)"}}>
            {t.l}
          </button>
        ))}
      </div>

      {/* STATS */}
      {tab==="stats"&&<div className="slideUp">
        <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",gap:9,marginBottom:13}}>
          {[{v:players.length,l:"Estudiantes",c:G67_P.primary,i:"👥"},
            {v:`${qStats.filter(s=>s.pct!==null).length?Math.round(qStats.filter(s=>s.pct!==null).reduce((s,r)=>s+r.pct,0)/qStats.filter(s=>s.pct!==null).length):0}%`,l:"Aciertos global",c:G67_P.accent,i:"🎯"},
            {v:players.reduce((s,p)=>s+Object.values(p.answers||{}).filter(a=>a.correct).length,0),l:"Correctas totales",c:G67_P.primary,i:"✅"},
            {v:alerts.length,l:"En riesgo",c:G67_P.warn,i:"🚨"},
          ].map((s,i)=>(
            <div key={i} style={{background:G67_P.card,borderRadius:13,padding:"13px 15px",border:`1.5px solid ${s.c}33`}}>
              <div style={{fontSize:19,marginBottom:3}}>{s.i}</div>
              <div style={{fontWeight:900,fontSize:21,color:s.c}}>{s.v}</div>
              <div style={{fontSize:11,color:G67_P.muted}}>{s.l}</div>
            </div>
          ))}
        </div>

        {/* ANÁLISIS ICFES — Vocabulario / Gramática / Semántica */}
        <div style={{background:G67_P.card,borderRadius:17,padding:17,marginBottom:13,border:`1.5px solid ${G67_P.border}`}}>
          <div style={{fontWeight:800,fontSize:13,color:G67_P.text,marginBottom:3}}>🧠 Análisis por Competencia (estilo ICFES)</div>
          <p style={{fontSize:11,color:G67_P.muted,margin:"0 0 13px"}}>Identificar en qué competencia específica fallan los estudiantes.</p>
          <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:9,marginBottom:14}}>
            {domainStats.map(d=>(
              <div key={d.domain} style={{textAlign:"center",padding:"12px 6px",borderRadius:13,
                background:d.avg===null?"#F8FAFC":d.avg>=70?`${G67_P.accent}12`:d.avg>=50?`${G67_P.gold}12`:`${G67_P.warn}12`,
                border:`1.5px solid ${d.avg===null?G67_P.border:d.avg>=70?G67_P.accent:d.avg>=50?G67_P.gold:G67_P.warn}44`}}>
                <div style={{fontSize:16,fontWeight:900,
                  color:d.avg===null?G67_P.muted:d.avg>=70?G67_P.accent:d.avg>=50?G67_P.gold:G67_P.warn}}>
                  {d.avg===null?"—":d.avg+"%"}
                </div>
                <div style={{fontSize:10,fontWeight:700,color:G67_P.muted,marginTop:3}}>{d.domain}</div>
              </div>
            ))}
          </div>
          <div style={{fontSize:11,fontWeight:700,color:G67_P.muted,marginBottom:8}}>Desglose por Nivel CEFR</div>
          <div style={{overflowX:"auto",marginBottom:14}}>
            <table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}>
              <thead><tr style={{background:`${G67_P.primary}12`}}>
                <th style={{padding:"6px 9px",textAlign:"left",fontWeight:700,color:G67_P.primary}}>Competencia</th>
                {LEVELS.map(l=>(<th key={l} style={{padding:"6px 9px",fontWeight:700,color:G67_P.primary}}>{l}</th>))}
              </tr></thead>
              <tbody>
                {domainLevelMatrix.map((row,i)=>(
                  <tr key={row.domain} style={{background:i%2?"#fff":"#F0FDF4"}}>
                    <td style={{padding:"7px 9px",fontWeight:700,color:G67_P.text}}>{row.domain}</td>
                    {row.levels.map(lv=>(
                      <td key={lv.lvl} style={{padding:"7px 9px",textAlign:"center",fontWeight:800,
                        color:lv.avg===null?G67_P.muted:lv.avg>=70?G67_P.accent:lv.avg>=50?G67_P.gold:G67_P.warn}}>
                        {lv.avg===null?"—":lv.avg+"%"}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
            <div style={{background:"#ECFDF5",borderRadius:13,padding:12,border:"1.5px solid #22C55E33"}}>
              <div style={{fontWeight:800,fontSize:12,color:G67_P.primary,marginBottom:8}}>✅ Fortalezas</div>
              {strongSkills.length?strongSkills.map(s=>(
                <div key={s.q.id} style={{fontSize:10,color:"#065F46",marginBottom:6}}>
                  <span style={{fontWeight:700}}>{s.q.domain||"Semántica"}</span> ({s.q.lvl}) — {s.pct}%
                  <div style={{color:G67_P.muted,fontSize:9}}>{s.q.skill}</div>
                </div>
              )):<div style={{fontSize:11,color:G67_P.muted}}>Sin datos suficientes</div>}
            </div>
            <div style={{background:"#FEF2F2",borderRadius:13,padding:12,border:"1.5px solid #EF444433"}}>
              <div style={{fontWeight:800,fontSize:12,color:G67_P.warn,marginBottom:8}}>❌ Debilidades</div>
              {weakSkills.length?weakSkills.map(s=>(
                <div key={s.q.id} style={{fontSize:10,color:"#991B1B",marginBottom:6}}>
                  <span style={{fontWeight:700}}>{s.q.domain||"Semántica"}</span> ({s.q.lvl}) — {s.pct}%
                  <div style={{color:G67_P.muted,fontSize:9}}>{s.q.skill}</div>
                </div>
              )):<div style={{fontSize:11,color:G67_P.muted}}>Sin datos suficientes</div>}
            </div>
          </div>
        </div>

        <div style={{background:G67_P.card,borderRadius:17,padding:17,marginBottom:13,border:`1.5px solid ${G67_P.border}`}}>
          <div style={{fontWeight:800,fontSize:13,color:G67_P.text,marginBottom:11}}>🗺️ Progreso por Misión</div>
          {G67_MISSIONS.map(m=>{
            const mQ=m.questions;
            const mVals=mQ.map(q=>{
              const a=players.map(p=>(p.answers||{})[q.id]).filter(Boolean);
              return a.length?Math.round((a.filter(x=>x.correct).length/a.length)*100):null;
            }).filter(v=>v!==null);
            const avg=mVals.length?Math.round(mVals.reduce((s,v)=>s+v,0)/mVals.length):null;
            const comp=players.filter(p=>(p.completedMissions||[]).includes(m.id)).length;
            return <div key={m.id} style={{marginBottom:11}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:3}}>
                <span style={{fontSize:13,fontWeight:700,color:G67_P.text}}>{m.emoji} {m.name}</span>
                <span style={{fontSize:11,color:G67_P.muted}}>{comp} completaron • {avg!==null?avg+"%":"sin datos"}</span>
              </div>
              <div style={{height:7,borderRadius:7,background:"#BBF7D0",overflow:"hidden"}}>
                <div style={{height:"100%",borderRadius:7,
                  background:avg===null?G67_P.muted:avg>=70?G67_P.primary:avg>=50?G67_P.gold:G67_P.warn,
                  width:`${avg||0}%`,transition:"width .8s"}}/>
              </div>
            </div>;
          })}
        </div>
        <div style={{background:G67_P.card,borderRadius:17,padding:17,border:`1.5px solid ${G67_P.border}`}}>
          <div style={{fontWeight:800,fontSize:13,color:G67_P.text,marginBottom:11}}>🔥 Heatmap de Preguntas</div>
          <div style={{display:"flex",gap:4,flexWrap:"wrap"}}>
            {qStats.map(s=>{
              const bg=s.pct===null?"#F1F5F9":s.pct>=80?"#DCFCE7":s.pct>=60?"#FEF9C3":s.pct>=40?"#FFEDD5":"#FEE2E2";
              const bc=s.pct===null?G67_P.border:s.pct>=80?"#22C55E":s.pct>=60?G67_P.gold:s.pct>=40?"#F97316":G67_P.warn;
              return <div key={s.q.id} style={{width:42,height:42,borderRadius:9,background:bg,
                border:`1.5px solid ${bc}`,display:"flex",flexDirection:"column",
                alignItems:"center",justifyContent:"center",gap:1}}>
                <span style={{fontSize:7,fontWeight:700,color:G67_P.muted}}>{s.q.id}</span>
                <span style={{fontSize:10,fontWeight:900,color:bc}}>{s.pct===null?"—":s.pct+"%"}</span>
              </div>;
            })}
          </div>
        </div>
      </div>}

      {/* STUDENTS */}
      {tab==="students"&&<div className="slideUp">
        {!players.length&&<div style={{textAlign:"center",padding:44,color:G67_P.muted,background:G67_P.card,borderRadius:17}}>
          <div style={{fontSize:42,marginBottom:9}}>👥</div><p style={{fontWeight:700}}>Sin estudiantes.</p>
        </div>}
        <div style={{display:"flex",flexDirection:"column",gap:7}}>
          {[...players].sort((a,b)=>(b.xp||0)-(a.xp||0)).map((p,i)=>{
            const ans=Object.values(p.answers||{});
            const tc=ans.filter(a=>a.correct).length;
            const pct=ans.length?Math.round((tc/ans.length)*100):0;
            return <div key={p.name} style={{background:G67_P.card,borderRadius:13,padding:"11px 15px",
              border:`1.5px solid ${G67_P.border}`,display:"flex",alignItems:"center",gap:9}}>
              <span style={{fontSize:14,fontWeight:900,width:27,color:i===0?G67_P.gold:i===1?"#94A3B8":i===2?"#CD7F32":G67_P.muted}}>
                {i===0?"🥇":i===1?"🥈":i===2?"🥉":`#${i+1}`}
              </span>
              <div style={{flex:1}}>
                <div style={{fontWeight:800,color:G67_P.text,fontSize:13}}>{p.name}</div>
                <div style={{fontSize:10,color:G67_P.muted}}>Nv.{Math.floor((p.xp||0)/120)+1} • {p.lastSeen}</div>
              </div>
              <div style={{textAlign:"right"}}>
                <div style={{fontWeight:900,color:G67_P.gold,fontSize:12}}>⭐ {p.xp||0} XP</div>
                <div style={{fontSize:10,fontWeight:700,
                  color:pct>=70?G67_P.primary:pct>=50?G67_P.gold:G67_P.warn}}>{pct}% • {(p.completedMissions||[]).length}/4 misiones</div>
              </div>
            </div>;
          })}
        </div>
        {alerts.length>0&&<div style={{background:"#FEF2F2",border:`2px solid ${G67_P.warn}44`,borderRadius:15,padding:14,marginTop:12}}>
          <div style={{fontWeight:800,fontSize:13,color:G67_P.warn,marginBottom:8}}>🚨 Estudiantes en Riesgo</div>
          {alerts.map(p=>{
            const ans=Object.values(p.answers||{});
            const pct=ans.length?Math.round((ans.filter(a=>a.correct).length/ans.length)*100):0;
            return <div key={p.name} style={{background:"#fff",borderRadius:10,padding:"8px 12px",marginBottom:6,
              display:"flex",justifyContent:"space-between"}}>
              <span style={{fontWeight:800,color:G67_P.text}}>{p.name}</span>
              <span style={{fontWeight:900,color:G67_P.warn}}>{pct}% aciertos</span>
            </div>;
          })}
        </div>}
      </div>}

      {/* QUESTIONS */}
      {tab==="questions"&&<div className="slideUp">
        {G67_MISSIONS.map(m=>(
          <div key={m.id} style={{background:G67_P.card,borderRadius:17,padding:17,marginBottom:13,border:`1.5px solid ${m.color}33`}}>
            <div style={{display:"flex",alignItems:"center",gap:9,marginBottom:12}}>
              <span style={{fontSize:24}}>{m.emoji}</span>
              <div>
                <div style={{fontWeight:900,color:G67_P.text,fontSize:14}}>{m.num}. {m.name}</div>
                <span style={{fontSize:10,background:`${m.color}18`,color:m.color,padding:"2px 7px",borderRadius:20,fontWeight:700}}>
                  {m.level} • {m.topic}
                </span>
              </div>
            </div>
            <div style={{fontSize:12,color:G67_P.muted,fontStyle:"italic",marginBottom:11,
              background:m.bg,borderRadius:9,padding:"7px 11px"}}>{m.text}</div>
            <div style={{overflowX:"auto"}}>
              <table style={{width:"100%",borderCollapse:"collapse",fontSize:11}}>
                <thead><tr style={{background:`${m.color}12`}}>
                  {["ID","Pregunta","Respuesta Correcta","Competencia","Nivel","Habilidad"].map(h=>(
                    <th key={h} style={{padding:"6px 7px",textAlign:"left",fontWeight:700,
                      color:m.color,borderBottom:`1.5px solid ${G67_P.border}`,whiteSpace:"nowrap"}}>{h}</th>
                  ))}
                </tr></thead>
                <tbody>
                  {m.questions.map((q,i)=>(
                    <tr key={q.id} style={{background:i%2===0?"#fff":"#F0FDF4"}}>
                      <td style={{padding:"6px 7px",fontWeight:800,color:G67_P.primary}}>{q.id}</td>
                      <td style={{padding:"6px 7px",color:G67_P.text,maxWidth:190,fontSize:11}}>{q.q}</td>
                      <td style={{padding:"6px 7px",fontWeight:700,color:G67_P.accent,whiteSpace:"nowrap",fontSize:11}}>
                        {["A","B","C","D"][q.ans]}. {q.opts[q.ans]}
                      </td>
                      <td style={{padding:"6px 7px",color:G67_P.purple,fontWeight:700,fontSize:10,whiteSpace:"nowrap"}}>{q.competency}</td>
                      <td style={{padding:"6px 7px",whiteSpace:"nowrap"}}>
                        <span style={{background:`${m.color}18`,color:m.color,padding:"2px 5px",borderRadius:20,fontWeight:700,fontSize:9}}>{q.lvl}</span>
                      </td>
                      <td style={{padding:"6px 7px",color:G67_P.muted,fontSize:10,maxWidth:170}}>{q.skill}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        ))}
      </div>}

      {/* EXPORT */}
      {tab==="export"&&<div className="slideUp">
        <div style={{background:G67_P.card,borderRadius:17,padding:17,border:`1.5px solid ${G67_P.border}`}}>
          <div style={{fontWeight:800,fontSize:14,color:G67_P.text,marginBottom:13}}>📤 Exportar datos</div>
          {[
            {icon:"📊",label:"Excel / CSV",sub:"Abre en Excel",c:G67_P.accent,fn:exportCSV},
            {icon:"🗂️",label:"JSON completo",sub:"Backup de datos",c:G67_P.primary,fn:()=>{
              const blob=new Blob([JSON.stringify({jugadores:players,fecha:new Date().toLocaleDateString("es-CO"),grado:"6-7"},null,2)],{type:"application/json"});
              const url=URL.createObjectURL(blob);const a=document.createElement("a");
              a.href=url;a.download="Guardians_G67.json";document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);
            }},
            {icon:"🖨️",label:"Imprimir PDF",sub:"Reporte visual",c:G67_P.purple,fn:()=>{
              const rows=[...players].sort((a,b)=>(b.xp||0)-(a.xp||0)).map((p,i)=>{
                const ans=Object.values(p.answers||{});const tc=ans.filter(a=>a.correct).length;
                const pct=ans.length?Math.round((tc/ans.length)*100):0;
                return`<tr><td>#${i+1} ${p.name}</td><td>${p.xp||0}</td><td>${pct}%</td><td>${(p.completedMissions||[]).length}/4</td></tr>`;
              }).join("");
              const html=`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Guardians G6-G7</title><style>body{font-family:Arial;padding:16px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #e2e8f0;padding:7px}th{background:#22c55e;color:#fff}</style></head><body><h2 style="color:#22c55e">🌟 English Guardians G6-G7</h2><p>I.E. La Amistad • Mg. Anderson • ${new Date().toLocaleDateString("es-CO")}</p><table><thead><tr><th>Estudiante</th><th>XP</th><th>% Aciertos</th><th>Misiones</th></tr></thead><tbody>${rows}</tbody></table><script>window.onload=()=>window.print();</script></body></html>`;
              const w=window.open("","_blank");w.document.write(html);w.document.close();
            }},
          ].map((o,i)=>(
            <button key={i} onClick={o.fn} style={{display:"flex",alignItems:"center",gap:11,
              width:"100%",padding:"12px 15px",borderRadius:13,marginBottom:8,
              border:`2px solid ${o.c}44`,background:`${o.c}0D`,color:G67_P.text,cursor:"pointer",textAlign:"left"}}>
              <span style={{fontSize:25}}>{o.icon}</span>
              <div style={{flex:1}}>
                <div style={{fontWeight:800,fontSize:13}}>{o.label}</div>
                <div style={{fontSize:11,color:G67_P.muted}}>{o.sub}</div>
              </div>
              <span style={{color:o.c,fontSize:16}}>↓</span>
            </button>
          ))}
        </div>
      </div>}
    </div>
  </div>;
};

// ══════════════════════════════════════════════════════════════
//  MAIN APP
// ══════════════════════════════════════════════════════════════
function G67Game(){
  const [started,setStarted]=useState(false);
  const [playerName,setPlayerName]=useState("Estudiante");
  const [avatar,setAvatar]=useState(G67_AVATARS[0]);
  const [xp,setXp]=useState(0);const [coins,setCoins]=useState(0);const [lives,setLives]=useState(5);
  const [completed,setCompleted]=useState([]);const [answers,setAnswers]=useState({});
  const [screen,setScreen]=useState("home");const [selMission,setSelMission]=useState(null);
  const [showLogin,setShowLogin]=useState(false);const [showAdmin,setShowAdmin]=useState(false);
  const [toast,setToast]=useState(null);
  const showToast=(msg,color)=>setToast({msg,color});
  const handleStart=(name,av)=>{
    setPlayerName(name);setAvatar(av);
    const ex=G67_loadPlayers().find(p=>p.name===name);
    if(ex){setXp(ex.xp||0);setCoins(ex.coins||0);setLives(ex.lives||5);
      setCompleted(ex.completedMissions||[]);setAnswers(ex.answers||{});
      if(ex.avatarId)setAvatar(G67_AVATARS.find(a=>a.id===ex.avatarId)||av);}
    setStarted(true);
  };
  const handleNameChange=name=>{
    setPlayerName(name);
    const ex=G67_loadPlayers().find(p=>p.name===name);
    if(ex){setXp(ex.xp||0);setCoins(ex.coins||0);setLives(ex.lives||5);setCompleted(ex.completedMissions||[]);setAnswers(ex.answers||{});}
  };
  const handleAvatarChange=av=>{
    setAvatar(av);
    G67_savePlayers(G67_upsertPlayer(G67_loadPlayers(),playerName,{xp,coins,lives,completedMissions:completed,answers,avatarId:av.id}));
    showToast(`${av.emoji} ¡Avatar cambiado!`,G67_P.purple);
  };
  const handleRecordAnswer=(qId,correct,qData)=>{
    const na={...answers,[qId]:{correct,competency:qData.competency,domain:qData.domain||"Semántica",lvl:qData.lvl,diff:qData.diff}};
    setAnswers(na);G67_savePlayers(G67_upsertPlayer(G67_loadPlayers(),playerName,{xp,coins,lives,completedMissions:completed,answers:na,avatarId:avatar.id}));
  };
  const handleEarnReward=(mission,win)=>{
    const eXp=win?mission.xp:Math.round(mission.xp*.4);const eCoins=win?mission.coins:Math.round(mission.coins*.3);
    const nXp=xp+eXp,nCoins=coins+eCoins;
    const nComp=win&&!completed.includes(mission.id)?[...completed,mission.id]:completed;
    setXp(nXp);setCoins(nCoins);if(win)setCompleted(nComp);else setLives(l=>Math.max(0,l-1));
    G67_savePlayers(G67_upsertPlayer(G67_loadPlayers(),playerName,{xp:nXp,coins:nCoins,lives,completedMissions:nComp,answers,avatarId:avatar.id}));
    showToast(win?`🏆 +${eXp} XP • 🪙 +${eCoins}`:`💪 +${eXp} XP de práctica`,win?G67_P.primary:G67_P.gold);
    setScreen("home");setSelMission(null);
  };
  if(!started)return <G67_WelcomeScreen onStart={handleStart}/>;
  if(showAdmin)return <G67_AdminPanel onClose={()=>setShowAdmin(false)}/>;
  return <div style={{minHeight:"100vh",background:G67_P.bg}}>
    <style>{G67_CSS}</style>
    {showLogin&&<G67_AdminLogin onSuccess={()=>{setShowLogin(false);setShowAdmin(true);}} onCancel={()=>setShowLogin(false)}/>}
    {toast&&<G67_Toast msg={toast.msg} color={toast.color} onDone={()=>setToast(null)}/>}
    <div style={{maxWidth:720,margin:"0 auto",padding:"13px 12px"}}>
      <div style={{textAlign:"center",marginBottom:14}}>
        <div style={{display:"inline-flex",alignItems:"center",gap:5,background:`${G67_P.primary}12`,
          border:`1px solid ${G67_P.primary}33`,borderRadius:30,padding:"3px 11px",marginBottom:7,
          fontSize:11,color:G67_P.primary,fontWeight:700}}>
          🏫 I.E. La Amistad • Grados 6° y 7° • Mg. Anderson
        </div>
        <h1 style={{margin:0,fontWeight:900,fontSize:24,
          background:`linear-gradient(90deg,${G67_P.primary},${G67_P.accent},${G67_P.purple})`,
          WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",lineHeight:1.2}}>
          🌟 English Guardians G6-G7
        </h1>
        <p style={{color:G67_P.muted,fontSize:12,margin:"3px 0 0"}}>Presente Simple • Vocabulario Básico • Pre A1 / A1</p>
      </div>
      <div style={{display:"flex",gap:6,marginBottom:13}}>
        {[{id:"home",l:"🏠 Misiones"},{id:"ranking",l:"🏆 Ranking"}].map(t=>(
          <button key={t.id} onClick={()=>{setScreen(t.id);setSelMission(null);}}
            style={{padding:"7px 15px",borderRadius:12,border:"none",
              background:screen===t.id?G67_P.primary:"#fff",color:screen===t.id?"#fff":G67_P.muted,
              fontWeight:700,cursor:"pointer",fontSize:12,
              boxShadow:screen===t.id?`0 2px 9px ${G67_P.primary}44`:"0 1px 4px rgba(0,0,0,.06)"}}>
            {t.l}
          </button>
        ))}
        <button onClick={()=>setShowLogin(true)} style={{marginLeft:"auto",padding:"7px 10px",borderRadius:12,
          border:"none",background:"#fff",color:"#94A3B8",cursor:"pointer",fontSize:11,
          boxShadow:"0 1px 4px rgba(0,0,0,.06)"}}>🔐</button>
      </div>
      {screen!=="mission"&&<G67_PlayerHUD name={playerName} xp={xp} coins={coins} lives={lives}
        avatar={avatar} onNameChange={handleNameChange} onAvatarChange={handleAvatarChange}/>}
      {screen==="home"&&!selMission&&<G67_MissionGrid completed={completed} onSelect={m=>{setSelMission(m);setScreen("mission");}}/>}
      {screen==="ranking"&&<G67_RankingPanel playerName={playerName}/>}
      {screen==="mission"&&selMission&&(
        <G67_MissionDetail mission={selMission}
          onBack={()=>{setScreen("home");setSelMission(null);}}
          onEarnReward={handleEarnReward} onRecordAnswer={handleRecordAnswer}/>
      )}
      <div style={{textAlign:"center",marginTop:26,color:"#CBD5E1",fontSize:10}}>
        English Guardians G6-G7 © 2026 • I.E. La Amistad
      </div>
    </div>
  </div>;
}

