//  AVATAR PICKER
// ══════════════════════════════════════════════════════════════
const G8_AvatarPicker=({current,onSelect,onClose})=>(
  <div style={{position:"fixed",inset:0,background:"rgba(30,41,59,.6)",zIndex:6000,
    display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
    <div className="pop" style={{background:G8_P.card,borderRadius:22,padding:24,maxWidth:380,width:"100%",
      boxShadow:"0 8px 48px rgba(249,115,22,.2)"}}>
      <div style={{fontWeight:900,fontSize:17,color:G8_P.text,marginBottom:4,textAlign:"center"}}>🎭 Elige tu Avatar</div>
      <p style={{color:G8_P.muted,fontSize:12,textAlign:"center",margin:"0 0 16px"}}>Toca el que más te guste</p>
      <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:9,marginBottom:14}}>
        {G8_AVATARS.map(a=>(
          <div key={a.id} onClick={()=>onSelect(a)}
            style={{textAlign:"center",padding:"9px 4px",borderRadius:13,cursor:"pointer",
              border:`2px solid ${current===a.id?G8_P.primary:G8_P.border}`,
              background:current===a.id?`${G8_P.primary}18`:"#FFF7ED",transition:"all .2s"}}>
            <div style={{fontSize:26,marginBottom:2}}>{a.emoji}</div>
            <div style={{fontSize:9,color:G8_P.muted,fontWeight:700}}>{a.label}</div>
          </div>
        ))}
      </div>
      <button onClick={onClose} style={{width:"100%",padding:"10px 0",borderRadius:13,border:"none",
        background:G8_P.primary,color:"#fff",fontWeight:900,cursor:"pointer",fontSize:14}}>✓ Listo</button>
    </div>
  </div>
);

// ══════════════════════════════════════════════════════════════
//  WELCOME SCREEN
// ══════════════════════════════════════════════════════════════
const G8_WelcomeScreen=({onStart})=>{
  const [name,setName]=useState("");
  const [avatar,setAvatar]=useState(G8_AVATARS[0]);
  const [showPicker,setShowPicker]=useState(false);
  const [err,setErr]=useState(false);
  const go=()=>{if(!name.trim()){setErr(true);return;}onStart(name.trim(),avatar);};
  return(
    <div style={{minHeight:"100vh",background:G8_P.bg,display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
      <style>{G8_CSS}</style>
      {showPicker&&<G8_AvatarPicker current={avatar.id} onSelect={a=>{setAvatar(a);setShowPicker(false);}} onClose={()=>setShowPicker(false)}/>}
      <div className="pop" style={{background:G8_P.card,borderRadius:26,padding:30,maxWidth:400,width:"100%",
        boxShadow:"0 8px 48px rgba(249,115,22,.18)",textAlign:"center"}}>
        <div style={{display:"inline-flex",alignItems:"center",gap:6,background:`${G8_P.primary}12`,
          border:`1px solid ${G8_P.primary}33`,borderRadius:30,padding:"3px 12px",marginBottom:10,
          fontSize:11,color:G8_P.primary,fontWeight:700}}>
          🏫 I.E. La Amistad • Grado 8° • Mg. Anderson
        </div>
        <h1 style={{margin:"0 0 4px",fontWeight:900,fontSize:23,
          background:`linear-gradient(90deg,${G8_P.primary},${G8_P.purple},${G8_P.pink})`,
          WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent"}}>
          ⚔️ English Guardians G8
        </h1>
        <p style={{color:G8_P.muted,fontSize:12,margin:"0 0 24px"}}>Presente Simple • Comparativos • Superlativos</p>
        <div style={{marginBottom:20}}>
          <div style={{fontSize:11,fontWeight:700,color:G8_P.muted,marginBottom:9}}>Elige tu avatar</div>
          <div onClick={()=>setShowPicker(true)} className="float"
            style={{width:78,height:78,borderRadius:"50%",margin:"0 auto 8px",cursor:"pointer",
              background:`linear-gradient(135deg,${G8_P.primary},${G8_P.purple})`,
              display:"flex",alignItems:"center",justifyContent:"center",fontSize:38,
              boxShadow:`0 6px 22px ${G8_P.primary}44`,border:`3px solid ${G8_P.primary}`}}>
            {avatar.emoji}
          </div>
          <button onClick={()=>setShowPicker(true)} style={{background:"none",border:`1.5px solid ${G8_P.border}`,
            borderRadius:20,padding:"4px 14px",color:G8_P.muted,cursor:"pointer",fontSize:12,fontWeight:700}}>
            🎭 Cambiar avatar
          </button>
        </div>
        <div style={{marginBottom:20,textAlign:"left"}}>
          <div style={{fontSize:11,fontWeight:700,color:G8_P.muted,marginBottom:7}}>¿Cuál es tu nombre?</div>
          <input value={name} onChange={e=>{setName(e.target.value);setErr(false);}}
            onKeyDown={e=>e.key==="Enter"&&go()} placeholder="Escribe tu nombre..."
            style={{width:"100%",padding:"12px 15px",borderRadius:13,
              border:`2px solid ${err?G8_P.warn:name?G8_P.primary:G8_P.border}`,
              fontSize:15,fontWeight:700,color:G8_P.text,outline:"none",background:"#FFF7ED"}}/>
          {err&&<p style={{color:G8_P.warn,fontSize:11,fontWeight:700,margin:"5px 0 0"}}>⚠️ Escribe tu nombre para continuar</p>}
        </div>
        <button onClick={go} style={{width:"100%",padding:"13px 0",borderRadius:15,border:"none",
          background:`linear-gradient(90deg,${G8_P.primary},${G8_P.purple})`,
          color:"#fff",fontWeight:900,fontSize:15,cursor:"pointer",
          boxShadow:`0 4px 18px ${G8_P.primary}44`}}>¡Comenzar Aventura! ⚔️</button>
        <p style={{color:G8_P.muted,fontSize:10,marginTop:12}}>Si ya jugaste antes, escribe el mismo nombre para recuperar tu progreso.</p>
      </div>
    </div>
  );
};

// ══════════════════════════════════════════════════════════════
//  PLAYER HUD
// ══════════════════════════════════════════════════════════════
const G8_PlayerHUD=({name,xp,coins,lives,avatar,onNameChange,onAvatarChange})=>{
  const [editing,setEditing]=useState(false);
  const [tmp,setTmp]=useState(name);
  const [showPicker,setShowPicker]=useState(false);
  const level=Math.floor(xp/150)+1;
  return <>
    {showPicker&&<G8_AvatarPicker current={avatar.id} onSelect={a=>{onAvatarChange(a);setShowPicker(false);}} onClose={()=>setShowPicker(false)}/>}
    <div className="slideUp" style={{background:G8_P.card,borderRadius:20,padding:"13px 17px",
      marginBottom:13,boxShadow:"0 2px 14px rgba(249,115,22,.10)",border:`1.5px solid ${G8_P.border}`}}>
    <div style={{display:"flex",alignItems:"center",gap:11,flexWrap:"wrap"}}>
      <div onClick={()=>setShowPicker(true)} className="float"
        style={{width:52,height:52,borderRadius:"50%",flexShrink:0,cursor:"pointer",
          background:`linear-gradient(135deg,${G8_P.primary},${G8_P.purple})`,
          display:"flex",alignItems:"center",justifyContent:"center",fontSize:26,position:"relative",
          boxShadow:`0 2px 10px ${G8_P.primary}33`}}>
        {avatar.emoji}
        <div style={{position:"absolute",bottom:-2,right:-2,width:17,height:17,borderRadius:"50%",
          background:G8_P.gold,border:"2px solid #fff",display:"flex",alignItems:"center",
          justifyContent:"center",fontSize:8}}>✏️</div>
      </div>
      <div style={{flex:1,minWidth:140}}>
        <div style={{display:"flex",alignItems:"center",gap:7,marginBottom:5}}>
          {editing
            ?<><input value={tmp} onChange={e=>setTmp(e.target.value)}
                onKeyDown={e=>e.key==="Enter"&&(onNameChange(tmp),setEditing(false))} autoFocus
                style={{background:"transparent",border:"none",borderBottom:`2px solid ${G8_P.primary}`,
                fontSize:14,fontWeight:800,color:G8_P.text,outline:"none",width:150}}/>
              <button onClick={()=>{onNameChange(tmp);setEditing(false);}}
                style={{background:G8_P.accent,color:"#fff",border:"none",borderRadius:8,padding:"2px 7px",cursor:"pointer",fontWeight:700}}>✓</button>
            </>
            :<><span style={{fontWeight:900,fontSize:15,color:G8_P.text}}>{name}</span>
              <button onClick={()=>setEditing(true)} style={{background:"none",border:"none",cursor:"pointer",fontSize:12}}>✏️</button>
            </>}
        </div>
        <G8_XPBar xp={xp}/>
      </div>
      <div style={{display:"flex",gap:7,flexShrink:0}}>
        {[{v:`Nv.${level}`,i:"⭐",c:G8_P.primary},{v:coins,i:"🪙",c:G8_P.gold}].map((s,i)=>(
          <div key={i} style={{textAlign:"center",background:`${s.c}12`,border:`1.5px solid ${s.c}33`,
            borderRadius:11,padding:"5px 9px",minWidth:52}}>
            <div style={{fontSize:13}}>{s.i}</div>
            <div style={{fontWeight:900,color:s.c,fontSize:12}}>{s.v}</div>
          </div>
        ))}
        <div style={{textAlign:"center",background:"#FEE2E222",border:"1.5px solid #EF444433",
          borderRadius:11,padding:"5px 9px",minWidth:52}}>
          {Array.from({length:5}).map((_,i)=>(
            <span key={i} style={{fontSize:11,opacity:i<lives?1:.2}}>❤️</span>
          ))}
          <div style={{fontSize:9,color:G8_P.muted,marginTop:1}}>Vidas</div>
        </div>
      </div>
    </div>
  </div>
  </>;
};

// ══════════════════════════════════════════════════════════════
//  MISSION GRID
// ══════════════════════════════════════════════════════════════
const G8_MissionGrid=({completed,onSelect})=>{
  const mecLabel={quiz:"⚔️ Quiz Boss",wordmatch:"🔤 Word Match",dragdrop:"🎯 Clasificar",fillblank:"✏️ Completar"};
  return <div>
    <h2 style={{fontWeight:900,fontSize:20,color:G8_P.text,marginBottom:13,textAlign:"center"}}>🗺️ Elige tu Misión</h2>
    <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(270px,1fr))",gap:11}}>
      {G8_MISSIONS.map((m,i)=>{
        const done=completed.includes(m.id);
        const locked=i>0&&!completed.includes(G8_MISSIONS[i-1].id);
        return <div key={m.id} onClick={()=>!locked&&onSelect(m)}
          style={{background:locked?"#FFF7ED":m.bg,borderRadius:17,padding:15,cursor:locked?"not-allowed":"pointer",
            border:`2px solid ${done?"#10B981":locked?"#FED7AA":m.color}44`,
            boxShadow:done?`0 4px 14px #10B98122`:`0 2px 10px ${m.color}18`,
            opacity:locked?.55:1,transition:"all .2s",position:"relative",overflow:"hidden"}}>
          <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:9}}>
            <div style={{fontSize:32}}>{m.emoji}</div>
            <div style={{flex:1}}>
              <div style={{fontWeight:900,color:G8_P.text,fontSize:14}}>{m.name}</div>
              <div style={{fontSize:11,color:m.color,fontWeight:700}}>{m.level}</div>
              <div style={{fontSize:10,color:G8_P.muted}}>{m.topic}</div>
            </div>
            {done&&<span style={{fontSize:19}}>✅</span>}
            {locked&&<span style={{fontSize:19}}>🔒</span>}
          </div>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:5}}>
            <span style={{fontSize:10,background:`${m.color}18`,color:m.color,
              padding:"2px 7px",borderRadius:20,fontWeight:700}}>{mecLabel[m.mechanic]}</span>
            <span style={{fontSize:10,color:G8_P.gold,fontWeight:800}}>🪙{m.coins} +{m.xp}XP</span>
          </div>
          <div style={{fontSize:10,color:G8_P.muted}}>🎁 {m.reward}</div>
        </div>;
      })}
    </div>
  </div>;
};

// ══════════════════════════════════════════════════════════════
//  BOSS INTRO
// ══════════════════════════════════════════════════════════════
const G8_BossIntro=({m,onStart,onBack})=>(
  <div className="slideUp" style={{textAlign:"center",padding:"18px 0"}}>
    <div className="shake" style={{fontSize:68,display:"inline-block",marginBottom:8}}>{m.bossEmoji}</div>
    <div style={{background:m.bg,border:`2px solid ${m.color}44`,borderRadius:17,padding:16,marginBottom:14}}>
      <div style={{fontSize:12,fontWeight:700,color:m.color,marginBottom:5}}>⚔️ {m.bossName} aparece!</div>
      <p style={{color:G8_P.text,fontWeight:700,fontSize:13,margin:0}}>
        {m.mechanic==="quiz"&&"¡Lee el texto y responde las preguntas para derrotar al Boss!"}
        {m.mechanic==="wordmatch"&&"¡Conecta cada palabra con su significado correcto!"}
        {m.mechanic==="dragdrop"&&"¡Clasifica las expresiones en Comparativo o Superlativo!"}
        {m.mechanic==="fillblank"&&"¡Completa las oraciones eligiendo la palabra correcta!"}
      </p>
    </div>
    <div style={{fontSize:12,color:G8_P.muted,marginBottom:16}}>
      📖 Nivel: <b>{m.level}</b> • 📚 <b>{m.topic}</b> • 🎁 <b>{m.reward}</b>
    </div>
    <div style={{display:"flex",gap:9,justifyContent:"center"}}>
      <button onClick={onBack} style={{padding:"8px 17px",borderRadius:13,border:`2px solid ${G8_P.border}`,
        background:"#fff",color:G8_P.muted,fontWeight:700,cursor:"pointer",fontSize:13}}>← Volver</button>
      <button onClick={onStart} className="pulse" style={{padding:"8px 22px",borderRadius:13,border:"none",
        background:`linear-gradient(90deg,${m.color},${G8_P.purple})`,color:"#fff",
        fontWeight:900,cursor:"pointer",fontSize:14}}>¡Iniciar Batalla! ⚔️</button>
    </div>
  </div>
);

// ══════════════════════════════════════════════════════════════
//  READING PHASE
// ══════════════════════════════════════════════════════════════
const G8_ReadingPhase=({m,onReady,onBack})=>{
  const [speaking,setSpeaking]=useState(false);
  const speak=(rate=0.9)=>{
    if(!("speechSynthesis"in window))return;
    window.speechSynthesis.cancel();
    const u=new SpeechSynthesisUtterance(m.text);
    u.lang="en-US";u.rate=rate;
    u.onstart=()=>setSpeaking(true);u.onend=()=>setSpeaking(false);
    window.speechSynthesis.speak(u);
  };
  return <div className="slideUp">
    <div style={{display:"flex",alignItems:"center",gap:9,marginBottom:13}}>
      <button onClick={onBack} style={{background:"none",border:"none",color:G8_P.primary,fontWeight:700,cursor:"pointer"}}>← Volver</button>
      <h3 style={{margin:0,fontWeight:900,color:G8_P.text,fontSize:16}}>{m.emoji} {m.name}</h3>
    </div>
    <div style={{background:m.bg,border:`1.5px solid ${m.color}33`,borderRadius:13,
      padding:"7px 13px",marginBottom:11,fontSize:11,color:m.color,fontWeight:700}}>
      🌎 {m.topic} • {m.level}
    </div>
    <div style={{background:G8_P.card,borderRadius:17,padding:18,marginBottom:13,
      border:`1.5px solid ${G8_P.border}`,boxShadow:"0 2px 10px rgba(0,0,0,.05)"}}>
      <p style={{color:G8_P.text,lineHeight:1.8,fontSize:15,margin:0}}>{m.text}</p>
    </div>
    <div style={{display:"flex",gap:7,marginBottom:16}}>
      <button onClick={()=>speak(0.9)} style={{flex:1,padding:"8px 0",borderRadius:12,border:"none",
        background:speaking?`${m.color}22`:m.bg,color:m.color,fontWeight:700,cursor:"pointer",fontSize:12}}>
        {speaking?"🔊 Reproduciendo...":"🔊 Escuchar"}
      </button>
      <button onClick={()=>speak(0.6)} style={{flex:1,padding:"8px 0",borderRadius:12,border:"none",
        background:"#F0F9FF",color:G8_P.sky,fontWeight:700,cursor:"pointer",fontSize:12}}>🐢 Lento</button>
      {speaking&&<button onClick={()=>window.speechSynthesis.cancel()}
        style={{padding:"8px 11px",borderRadius:12,border:"none",background:"#FEE2E2",color:G8_P.warn,cursor:"pointer",fontWeight:700}}>⏹</button>}
    </div>
    <button onClick={onReady} style={{width:"100%",padding:"12px 0",borderRadius:15,border:"none",
      background:`linear-gradient(90deg,${m.color},${G8_P.purple})`,
      color:"#fff",fontWeight:900,fontSize:14,cursor:"pointer"}}>
      {m.mechanic==="quiz"?"¡Listo para el Quiz! 🧠":m.mechanic==="wordmatch"?"¡Listo para Word Match! 🔤":m.mechanic==="fillblank"?"¡Listo para Completar! ✏️":"¡Listo para Clasificar! 🎯"}
    </button>
  </div>;
};

// ══════════════════════════════════════════════════════════════
//  QUIZ MECHANIC
// ══════════════════════════════════════════════════════════════
const G8_QuizMechanic=({m,onComplete,onRecordAnswer})=>{
  const qs=m.questions;
  const [idx,setIdx]=useState(0);
  const [sel,setSel]=useState(null);
  const [score,setScore]=useState(0);
  const [timeLeft,setTimeLeft]=useState(45);
  const [done,setDone]=useState(false);
  const ref=useRef(null);
  useEffect(()=>{
    if(done||sel!==null)return;
    ref.current=setInterval(()=>setTimeLeft(t=>{
      if(t<=1){clearInterval(ref.current);handleAns(-1);return 0;}return t-1;
    }),1000);
    return()=>clearInterval(ref.current);
  },[idx,sel,done]);
  const handleAns=i=>{
    if(sel!==null)return;
    clearInterval(ref.current);setSel(i);
    const ok=i===qs[idx].ans;
    if(ok)setScore(s=>s+1);
    onRecordAnswer(qs[idx].id,ok,qs[idx]);
  };
  const next=()=>{setSel(null);setTimeLeft(45);if(idx+1>=qs.length)setDone(true);else setIdx(i=>i+1);};
  if(done)return <G8_ResultScreen m={m} score={score} total={qs.length} onContinue={()=>onComplete(score,qs.length)}/>;
  const q=qs[idx];
  const tc=timeLeft>25?G8_P.accent:timeLeft>12?G8_P.gold:G8_P.warn;
  return <div className="slideUp">
    <div style={{display:"flex",alignItems:"center",gap:9,marginBottom:11}}>
      <div style={{flex:1,height:6,borderRadius:6,background:"#FED7AA",overflow:"hidden"}}>
        <div style={{height:"100%",width:`${(idx/qs.length)*100}%`,background:m.color,borderRadius:6,transition:"width .5s"}}/>
      </div>
      <span style={{fontSize:10,fontWeight:800,color:G8_P.muted}}>{idx+1}/{qs.length}</span>
      <div style={{display:"flex",alignItems:"center",gap:4}}>
        <div style={{width:48,height:6,borderRadius:6,background:"#FED7AA",overflow:"hidden"}}>
          <div style={{height:"100%",width:`${(timeLeft/45)*100}%`,background:tc,borderRadius:6,transition:"width 1s linear"}}/>
        </div>
        <span style={{fontSize:11,fontWeight:800,color:tc}}>{timeLeft}s</span>
      </div>
    </div>
    <div style={{background:m.bg,borderRadius:11,padding:"6px 11px",marginBottom:11,
      display:"flex",alignItems:"center",gap:7}}>
      <span style={{fontSize:19}}>{m.bossEmoji}</span>
      <div style={{flex:1,height:7,borderRadius:7,background:"#FED7AA",overflow:"hidden"}}>
        <div style={{height:"100%",borderRadius:7,background:G8_P.warn,
          width:`${100-((idx/qs.length)*100)}%`,transition:"width .6s"}}/>
      </div>
      <span style={{fontSize:10,fontWeight:700,color:G8_P.warn}}>{qs.length-idx} HP</span>
    </div>
    <div style={{background:G8_P.card,borderRadius:17,padding:17,marginBottom:11,
      border:`1.5px solid ${G8_P.border}`,boxShadow:"0 2px 8px rgba(0,0,0,.05)"}}>
      <div style={{display:"flex",gap:5,marginBottom:7,flexWrap:"wrap"}}>
        <span style={{fontSize:10,background:`${m.color}18`,color:m.color,padding:"2px 7px",borderRadius:20,fontWeight:700}}>{q.competency}</span>
        <span style={{fontSize:10,background:"#F1F5F9",color:G8_P.muted,padding:"2px 7px",borderRadius:20,fontWeight:700}}>{q.lvl}</span>
        <span style={{fontSize:10,background:"#F1F5F9",color:G8_P.muted,padding:"2px 7px",borderRadius:20,fontWeight:700}}>{"⭐".repeat(q.diff)}</span>
      </div>
      <p style={{fontWeight:800,color:G8_P.text,fontSize:15,marginBottom:13}}>{q.q}</p>
      <div style={{display:"flex",flexDirection:"column",gap:7}}>
        {q.opts.map((opt,i)=>{
          let bg=G8_P.bg,border=G8_P.border,col=G8_P.text;
          if(sel!==null){
            if(i===q.ans){bg="#DCFCE7";border="#10B981";col="#065F46";}
            else if(i===sel&&i!==q.ans){bg="#FEE2E2";border=G8_P.warn;col="#991B1B";}
          }
          return <button key={i} onClick={()=>handleAns(i)}
            style={{width:"100%",textAlign:"left",padding:"10px 12px",borderRadius:11,
              background:bg,border:`1.5px solid ${border}`,color:col,
              fontWeight:sel!==null&&i===q.ans?800:600,fontSize:14,cursor:"pointer",transition:"all .2s"}}>
            <span style={{color:m.color,fontWeight:800,marginRight:7}}>{["A","B","C","D"][i]}.</span>{opt}
          </button>;
        })}
      </div>
      {sel!==null&&<div className="slideUp" style={{marginTop:11,padding:"8px 12px",borderRadius:10,
        background:`${G8_P.sky}18`,border:`1.5px solid ${G8_P.sky}44`,color:G8_P.sky,fontSize:12,fontWeight:700}}>
        💡 {q.exp}
      </div>}
    </div>
    {sel!==null&&<button className="pop" onClick={next} style={{width:"100%",padding:"11px 0",borderRadius:13,
      border:"none",background:`linear-gradient(90deg,${m.color},${G8_P.purple})`,
      color:"#fff",fontWeight:900,fontSize:14,cursor:"pointer"}}>
      {idx+1>=qs.length?"🏆 Ver Resultados":"Siguiente →"}
    </button>}
  </div>;
};

// ══════════════════════════════════════════════════════════════
//  WORD MATCH MECHANIC (misión 2)
// ══════════════════════════════════════════════════════════════
const G8_WordMatchMechanic=({m,onComplete,onRecordAnswer})=>{
  const pairs=G8_WORDMATCH_PAIRS;
  const [selWord,setSelWord]=useState(null);
  const [selMatch,setSelMatch]=useState(null);
  const [matched,setMatched]=useState({});
  const [wrong,setWrong]=useState([]);
  const [done,setDone]=useState(false);
  const shuffled=useRef([...pairs].sort(()=>Math.random()-.5)).current;
  useEffect(()=>{
    if(selWord!==null&&selMatch!==null){
      const ok=pairs[selWord].match===shuffled[selMatch].match;
      if(ok){
        const nm={...matched,[selWord]:selMatch};setMatched(nm);
        m.questions.slice(0,1).forEach(q=>onRecordAnswer(q.id,true,q));
        if(Object.keys(nm).length===pairs.length)setTimeout(()=>setDone(true),600);
      }else{
        setWrong([selWord+"w",selMatch+"m"]);
        setTimeout(()=>setWrong([]),700);
        m.questions.slice(0,1).forEach(q=>onRecordAnswer(q.id,false,q));
      }
      setTimeout(()=>{setSelWord(null);setSelMatch(null);},300);
    }
  },[selWord,selMatch]);
  if(done){const s=Object.keys(matched).length;return <G8_ResultScreen m={m} score={s} total={pairs.length} onContinue={()=>onComplete(s,pairs.length)}/>;}
  return <div className="slideUp">
    <div style={{background:m.bg,borderRadius:13,padding:"9px 13px",marginBottom:14,
      display:"flex",justifyContent:"space-between",alignItems:"center"}}>
      <span style={{fontWeight:800,color:m.color,fontSize:13}}>🔤 Word Match — {m.name}</span>
      <span style={{fontSize:11,color:G8_P.muted}}>Toca para conectar</span>
    </div>
    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:11}}>
      <div>
        <div style={{fontSize:10,fontWeight:700,color:G8_P.muted,marginBottom:7,textAlign:"center"}}>PALABRAS</div>
        {pairs.map((p,i)=>{
          const isM=matched[i]!==undefined,isSel=selWord===i,isW=wrong.includes(i+"w");
          return <div key={i} onClick={()=>!isM&&setSelWord(isSel?null:i)}
            className={isW?"shake":""}
            style={{padding:"10px 11px",borderRadius:11,marginBottom:7,cursor:isM?"default":"pointer",
              background:isM?"#DCFCE7":isSel?`${m.color}22`:"#fff",
              border:`2px solid ${isM?"#10B981":isSel?m.color:isW?G8_P.warn:G8_P.border}`,
              fontWeight:700,color:G8_P.text,fontSize:13,textAlign:"center",transition:"all .2s"}}>
            {isM?"✅ ":"🔵 "}{p.word}
          </div>;
        })}
      </div>
      <div>
        <div style={{fontSize:10,fontWeight:700,color:G8_P.muted,marginBottom:7,textAlign:"center"}}>DEFINICIONES</div>
        {shuffled.map((p,i)=>{
          const isM=Object.values(matched).includes(i),isSel=selMatch===i,isW=wrong.includes(i+"m");
          return <div key={i} onClick={()=>!isM&&setSelMatch(isSel?null:i)}
            className={isW?"shake":""}
            style={{padding:"10px 11px",borderRadius:11,marginBottom:7,cursor:isM?"default":"pointer",
              background:isM?"#DCFCE7":isSel?`${m.color}22`:"#fff",
              border:`2px solid ${isM?"#10B981":isSel?m.color:isW?G8_P.warn:G8_P.border}`,
              fontWeight:600,color:G8_P.text,fontSize:12,textAlign:"center",transition:"all .2s"}}>
            {isM?"✅ ":""}{p.match}
          </div>;
        })}
      </div>
    </div>
    <div style={{marginTop:13,background:`${G8_P.sky}12`,borderRadius:11,padding:"9px 13px",
      fontSize:12,color:G8_P.sky,fontWeight:700}}>
      💡 Toca una palabra y luego su definición para conectarlas.
    </div>
  </div>;
};

// ══════════════════════════════════════════════════════════════
//  DRAG-DROP MECHANIC (misión 3)
// ══════════════════════════════════════════════════════════════
const G8_DragDropMechanic=({m,onComplete,onRecordAnswer})=>{
  const items=G8_DRAGDROP_ITEMS;
  const [placements,setPlacements]=useState({});
  const [feedback,setFeedback]=useState({});
  const [selItem,setSelItem]=useState(null);
  const [done,setDone]=useState(false);
  const place=cat=>{
    if(!selItem)return;
    const ok=items.find(i=>i.id===selItem)?.category===cat;
    const np={...placements,[selItem]:cat};
    const nf={...feedback,[selItem]:ok};
    setPlacements(np);setFeedback(nf);
    m.questions.slice(0,1).forEach(q=>onRecordAnswer(q.id,ok,q));
    setSelItem(null);
    if(Object.keys(np).length===items.length)setTimeout(()=>setDone(true),600);
  };
  if(done){const s=Object.values(feedback).filter(Boolean).length;return <G8_ResultScreen m={m} score={s} total={items.length} onContinue={()=>onComplete(s,items.length)}/>;}
  const unplaced=items.filter(i=>!placements[i.id]);
  return <div className="slideUp">
    <div style={{background:m.bg,borderRadius:13,padding:"9px 13px",marginBottom:13,
      display:"flex",justifyContent:"space-between"}}>
      <span style={{fontWeight:800,color:m.color,fontSize:13}}>🎯 Clasificar — {m.name}</span>
      <span style={{fontSize:11,color:G8_P.muted}}>{Object.keys(placements).length}/{items.length}</span>
    </div>
    <div style={{marginBottom:13}}>
      <div style={{fontSize:10,fontWeight:700,color:G8_P.muted,marginBottom:7}}>Toca para seleccionar:</div>
      <div style={{display:"flex",flexWrap:"wrap",gap:7}}>
        {unplaced.map(item=>(
          <div key={item.id} onClick={()=>setSelItem(selItem===item.id?null:item.id)}
            style={{padding:"8px 13px",borderRadius:20,cursor:"pointer",fontWeight:700,fontSize:13,
              background:selItem===item.id?`${m.color}22`:"#fff",
              border:`2px solid ${selItem===item.id?m.color:G8_P.border}`,color:G8_P.text,transition:"all .2s"}}>
            {selItem===item.id?"👉 ":""}{item.word}
          </div>
        ))}
        {!unplaced.length&&<div style={{color:G8_P.accent,fontWeight:700,fontSize:12}}>✅ ¡Todos clasificados!</div>}
      </div>
    </div>
    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:13}}>
      {G8_DD_CATEGORIES.map(cat=>{
        const placed=items.filter(i=>placements[i.id]===cat);
        return <div key={cat} onClick={()=>place(cat)}
          style={{background:selItem?"#FFF7ED":"#F8FAFC",border:`2px dashed ${selItem?m.color:G8_P.border}`,
            borderRadius:13,padding:"9px 7px",cursor:selItem?"pointer":"default",minHeight:90,transition:"all .2s"}}>
          <div style={{fontSize:11,fontWeight:800,color:m.color,marginBottom:7,textAlign:"center"}}>{cat}</div>
          {placed.map(i=>(
            <div key={i.id} style={{padding:"4px 7px",borderRadius:7,marginBottom:3,textAlign:"center",
              background:feedback[i.id]?"#DCFCE7":"#FEE2E2",
              border:`1.5px solid ${feedback[i.id]?"#10B981":G8_P.warn}`,fontSize:11,fontWeight:700}}>
              {feedback[i.id]?"✅":"❌"} {i.word}
            </div>
          ))}
        </div>;
      })}
    </div>
    {selItem&&<div style={{textAlign:"center",fontSize:12,color:m.color,fontWeight:700}}>
      👆 Ahora toca una categoría: <b>{items.find(i=>i.id===selItem)?.word}</b>
    </div>}
  </div>;
};

// ══════════════════════════════════════════════════════════════
//  FILL-IN-THE-BLANK MECHANIC (misión 4)
// ══════════════════════════════════════════════════════════════
const G8_FillBlankMechanic=({m,onComplete,onRecordAnswer})=>{
  const items=G8_FILLBLANK_ITEMS;
  const [idx,setIdx]=useState(0);
  const [sel,setSel]=useState(null);
  const [score,setScore]=useState(0);
  const [done,setDone]=useState(false);
  const handlePick=opt=>{
    if(sel!==null)return;
    setSel(opt);
    const ok=opt===items[idx].answer;
    if(ok)setScore(s=>s+1);
    m.questions.slice(idx,idx+1).forEach(q=>onRecordAnswer(q.id,ok,q));
  };
  const next=()=>{
    setSel(null);
    if(idx+1>=items.length)setDone(true);else setIdx(i=>i+1);
  };
  if(done)return <G8_ResultScreen m={m} score={score} total={items.length} onContinue={()=>onComplete(score,items.length)}/>;
  const it=items[idx];
  const parts=it.sentence.split("___");
  return <div className="slideUp">
    <div style={{background:m.bg,borderRadius:13,padding:"9px 13px",marginBottom:14,
      display:"flex",justifyContent:"space-between",alignItems:"center"}}>
      <span style={{fontWeight:800,color:m.color,fontSize:13}}>✏️ Completa la oración — {m.name}</span>
      <span style={{fontSize:11,color:G8_P.muted}}>{idx+1}/{items.length}</span>
    </div>
    <div style={{background:G8_P.card,borderRadius:17,padding:20,marginBottom:14,
      border:`1.5px solid ${G8_P.border}`,boxShadow:"0 2px 10px rgba(0,0,0,.05)",textAlign:"center"}}>
      <p style={{fontSize:18,fontWeight:800,color:G8_P.text,lineHeight:1.6,margin:0}}>
        {parts[0]}
        <span style={{display:"inline-block",minWidth:80,borderBottom:`3px solid ${m.color}`,
          color:sel?(sel===it.answer?G8_P.accent:G8_P.warn):m.color,fontWeight:900,padding:"0 6px"}}>
          {sel||"______"}
        </span>
        {parts[1]}
      </p>
    </div>
    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:9,marginBottom:14}}>
      {it.options.map((opt,i)=>{
        let bg="#fff",border=G8_P.border,col=G8_P.text;
        if(sel!==null){
          if(opt===it.answer){bg="#DCFCE7";border="#10B981";col="#065F46";}
          else if(opt===sel){bg="#FEE2E2";border=G8_P.warn;col="#991B1B";}
        }
        return <button key={i} onClick={()=>handlePick(opt)} disabled={sel!==null}
          style={{padding:"13px 10px",borderRadius:13,border:`2px solid ${border}`,
            background:bg,color:col,fontWeight:800,fontSize:14,cursor:sel!==null?"default":"pointer",transition:"all .2s"}}>
          {opt}
        </button>;
      })}
    </div>
    {sel!==null&&<button className="pop" onClick={next} style={{width:"100%",padding:"12px 0",borderRadius:13,
      border:"none",background:`linear-gradient(90deg,${m.color},${G8_P.purple})`,
      color:"#fff",fontWeight:900,fontSize:14,cursor:"pointer"}}>
      {idx+1>=items.length?"🏆 Ver Resultados":"Siguiente →"}
    </button>}
  </div>;
};


const G8_ResultScreen=({m,score,total,onContinue})=>{
  const pct=Math.round((score/total)*100);
  const win=pct>=60;
  const stars=pct>=85?3:pct>=60?2:1;
  return <div className="pop" style={{textAlign:"center",padding:"22px 0"}}>
    {win&&<G8_Fireworks/>}
    <div style={{fontSize:64,marginBottom:7,display:"inline-block"}}>{win?"🏆":"💪"}</div>
    <h2 style={{fontWeight:900,fontSize:22,color:G8_P.text,marginBottom:4}}>
      {pct>=85?"¡Boss derrotado! 🎉":pct>=60?"¡Buen trabajo! 👍":"¡Sigue intentando! 💪"}
    </h2>
    <div style={{display:"flex",justifyContent:"center",gap:4,marginBottom:14,fontSize:26}}>
      {Array.from({length:3}).map((_,i)=><span key={i} style={{opacity:i<stars?1:.2}}>⭐</span>)}
    </div>
    <div style={{background:m.bg,border:`2px solid ${m.color}44`,borderRadius:17,
      padding:16,display:"inline-block",minWidth:180,marginBottom:16}}>
      <div style={{fontSize:36,fontWeight:900,color:m.color}}>{score}/{total}</div>
      <div style={{color:G8_P.muted,fontSize:12,marginBottom:5}}>Respuestas correctas</div>
      {win&&<div style={{fontSize:11,fontWeight:700,color:G8_P.gold}}>🎁 {m.reward}</div>}
      <div style={{fontSize:11,fontWeight:700,color:G8_P.gold,marginTop:3}}>🪙 +{win?m.coins:Math.round(m.coins*.3)}</div>
      <div style={{fontSize:11,fontWeight:700,color:G8_P.primary,marginTop:2}}>+{win?m.xp:Math.round(m.xp*.4)} XP</div>
    </div>
    <div style={{display:"flex",gap:9,justifyContent:"center"}}>
      <button onClick={()=>onContinue(win)} style={{padding:"9px 24px",borderRadius:13,border:"none",
        background:`linear-gradient(90deg,${m.color},${G8_P.purple})`,color:"#fff",
        fontWeight:900,cursor:"pointer",fontSize:14}}>
        {win?"🏆 ¡Reclamar premio!":"🔄 Intentar de nuevo"}
      </button>
    </div>
  </div>;
};

// ══════════════════════════════════════════════════════════════
//  MISSION DETAIL
// ══════════════════════════════════════════════════════════════
const G8_MissionDetail=({mission,onBack,onEarnReward,onRecordAnswer})=>{
  const [view,setView]=useState("intro");
  const handleComplete=(score,total)=>onEarnReward(mission,score/total>=0.6);
  if(view==="intro")return <G8_BossIntro m={mission} onStart={()=>setView("reading")} onBack={onBack}/>;
  if(view==="reading")return <G8_ReadingPhase m={mission} onReady={()=>setView("mechanic")} onBack={()=>setView("intro")}/>;
  if(view==="mechanic"){
    const props={m:mission,onComplete:handleComplete,onRecordAnswer};
    if(mission.mechanic==="quiz")return <G8_QuizMechanic {...props}/>;
    if(mission.mechanic==="wordmatch")return <G8_WordMatchMechanic {...props}/>;
    if(mission.mechanic==="dragdrop")return <G8_DragDropMechanic {...props}/>;
    if(mission.mechanic==="fillblank")return <G8_FillBlankMechanic {...props}/>;
  }
  return null;
};

// ══════════════════════════════════════════════════════════════
//  RANKING
// ══════════════════════════════════════════════════════════════
const G8_RankingPanel=({playerName})=>{
  const players=[...G8_loadPlayers()].sort((a,b)=>(b.xp||0)-(a.xp||0));
  const myRank=players.findIndex(p=>p.name===playerName)+1;
  return <div className="slideUp">
    <h2 style={{fontWeight:900,fontSize:20,color:G8_P.text,marginBottom:13,textAlign:"center"}}>🏆 Ranking de Guardianes G8</h2>
    {myRank>0&&<div style={{background:`${G8_P.primary}12`,border:`2px solid ${G8_P.primary}33`,borderRadius:13,
      padding:"9px 15px",marginBottom:13,textAlign:"center"}}>
      Tu posición: <span style={{fontWeight:900,fontSize:21,color:G8_P.primary}}>#{myRank}</span>
      <span style={{color:G8_P.muted,fontSize:12}}> de {players.length}</span>
    </div>}
    <div style={{display:"flex",flexDirection:"column",gap:6}}>
      {players.map((p,i)=>(
        <div key={p.name} style={{display:"flex",alignItems:"center",gap:9,padding:"10px 14px",borderRadius:12,
          background:p.name===playerName?`${G8_P.primary}12`:G8_P.card,
          border:`1.5px solid ${p.name===playerName?G8_P.primary:i<3?"#F59E0B33":G8_P.border}`}}>
          <span style={{fontSize:15,fontWeight:900,width:28,textAlign:"center",
            color:i===0?G8_P.gold:i===1?"#94A3B8":i===2?"#CD7F32":G8_P.muted}}>
            {i===0?"🥇":i===1?"🥈":i===2?"🥉":`#${i+1}`}
          </span>
          <span style={{flex:1,fontWeight:700,color:G8_P.text,fontSize:13}}>{p.name}</span>
          <span style={{fontWeight:900,color:G8_P.gold,fontSize:12}}>🪙 {p.coins||0}</span>
          <span style={{fontWeight:900,color:G8_P.primary,fontSize:12}}>⭐ {p.xp||0}</span>
        </div>
      ))}
      {!players.length&&<div style={{textAlign:"center",padding:32,color:G8_P.muted}}>¡Sé el primero!</div>}
    </div>
  </div>;
};

// ══════════════════════════════════════════════════════════════
//  ADMIN LOGIN
// ══════════════════════════════════════════════════════════════
const G8_AdminLogin=({onSuccess,onCancel})=>{
  const [pw,setPw]=useState("");const [err,setErr]=useState(false);
  const submit=()=>{if(pw===G8_TEACHER_PASSWORD){setErr(false);onSuccess();}else{setErr(true);setPw("");}};
  return <div style={{position:"fixed",inset:0,background:"rgba(30,41,59,.55)",zIndex:5000,
    display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
    <div className="pop" style={{background:G8_P.card,borderRadius:21,padding:28,maxWidth:330,width:"100%",
      boxShadow:"0 8px 44px rgba(249,115,22,.2)"}}>
      <div style={{textAlign:"center",marginBottom:20}}>
        <div style={{fontSize:42,marginBottom:7}}>🔐</div>
        <h2 style={{margin:0,fontWeight:900,color:G8_P.text,fontSize:18}}>Panel Docente</h2>
      </div>
      <input type="password" value={pw} onChange={e=>setPw(e.target.value)}
        onKeyDown={e=>e.key==="Enter"&&submit()} placeholder="Contraseña..."
        style={{width:"100%",padding:"11px 14px",borderRadius:12,border:`2px solid ${err?G8_P.warn:G8_P.border}`,
          fontSize:14,fontWeight:700,outline:"none",color:G8_P.text,marginBottom:7}}/>
      {err&&<p style={{color:G8_P.warn,fontSize:11,fontWeight:700,margin:"0 0 9px"}}>⚠️ Contraseña incorrecta</p>}
      <div style={{display:"flex",gap:7,marginTop:5}}>
        <button onClick={onCancel} style={{flex:1,padding:"9px 0",borderRadius:12,border:`2px solid ${G8_P.border}`,
          background:"#fff",color:G8_P.muted,fontWeight:700,cursor:"pointer"}}>Cancelar</button>
        <button onClick={submit} style={{flex:1,padding:"9px 0",borderRadius:12,border:"none",
          background:G8_P.primary,color:"#fff",fontWeight:900,cursor:"pointer"}}>Entrar</button>
      </div>
    </div>
  </div>;
};

// ══════════════════════════════════════════════════════════════
//  ADMIN PANEL
// ══════════════════════════════════════════════════════════════
const G8_AdminPanel=({onClose})=>{
  const [players,setPlayers]=useState(G8_loadPlayers);
  const [tab,setTab]=useState("stats");
  const allQ=G8_MISSIONS.flatMap(m=>m.questions);
  const competencies=["Comprensión literal","Competencia lingüística","Vocabulario contextual"];
  const qStats=allQ.map(q=>{
    const attempts=players.map(p=>(p.answers||{})[q.id]).filter(Boolean);
    const correct=attempts.filter(a=>a.correct).length;
    const pct=attempts.length?Math.round((correct/attempts.length)*100):null;
    return{q,attempts:attempts.length,correct,pct};
  });
  // ICFES-style domain breakdown: Vocabulario / Gramática / Semántica
  const DOMAINS=["Vocabulario","Gramática","Semántica"];
  const domainStats=DOMAINS.map(dom=>{
    const qs=qStats.filter(s=>(s.q.domain||"Semántica")===dom&&s.pct!==null);
    const avg=qs.length?Math.round(qs.reduce((s,r)=>s+r.pct,0)/qs.length):null;
    return{domain:dom,avg,count:qs.length};
  });
  // Per CEFR level breakdown (A1 / A2)
  const LEVELS=["A1","A2"];
  const levelStats=LEVELS.map(lvl=>{
    const qs=qStats.filter(s=>s.q.lvl===lvl&&s.pct!==null);
    const avg=qs.length?Math.round(qs.reduce((s,r)=>s+r.pct,0)/qs.length):null;
    return{lvl,avg,count:qs.length};
  });
  // Cross table: Domain × Level
  const domainLevelMatrix=DOMAINS.map(dom=>({
    domain:dom,
    levels:LEVELS.map(lvl=>{
      const qs=qStats.filter(s=>(s.q.domain||"Semántica")===dom&&s.q.lvl===lvl&&s.pct!==null);
      const avg=qs.length?Math.round(qs.reduce((s,r)=>s+r.pct,0)/qs.length):null;
      return{lvl,avg};
    })
  }));
  // Weakest specific skills (ICFES style — pinpoint exact failing skill)
  const weakSkills=qStats.filter(s=>s.pct!==null&&s.pct<60).sort((a,b)=>a.pct-b.pct).slice(0,6);
  const strongSkills=qStats.filter(s=>s.pct!==null&&s.pct>=80).slice(0,4);
  const alerts=players.filter(p=>{
    const ans=Object.values(p.answers||{});
    if(!ans.length)return false;
    return Math.round((ans.filter(a=>a.correct).length/ans.length)*100)<50;
  });
  const exportCSV=()=>{
    if(!players.length){alert("Sin datos.");return;}
    const fecha=new Date().toLocaleDateString("es-CO");
    const header=`Nombre,XP,Monedas,Misiones,Total Correctas,% Global,Ultima Sesion`;
    const rows=players.map(p=>{
      const ans=Object.values(p.answers||{});
      const tc=ans.filter(a=>a.correct).length;
      const pct=ans.length?Math.round((tc/ans.length)*100):0;
      return`"${p.name}",${p.xp||0},${p.coins||0},${(p.completedMissions||[]).length},${tc},${pct}%,"${p.lastSeen||""}"`;
    });
    const csv="\uFEFF"+[header,...rows].join("\n");
    const blob=new Blob([csv],{type:"text/csv;charset=utf-8;"});
    const url=URL.createObjectURL(blob);const a=document.createElement("a");
    a.href=url;a.download=`Guardians_G8_${fecha.replace(/\//g,"-")}.csv`;
    document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);
  };
  return <div style={{minHeight:"100vh",background:G8_P.bg,padding:13}}>
    <style>{G8_CSS}</style>
    <div style={{maxWidth:860,margin:"0 auto"}}>
      <div style={{display:"flex",alignItems:"center",gap:11,marginBottom:14,
        background:G8_P.card,borderRadius:17,padding:"13px 17px",
        boxShadow:"0 2px 13px rgba(249,115,22,.08)"}}>
        <div style={{width:44,height:44,borderRadius:"50%",flexShrink:0,
          background:`linear-gradient(135deg,${G8_P.primary},${G8_P.purple})`,
          display:"flex",alignItems:"center",justifyContent:"center",fontSize:20}}>👨‍🏫</div>
        <div style={{flex:1}}>
          <div style={{fontWeight:900,fontSize:15,color:G8_P.text}}>English Guardians G8 — Panel Docente</div>
          <div style={{fontSize:11,color:G8_P.muted}}>I.E. La Amistad • Grado 8° • Mg. Anderson</div>
        </div>
        <button onClick={onClose} style={{background:"#FEE2E2",border:"none",borderRadius:9,
          padding:"6px 13px",color:G8_P.warn,fontWeight:700,cursor:"pointer",fontSize:12}}>✕ Salir</button>
      </div>
      <div style={{display:"flex",gap:6,marginBottom:13,flexWrap:"wrap"}}>
        {[{id:"stats",l:"📊 Estadísticas"},{id:"students",l:"👥 Estudiantes"},{id:"questions",l:"📋 Preguntas"},{id:"export",l:"📤 Exportar"}].map(t=>(
          <button key={t.id} onClick={()=>setTab(t.id)} style={{padding:"7px 15px",borderRadius:12,border:"none",
            background:tab===t.id?G8_P.primary:"#fff",color:tab===t.id?"#fff":G8_P.muted,
            fontWeight:700,cursor:"pointer",fontSize:12,
            boxShadow:tab===t.id?`0 2px 9px ${G8_P.primary}44`:"0 1px 3px rgba(0,0,0,.05)"}}>
            {t.l}
          </button>
        ))}
      </div>

      {/* STATS */}
      {tab==="stats"&&<div className="slideUp">
        <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",gap:9,marginBottom:13}}>
          {[{v:players.length,l:"Estudiantes",c:G8_P.primary,i:"👥"},
            {v:`${qStats.filter(s=>s.pct!==null).length?Math.round(qStats.filter(s=>s.pct!==null).reduce((s,r)=>s+r.pct,0)/qStats.filter(s=>s.pct!==null).length):0}%`,l:"Aciertos global",c:G8_P.accent,i:"🎯"},
            {v:players.reduce((s,p)=>s+Object.values(p.answers||{}).filter(a=>a.correct).length,0),l:"Correctas totales",c:G8_P.accent,i:"✅"},
            {v:alerts.length,l:"En riesgo",c:G8_P.warn,i:"🚨"},
          ].map((s,i)=>(
            <div key={i} style={{background:G8_P.card,borderRadius:13,padding:"13px 15px",border:`1.5px solid ${s.c}33`}}>
              <div style={{fontSize:19,marginBottom:3}}>{s.i}</div>
              <div style={{fontWeight:900,fontSize:21,color:s.c}}>{s.v}</div>
              <div style={{fontSize:11,color:G8_P.muted}}>{s.l}</div>
            </div>
          ))}
        </div>

        {/* DOMAIN ANALYSIS — Vocabulario / Gramática / Semántica (ICFES style) */}
        <div style={{background:G8_P.card,borderRadius:17,padding:17,marginBottom:13,border:`1.5px solid ${G8_P.border}`}}>
          <div style={{fontWeight:800,fontSize:13,color:G8_P.text,marginBottom:3}}>🧠 Análisis por Competencia (estilo ICFES)</div>
          <p style={{fontSize:11,color:G8_P.muted,margin:"0 0 13px"}}>Vocabulario, Gramática y Semántica — para identificar exactamente en qué están fallando.</p>
          <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:9,marginBottom:14}}>
            {domainStats.map(d=>(
              <div key={d.domain} style={{textAlign:"center",padding:"12px 6px",borderRadius:13,
                background:d.avg===null?"#F8FAFC":d.avg>=70?`${G8_P.accent}12`:d.avg>=50?`${G8_P.gold}12`:`${G8_P.warn}12`,
                border:`1.5px solid ${d.avg===null?G8_P.border:d.avg>=70?G8_P.accent:d.avg>=50?G8_P.gold:G8_P.warn}44`}}>
                <div style={{fontSize:16,fontWeight:900,
                  color:d.avg===null?G8_P.muted:d.avg>=70?G8_P.accent:d.avg>=50?G8_P.gold:G8_P.warn}}>
                  {d.avg===null?"—":d.avg+"%"}
                </div>
                <div style={{fontSize:10,fontWeight:700,color:G8_P.muted,marginTop:3}}>{d.domain}</div>
              </div>
            ))}
          </div>
          {/* Domain × Level matrix */}
          <div style={{fontSize:11,fontWeight:700,color:G8_P.muted,marginBottom:8}}>Desglose por Competencia y Nivel CEFR</div>
          <div style={{overflowX:"auto",marginBottom:14}}>
            <table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}>
              <thead><tr style={{background:`${G8_P.primary}12`}}>
                <th style={{padding:"6px 9px",textAlign:"left",fontWeight:700,color:G8_P.primary}}>Competencia</th>
                {LEVELS.map(l=>(<th key={l} style={{padding:"6px 9px",fontWeight:700,color:G8_P.primary}}>{l}</th>))}
              </tr></thead>
              <tbody>
                {domainLevelMatrix.map((row,i)=>(
                  <tr key={row.domain} style={{background:i%2?"#fff":"#FFF7ED"}}>
                    <td style={{padding:"7px 9px",fontWeight:700,color:G8_P.text}}>{row.domain}</td>
                    {row.levels.map(lv=>(
                      <td key={lv.lvl} style={{padding:"7px 9px",textAlign:"center",fontWeight:800,
                        color:lv.avg===null?G8_P.muted:lv.avg>=70?G8_P.accent:lv.avg>=50?G8_P.gold:G8_P.warn}}>
                        {lv.avg===null?"—":lv.avg+"%"}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {/* Strengths / Weaknesses specific skills */}
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
            <div style={{background:"#ECFDF5",borderRadius:13,padding:12,border:"1.5px solid #10B98133"}}>
              <div style={{fontWeight:800,fontSize:12,color:G8_P.accent,marginBottom:8}}>✅ Fortalezas</div>
              {strongSkills.length?strongSkills.map(s=>(
                <div key={s.q.id} style={{fontSize:10,color:"#065F46",marginBottom:6}}>
                  <span style={{fontWeight:700}}>{s.q.domain||"Semántica"}</span> ({s.q.lvl}) — {s.pct}%
                  <div style={{color:G8_P.muted,fontSize:9}}>{s.q.skill}</div>
                </div>
              )):<div style={{fontSize:11,color:G8_P.muted}}>Sin datos suficientes</div>}
            </div>
            <div style={{background:"#FEF2F2",borderRadius:13,padding:12,border:"1.5px solid #EF444433"}}>
              <div style={{fontWeight:800,fontSize:12,color:G8_P.warn,marginBottom:8}}>❌ Debilidades</div>
              {weakSkills.length?weakSkills.map(s=>(
                <div key={s.q.id} style={{fontSize:10,color:"#991B1B",marginBottom:6}}>
                  <span style={{fontWeight:700}}>{s.q.domain||"Semántica"}</span> ({s.q.lvl}) — {s.pct}%
                  <div style={{color:G8_P.muted,fontSize:9}}>{s.q.skill}</div>
                </div>
              )):<div style={{fontSize:11,color:G8_P.muted}}>Sin datos suficientes</div>}
            </div>
          </div>
        </div>

        <div style={{background:G8_P.card,borderRadius:17,padding:17,marginBottom:13,border:`1.5px solid ${G8_P.border}`}}>
          <div style={{fontWeight:800,fontSize:13,color:G8_P.text,marginBottom:11}}>🗺️ Progreso por Misión</div>
          {G8_MISSIONS.map(m=>{
            const mQ=m.questions;
            const mVals=mQ.map(q=>{
              const a=players.map(p=>(p.answers||{})[q.id]).filter(Boolean);
              return a.length?Math.round((a.filter(x=>x.correct).length/a.length)*100):null;
            }).filter(v=>v!==null);
            const avg=mVals.length?Math.round(mVals.reduce((s,v)=>s+v,0)/mVals.length):null;
            const comp=players.filter(p=>(p.completedMissions||[]).includes(m.id)).length;
            return <div key={m.id} style={{marginBottom:11}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:3}}>
                <span style={{fontSize:13,fontWeight:700,color:G8_P.text}}>{m.emoji} {m.name}</span>
                <span style={{fontSize:11,color:G8_P.muted}}>{comp} completaron • {avg!==null?avg+"%":"sin datos"}</span>
              </div>
              <div style={{height:7,borderRadius:7,background:"#FED7AA",overflow:"hidden"}}>
                <div style={{height:"100%",borderRadius:7,
                  background:avg===null?G8_P.muted:avg>=70?G8_P.accent:avg>=50?G8_P.gold:G8_P.warn,
                  width:`${avg||0}%`,transition:"width .8s"}}/>
              </div>
            </div>;
          })}
        </div>
        <div style={{background:G8_P.card,borderRadius:17,padding:17,border:`1.5px solid ${G8_P.border}`}}>
          <div style={{fontWeight:800,fontSize:13,color:G8_P.text,marginBottom:11}}>🔥 Heatmap de Preguntas</div>
          <div style={{display:"flex",gap:4,flexWrap:"wrap"}}>
            {qStats.map(s=>{
              const bg=s.pct===null?"#F1F5F9":s.pct>=80?"#DCFCE7":s.pct>=60?"#FEF9C3":s.pct>=40?"#FFEDD5":"#FEE2E2";
              const bc=s.pct===null?G8_P.border:s.pct>=80?"#10B981":s.pct>=60?G8_P.gold:s.pct>=40?"#F97316":G8_P.warn;
              return <div key={s.q.id} style={{width:42,height:42,borderRadius:9,background:bg,
                border:`1.5px solid ${bc}`,display:"flex",flexDirection:"column",
                alignItems:"center",justifyContent:"center",gap:1}}>
                <span style={{fontSize:7,fontWeight:700,color:G8_P.muted}}>{s.q.id}</span>
                <span style={{fontSize:10,fontWeight:900,color:bc}}>{s.pct===null?"—":s.pct+"%"}</span>
              </div>;
            })}
          </div>
          <div style={{display:"flex",gap:7,marginTop:9,flexWrap:"wrap",fontSize:10,color:G8_P.muted}}>
            {[{c:"#DCFCE7",l:"≥80%"},{c:"#FEF9C3",l:"60-79%"},{c:"#FFEDD5",l:"40-59%"},{c:"#FEE2E2",l:"<40%"}].map(x=>(
              <div key={x.l} style={{display:"flex",alignItems:"center",gap:3}}>
                <div style={{width:10,height:10,borderRadius:2,background:x.c}}/>
                <span>{x.l}</span>
              </div>
            ))}
          </div>
        </div>
      </div>}

      {/* STUDENTS */}
      {tab==="students"&&<div className="slideUp">
        {!players.length&&<div style={{textAlign:"center",padding:44,color:G8_P.muted,background:G8_P.card,borderRadius:17}}>
          <div style={{fontSize:42,marginBottom:9}}>👥</div><p style={{fontWeight:700}}>Sin estudiantes registrados.</p>
        </div>}
        <div style={{display:"flex",flexDirection:"column",gap:7}}>
          {[...players].sort((a,b)=>(b.xp||0)-(a.xp||0)).map((p,i)=>{
            const ans=Object.values(p.answers||{});
            const tc=ans.filter(a=>a.correct).length;
            const pct=ans.length?Math.round((tc/ans.length)*100):0;
            return <div key={p.name} style={{background:G8_P.card,borderRadius:13,padding:"11px 15px",
              border:`1.5px solid ${G8_P.border}`,display:"flex",alignItems:"center",gap:9}}>
              <span style={{fontSize:14,fontWeight:900,width:27,textAlign:"center",
                color:i===0?G8_P.gold:i===1?"#94A3B8":i===2?"#CD7F32":G8_P.muted}}>
                {i===0?"🥇":i===1?"🥈":i===2?"🥉":`#${i+1}`}
              </span>
              <div style={{flex:1}}>
                <div style={{fontWeight:800,color:G8_P.text,fontSize:13}}>{p.name}</div>
                <div style={{fontSize:10,color:G8_P.muted}}>Nv.{Math.floor((p.xp||0)/150)+1} • {p.lastSeen}</div>
              </div>
              <div style={{textAlign:"right"}}>
                <div style={{fontWeight:900,color:G8_P.gold,fontSize:12}}>⭐ {p.xp||0} XP</div>
                <div style={{fontSize:10,fontWeight:700,
                  color:pct>=70?G8_P.accent:pct>=50?G8_P.gold:G8_P.warn}}>{pct}% aciertos • {(p.completedMissions||[]).length}/4 misiones</div>
              </div>
            </div>;
          })}
        </div>
        {alerts.length>0&&<div style={{background:"#FEF2F2",border:`2px solid ${G8_P.warn}44`,borderRadius:15,padding:15,marginTop:13}}>
          <div style={{fontWeight:800,fontSize:13,color:G8_P.warn,marginBottom:9}}>🚨 Estudiantes en Riesgo</div>
          {alerts.map(p=>{
            const ans=Object.values(p.answers||{});
            const pct=ans.length?Math.round((ans.filter(a=>a.correct).length/ans.length)*100):0;
            return <div key={p.name} style={{background:"#fff",borderRadius:11,padding:"9px 13px",marginBottom:7}}>
              <div style={{display:"flex",justifyContent:"space-between"}}>
                <span style={{fontWeight:800,color:G8_P.text}}>{p.name}</span>
                <span style={{fontWeight:900,color:G8_P.warn}}>{pct}% aciertos</span>
              </div>
            </div>;
          })}
        </div>}
      </div>}

      {/* QUESTIONS */}
      {tab==="questions"&&<div className="slideUp">
        {G8_MISSIONS.map(m=>(
          <div key={m.id} style={{background:G8_P.card,borderRadius:17,padding:17,marginBottom:13,border:`1.5px solid ${m.color}33`}}>
            <div style={{display:"flex",alignItems:"center",gap:9,marginBottom:13}}>
              <span style={{fontSize:24}}>{m.emoji}</span>
              <div>
                <div style={{fontWeight:900,color:G8_P.text,fontSize:14}}>{m.num}. {m.name}</div>
                <span style={{fontSize:10,background:`${m.color}18`,color:m.color,padding:"2px 7px",borderRadius:20,fontWeight:700}}>
                  {m.level} • {m.topic}
                </span>
              </div>
            </div>
            <div style={{fontSize:12,color:G8_P.muted,fontStyle:"italic",marginBottom:11,
              background:m.bg,borderRadius:9,padding:"7px 11px"}}>{m.text}</div>
            <div style={{overflowX:"auto"}}>
              <table style={{width:"100%",borderCollapse:"collapse",fontSize:11}}>
                <thead><tr style={{background:`${m.color}12`}}>
                  {["ID","Pregunta","Respuesta Correcta","Competencia","Nivel","Dif.","Habilidad"].map(h=>(
                    <th key={h} style={{padding:"6px 7px",textAlign:"left",fontWeight:700,
                      color:m.color,borderBottom:`1.5px solid ${G8_P.border}`,whiteSpace:"nowrap"}}>{h}</th>
                  ))}
                </tr></thead>
                <tbody>
                  {m.questions.map((q,i)=>(
                    <tr key={q.id} style={{background:i%2===0?"#fff":"#FFF7ED"}}>
                      <td style={{padding:"6px 7px",fontWeight:800,color:G8_P.primary,whiteSpace:"nowrap"}}>{q.id}</td>
                      <td style={{padding:"6px 7px",color:G8_P.text,maxWidth:190,fontSize:11}}>{q.q}</td>
                      <td style={{padding:"6px 7px",fontWeight:700,color:G8_P.accent,whiteSpace:"nowrap",fontSize:11}}>
                        {["A","B","C","D"][q.ans]}. {q.opts[q.ans]}
                      </td>
                      <td style={{padding:"6px 7px",color:G8_P.purple,fontWeight:700,whiteSpace:"nowrap",fontSize:10}}>{q.competency}</td>
                      <td style={{padding:"6px 7px",whiteSpace:"nowrap"}}>
                        <span style={{background:`${m.color}18`,color:m.color,padding:"2px 5px",borderRadius:20,fontWeight:700,fontSize:9}}>{q.lvl}</span>
                      </td>
                      <td style={{padding:"6px 7px",textAlign:"center"}}>{"⭐".repeat(q.diff)}</td>
                      <td style={{padding:"6px 7px",color:G8_P.muted,fontSize:10,maxWidth:170}}>{q.skill}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        ))}
      </div>}

      {/* EXPORT */}
      {tab==="export"&&<div className="slideUp">
        <div style={{background:G8_P.card,borderRadius:17,padding:17,border:`1.5px solid ${G8_P.border}`}}>
          <div style={{fontWeight:800,fontSize:14,color:G8_P.text,marginBottom:13}}>📤 Exportar datos</div>
          {[
            {id:"csv",icon:"📊",label:"Excel / CSV",sub:"Abre directo en Excel",c:G8_P.accent,fn:exportCSV},
            {id:"json",icon:"🗂️",label:"JSON completo",sub:"Backup de todos los datos",c:G8_P.primary,fn:()=>{
              const blob=new Blob([JSON.stringify({jugadores:players,fecha:new Date().toLocaleDateString("es-CO")},null,2)],{type:"application/json"});
              const url=URL.createObjectURL(blob);const a=document.createElement("a");
              a.href=url;a.download="Guardians_G8.json";document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);
            }},
            {id:"print",icon:"🖨️",label:"Imprimir PDF",sub:"Reporte visual completo",c:G8_P.purple,fn:()=>{
              const rows=[...players].sort((a,b)=>(b.xp||0)-(a.xp||0)).map((p,i)=>{
                const ans=Object.values(p.answers||{});const tc=ans.filter(a=>a.correct).length;
                const pct=ans.length?Math.round((tc/ans.length)*100):0;
                return`<tr><td>#${i+1} ${p.name}</td><td>${p.xp||0}</td><td>${pct}%</td><td>${(p.completedMissions||[]).length}/4</td></tr>`;
              }).join("");
              const html=`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Guardians G8</title><style>body{font-family:Arial;padding:16px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #e2e8f0;padding:7px}th{background:#f97316;color:#fff}</style></head><body><h2 style="color:#f97316">⚔️ English Guardians G8 — Grado 8°</h2><p>I.E. La Amistad • Mg. Anderson • ${new Date().toLocaleDateString("es-CO")}</p><table><thead><tr><th>Estudiante</th><th>XP</th><th>% Aciertos</th><th>Misiones</th></tr></thead><tbody>${rows}</tbody></table><script>window.onload=()=>window.print();</script></body></html>`;
              const w=window.open("","_blank");w.document.write(html);w.document.close();
            }},
          ].map(o=>(
            <button key={o.id} onClick={o.fn} style={{display:"flex",alignItems:"center",gap:11,
              width:"100%",padding:"12px 15px",borderRadius:13,marginBottom:8,
              border:`2px solid ${o.c}44`,background:`${o.c}0D`,
              color:G8_P.text,cursor:"pointer",textAlign:"left"}}>
              <span style={{fontSize:25}}>{o.icon}</span>
              <div style={{flex:1}}>
                <div style={{fontWeight:800,fontSize:13}}>{o.label}</div>
                <div style={{fontSize:11,color:G8_P.muted}}>{o.sub}</div>
              </div>
              <span style={{color:o.c,fontSize:16}}>↓</span>
            </button>
          ))}
        </div>
      </div>}
    </div>
  </div>;
};

// ══════════════════════════════════════════════════════════════
//  MAIN APP
// ══════════════════════════════════════════════════════════════
function G8Game(){
  const [started,setStarted]=useState(false);
  const [playerName,setPlayerName]=useState("Estudiante");
  const [avatar,setAvatar]=useState(G8_AVATARS[0]);
  const [xp,setXp]=useState(0);const [coins,setCoins]=useState(0);const [lives,setLives]=useState(5);
  const [completed,setCompleted]=useState([]);const [answers,setAnswers]=useState({});
  const [screen,setScreen]=useState("home");const [selMission,setSelMission]=useState(null);
  const [showLogin,setShowLogin]=useState(false);const [showAdmin,setShowAdmin]=useState(false);
  const [toast,setToast]=useState(null);
  const showToast=(msg,color)=>setToast({msg,color});
  const handleStart=(name,av)=>{
    setPlayerName(name);setAvatar(av);
    const ex=G8_loadPlayers().find(p=>p.name===name);
    if(ex){setXp(ex.xp||0);setCoins(ex.coins||0);setLives(ex.lives||5);setCompleted(ex.completedMissions||[]);setAnswers(ex.answers||{});
      if(ex.avatarId)setAvatar(G8_AVATARS.find(a=>a.id===ex.avatarId)||av);}
    setStarted(true);
  };
  const handleNameChange=name=>{
    setPlayerName(name);
    const ex=G8_loadPlayers().find(p=>p.name===name);
    if(ex){setXp(ex.xp||0);setCoins(ex.coins||0);setLives(ex.lives||5);setCompleted(ex.completedMissions||[]);setAnswers(ex.answers||{});}
  };
  const handleAvatarChange=av=>{
    setAvatar(av);
    G8_savePlayers(G8_upsertPlayer(G8_loadPlayers(),playerName,{xp,coins,lives,completedMissions:completed,answers,avatarId:av.id}));
    showToast(`${av.emoji} ¡Avatar cambiado!`,G8_P.purple);
  };
  const handleRecordAnswer=(qId,correct,qData)=>{
    const na={...answers,[qId]:{correct,competency:qData.competency,domain:qData.domain||"Semántica",lvl:qData.lvl,diff:qData.diff}};
    setAnswers(na);G8_savePlayers(G8_upsertPlayer(G8_loadPlayers(),playerName,{xp,coins,lives,completedMissions:completed,answers:na,avatarId:avatar.id}));
  };
  const handleEarnReward=(mission,win)=>{
    const eXp=win?mission.xp:Math.round(mission.xp*.4);const eCoins=win?mission.coins:Math.round(mission.coins*.3);
    const nXp=xp+eXp,nCoins=coins+eCoins;
    const nComp=win&&!completed.includes(mission.id)?[...completed,mission.id]:completed;
    setXp(nXp);setCoins(nCoins);if(win)setCompleted(nComp);else setLives(l=>Math.max(0,l-1));
    G8_savePlayers(G8_upsertPlayer(G8_loadPlayers(),playerName,{xp:nXp,coins:nCoins,lives,completedMissions:nComp,answers,avatarId:avatar.id}));
    showToast(win?`🏆 +${eXp} XP • 🪙 +${eCoins}`:`💪 +${eXp} XP de práctica`,win?G8_P.accent:G8_P.gold);
    setScreen("home");setSelMission(null);
  };
  if(!started)return <G8_WelcomeScreen onStart={handleStart}/>;
  if(showAdmin)return <G8_AdminPanel onClose={()=>setShowAdmin(false)}/>;
  return <div style={{minHeight:"100vh",background:G8_P.bg}}>
    <style>{G8_CSS}</style>
    {showLogin&&<G8_AdminLogin onSuccess={()=>{setShowLogin(false);setShowAdmin(true);}} onCancel={()=>setShowLogin(false)}/>}
    {toast&&<G8_Toast msg={toast.msg} color={toast.color} onDone={()=>setToast(null)}/>}
    <div style={{maxWidth:720,margin:"0 auto",padding:"13px 12px"}}>
      <div style={{textAlign:"center",marginBottom:14}}>
        <div style={{display:"inline-flex",alignItems:"center",gap:5,background:`${G8_P.primary}12`,
          border:`1px solid ${G8_P.primary}33`,borderRadius:30,padding:"3px 11px",marginBottom:7,
          fontSize:11,color:G8_P.primary,fontWeight:700}}>
          🏫 I.E. La Amistad • Grado 8° • Mg. Anderson
        </div>
        <h1 style={{margin:0,fontWeight:900,fontSize:24,
          background:`linear-gradient(90deg,${G8_P.primary},${G8_P.purple},${G8_P.pink})`,
          WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",lineHeight:1.2}}>
          ⚔️ English Guardians G8
        </h1>
        <p style={{color:G8_P.muted,fontSize:12,margin:"3px 0 0"}}>Presente Simple • Comparativos • Superlativos • A1/A2</p>
      </div>
      <div style={{display:"flex",gap:6,marginBottom:13}}>
        {[{id:"home",l:"🏠 Misiones"},{id:"ranking",l:"🏆 Ranking"}].map(t=>(
          <button key={t.id} onClick={()=>{setScreen(t.id);setSelMission(null);}}
            style={{padding:"7px 15px",borderRadius:12,border:"none",
              background:screen===t.id?G8_P.primary:"#fff",color:screen===t.id?"#fff":G8_P.muted,
              fontWeight:700,cursor:"pointer",fontSize:12,
              boxShadow:screen===t.id?`0 2px 9px ${G8_P.primary}44`:"0 1px 4px rgba(0,0,0,.06)"}}>
            {t.l}
          </button>
        ))}
        <button onClick={()=>setShowLogin(true)} style={{marginLeft:"auto",padding:"7px 10px",borderRadius:12,
          border:"none",background:"#fff",color:"#94A3B8",cursor:"pointer",fontSize:11,
          boxShadow:"0 1px 4px rgba(0,0,0,.06)"}}>🔐</button>
      </div>
      {screen!=="mission"&&<G8_PlayerHUD name={playerName} xp={xp} coins={coins} lives={lives}
        avatar={avatar} onNameChange={handleNameChange} onAvatarChange={handleAvatarChange}/>}
      {screen==="home"&&!selMission&&<G8_MissionGrid completed={completed} onSelect={m=>{setSelMission(m);setScreen("mission");}}/>}
      {screen==="ranking"&&<G8_RankingPanel playerName={playerName}/>}
      {screen==="mission"&&selMission&&(
        <G8_MissionDetail mission={selMission}
          onBack={()=>{setScreen("home");setSelMission(null);}}
          onEarnReward={handleEarnReward} onRecordAnswer={handleRecordAnswer}/>
      )}
      <div style={{textAlign:"center",marginTop:26,color:"#CBD5E1",fontSize:10}}>
        English Guardians G8 © 2026 • Grado 8° • I.E. La Amistad
      </div>
    </div>
  </div>;
}
const JUEGOS = [
  {id:1,grado:"67",  titulo:"Misión 1",subtitulo:"English Guardians G6-G7",xp:150,dificultad:"Básico",  icono:"🚀",bloqueado:false,componente:G67Game},
  {id:2,grado:"67",  titulo:"Misión 2",subtitulo:"Grado 6° y 7°",        xp:200,dificultad:"Medio",   icono:"⭐",bloqueado:true, componente:null},
  {id:3,grado:"8",   titulo:"Misión 3",subtitulo:"English Guardians G8",   xp:250,dificultad:"Básico",  icono:"🌍",bloqueado:false,componente:G8Game},
  {id:4,grado:"9",   titulo:"Misión 4",subtitulo:"English Guardians Jr",  xp:300,dificultad:"Medio",   icono:"🔭",bloqueado:false,componente:EnglishGuardiansJr},
  {id:5,grado:"1011",titulo:"Misión 5",subtitulo:"Grado 10° y 11°",      xp:350,dificultad:"Avanzado",icono:"🧠",bloqueado:false,componente:null},
  {id:6,grado:"1011",titulo:"Misión 6",subtitulo:"Grado 10° y 11°",      xp:400,dificultad:"Avanzado",icono:"💡",bloqueado:true, componente:null},
  {id:7,grado:"icfes",titulo:"ICFES I",subtitulo:"English Guardians V3",  xp:600,dificultad:"ICFES",   icono:"🏆",bloqueado:false,componente:EnglishGuardiansV3},
  {id:8,grado:"icfes",titulo:"ICFES II",subtitulo:"Simulacro ICFES II",   xp:800,dificultad:"ICFES",   icono:"🎯",bloqueado:true, componente:null},
];

function ComingSoon({j}) {
  const m = GRADO_META_JUEGOS[j.grado];
  return (
    <div style={{display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",minHeight:"60vh",gap:18,textAlign:"center",padding:40,background:"#060e2a",color:"#e8f4fd"}}>
      <div style={{fontSize:64}}>{j.icono}</div>
      <div style={{padding:"5px 18px",borderRadius:30,background:"rgba(59,130,246,0.12)",border:"1px solid rgba(59,130,246,0.3)",fontSize:11,fontWeight:700,color:"#93c5fd",letterSpacing:1}}>PRÓXIMAMENTE</div>
      <div style={{fontFamily:"'Space Grotesk',sans-serif",fontSize:22,fontWeight:800}}>{j.titulo} · {j.subtitulo}</div>
      <div style={{fontSize:13,color:"#7a9cc0",maxWidth:360,lineHeight:1.7}}>Este juego está en desarrollo y aparecerá aquí automáticamente.</div>
      <div style={{padding:"10px 24px",borderRadius:30,background:"rgba(0,245,160,0.1)",border:"1px solid rgba(0,245,160,0.25)",fontSize:14,fontWeight:700,color:"#00f5a0"}}>⚡ {j.xp} XP al completar</div>
    </div>
  );
}

function HexCell({j, onClick, onShare, copied}) {
  const m   = GRADO_META_JUEGOS[j.grado];
  const [hov,setHov] = useState(false);
  const isIcfes = j.grado === "icfes";
  const sz = isIcfes ? 220 : 200;
  return (
    <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:6}}>
      <div
        className={`pje-hex${j.bloqueado?" locked":""}`}
        style={{width:sz,height:sz*1.09,filter:j.bloqueado?undefined:`drop-shadow(0 0 ${hov?"22":"10"}px ${m.glow})`,transform:hov&&!j.bloqueado?"scale(1.06) translateY(-4px)":"scale(1)",transition:"all .25s"}}
        onClick={()=>!j.bloqueado&&onClick(j)}
        onMouseEnter={()=>setHov(true)} onMouseLeave={()=>setHov(false)}
      >
        <div className="pje-hex-inner" style={{background:j.bloqueado?"linear-gradient(145deg,#1a2040,#111830)":m.bg}}>
          {j.bloqueado && <span style={{position:"absolute",top:14,right:20,fontSize:16}}>🔒</span>}
          <div className="pje-hex-emoji">{j.icono}</div>
          <div className="pje-hex-title">{j.titulo}</div>
          <div className="pje-hex-grade">{m.label}</div>
          <div className="pje-hex-xp">⚡ {j.xp} XP</div>
          <div className="pje-hex-status" style={{background:j.bloqueado?"rgba(255,255,255,0.05)":j.componente?"rgba(0,245,160,0.2)":"rgba(255,255,255,0.08)",color:j.bloqueado?"rgba(255,255,255,0.2)":j.componente?"#00f5a0":"rgba(255,255,255,0.35)"}}>
            {j.bloqueado?"Bloqueado":j.componente?"¡Jugar!":"Próximamente"}
          </div>
        </div>
      </div>
      {!j.bloqueado && (
        <button onClick={e=>{e.stopPropagation();onShare&&onShare(j,e);}}
          style={{padding:"4px 14px",borderRadius:20,border:`1px solid ${copied===j.id?"rgba(0,245,160,0.4)":"rgba(255,255,255,0.12)"}`,background:copied===j.id?"rgba(0,245,160,0.12)":"rgba(255,255,255,0.05)",color:copied===j.id?"#00f5a0":"rgba(255,255,255,0.4)",fontSize:11,fontWeight:700,cursor:"pointer",transition:"all .22s"}}>
          {copied===j.id?"✅ ¡Copiado!":"🔗 Compartir"}
        </button>
      )}
    </div>
  );
}

function PanelJuegosEstudiantes() {
  const [filtro,  setFiltro] = useState("todos");
  const [activo,  setActivo] = useState(null);
  const [copied,  setCopied] = useState(null);

  useEffect(()=>{
    const p = new URLSearchParams(window.location.search);
    const jid = p.get("juego");
    if (jid) {
      const found = JUEGOS.find(j=>String(j.id)===jid&&!j.bloqueado);
      if (found) setActivo(found);
    }
  },[]);

  const handleShare=(j,e)=>{
    e.stopPropagation();
    const url=`${window.location.origin}${window.location.pathname}?juego=${j.id}`;
    navigator.clipboard.writeText(url).then(()=>{setCopied(j.id);setTimeout(()=>setCopied(null),2200);});
  };

  const misiones  = JUEGOS.filter(j=>j.grado!=="icfes"&&(filtro==="todos"||filtro===j.grado));
  const icfes     = JUEGOS.filter(j=>j.grado==="icfes");
  const showIcfes = filtro==="todos"||filtro==="icfes";
  const row1=misiones.slice(0,3), row2=misiones.slice(3,6);

  const GameComp = activo?.componente;

  return (
    <>
      <style>{CSS_PANEL}</style>

      {/* LAUNCHER */}
      {activo && (
        <div className="pje-launcher">
          <div className="pje-launcher-bar">
            <button className="pje-back-btn" onClick={()=>setActivo(null)}>
              <svg width={16} height={16} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2.5} strokeLinecap="round"><path d="M19 12H5M12 5l-7 7 7 7"/></svg>
              Volver al mundo
            </button>
            <div style={{fontFamily:"'Space Grotesk',sans-serif",fontSize:15,fontWeight:800,color:GRADO_META_JUEGOS[activo.grado].color}}>{activo.icono} {activo.titulo} · {activo.subtitulo}</div>
            <div style={{marginLeft:"auto",display:"flex",alignItems:"center",gap:12}}>
              <span style={{fontSize:12,color:"#7a9cc0"}}>⚡ {activo.xp} XP · {activo.dificultad}</span>
              <button onClick={()=>handleShare(activo,{stopPropagation:()=>{}})} style={{padding:"6px 16px",borderRadius:20,border:`1px solid ${copied===activo.id?"rgba(0,245,160,0.4)":"rgba(255,255,255,0.15)"}`,background:copied===activo.id?"rgba(0,245,160,0.12)":"rgba(255,255,255,0.06)",color:copied===activo.id?"#00f5a0":"rgba(255,255,255,0.55)",fontSize:12,fontWeight:700,cursor:"pointer"}}>
                {copied===activo.id?"✅ ¡Copiado!":"🔗 Compartir"}
              </button>
            </div>
          </div>
          <div style={{flex:1,overflowY:"auto"}}>
            {GameComp ? <GameComp /> : <ComingSoon j={activo}/>}
          </div>
        </div>
      )}

      <div className="pje-root">
        <div className="pje-inner">
          {/* HEADER */}
          <div style={{textAlign:"center",marginBottom:32}}>
            <div style={{display:"inline-flex",alignItems:"center",gap:8,padding:"5px 18px",borderRadius:30,background:"rgba(59,130,246,0.1)",border:"1px solid rgba(59,130,246,0.25)",fontSize:11,fontWeight:700,color:"#93c5fd",letterSpacing:1,textTransform:"uppercase",marginBottom:14}}>🐝 I.E. La Amistad · Mundo de Juegos</div>
            <div style={{fontFamily:"'Space Grotesk',sans-serif",fontSize:34,fontWeight:800,background:"linear-gradient(135deg,#e8f4fd 30%,#3b82f6 70%,#8b5cf6)",WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",marginBottom:8}}>🌐 Panal de Misiones</div>
            <div style={{fontSize:14,color:"#7a9cc0"}}>Selecciona tu grado y conquista cada misión</div>
          </div>

          {/* STATS */}
          <div style={{display:"flex",justifyContent:"center",gap:16,marginBottom:28,flexWrap:"wrap"}}>
            {[["🎮",JUEGOS.length,"Misiones"],["🔓",JUEGOS.filter(j=>!j.bloqueado).length,"Disponibles"],["⚡",`${JUEGOS.filter(j=>!j.bloqueado).reduce((s,j)=>s+j.xp,0).toLocaleString()} XP`,"En juego"],["🏆",icfes.length,"ICFES"]].map(([ic,v,l],i)=>(
              <div key={i} style={{display:"flex",alignItems:"center",gap:10,padding:"10px 18px",borderRadius:14,background:"rgba(255,255,255,0.04)",border:"1px solid rgba(255,255,255,0.07)"}}>
                <span style={{fontSize:20}}>{ic}</span>
                <div><div style={{fontFamily:"'Space Grotesk',sans-serif",fontSize:18,fontWeight:800}}>{v}</div><div style={{fontSize:10,color:"#7a9cc0"}}>{l}</div></div>
              </div>
            ))}
          </div>

          {/* PROGRESS */}
          <div style={{maxWidth:460,margin:"0 auto 28px"}}>
            <div style={{display:"flex",justifyContent:"space-between",fontSize:11,color:"#7a9cc0",marginBottom:6}}>
              <span>Juegos activos</span><span>{JUEGOS.filter(j=>j.componente).length} / {JUEGOS.length}</span>
            </div>
            <div style={{height:7,background:"rgba(255,255,255,0.06)",borderRadius:10,overflow:"hidden"}}>
              <div style={{height:"100%",width:`${(JUEGOS.filter(j=>j.componente).length/JUEGOS.length)*100}%`,background:"linear-gradient(90deg,#3b82f6,#8b5cf6,#00f5a0)",borderRadius:10,boxShadow:"0 0 12px rgba(59,130,246,0.4)"}}/>
            </div>
          </div>

          {/* FILTERS */}
          <div style={{display:"flex",justifyContent:"center",gap:8,marginBottom:40,flexWrap:"wrap"}}>
            {FILTROS.map(f=>(
              <button key={f.id} className={`pje-filter${filtro===f.id?" active":""}`} onClick={()=>setFiltro(f.id)}>{f.label}</button>
            ))}
          </div>

          {/* HONEYCOMB */}
          {misiones.length>0 && (
            <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:0,marginBottom:showIcfes?48:24}}>
              {row1.length>0 && <div style={{display:"flex",gap:14,marginBottom:-26,zIndex:2}}>{row1.map(j=><HexCell key={j.id} j={j} onClick={setActivo} onShare={handleShare} copied={copied}/>)}</div>}
              {row2.length>0 && <div style={{display:"flex",gap:14,marginLeft:95,zIndex:1}}>{row2.map(j=><HexCell key={j.id} j={j} onClick={setActivo} onShare={handleShare} copied={copied}/>)}</div>}
            </div>
          )}

          {/* ICFES */}
          {showIcfes && (
            <>
              <div style={{textAlign:"center",marginBottom:20}}>
                <div style={{display:"flex",alignItems:"center",justifyContent:"center",gap:12,fontFamily:"'Space Grotesk',sans-serif",fontSize:13,fontWeight:700,color:"#f59e0b",letterSpacing:2,textTransform:"uppercase"}}>
                  <div style={{height:1,width:70,background:"linear-gradient(90deg,transparent,rgba(245,158,11,0.5))"}}/>
                  🏆 Simulacros Tipo ICFES
                  <div style={{height:1,width:70,background:"linear-gradient(90deg,rgba(245,158,11,0.5),transparent)"}}/>
                </div>
              </div>
              <div style={{display:"flex",justifyContent:"center",gap:20,marginBottom:32}}>
                {icfes.map(j=><HexCell key={j.id} j={j} onClick={setActivo} onShare={handleShare} copied={copied}/>)}
              </div>
            </>
          )}

          {/* LEGEND */}
          <div style={{display:"flex",justifyContent:"center",gap:20,flexWrap:"wrap",marginTop:16}}>
            {[["#00f5a0","¡Jugar! — Activo"],["rgba(255,255,255,0.25)","Próximamente"],["rgba(255,255,255,0.1)","🔒 Bloqueado"]].map(([c,l],i)=>(
              <div key={i} style={{display:"flex",alignItems:"center",gap:6,fontSize:11,color:"#7a9cc0"}}>
                <div style={{width:7,height:7,borderRadius:"50%",background:c}}/>{l}
              </div>
            ))}
          </div>
        </div>
      </div>
    </>
  );
}

