// ─── STYLES ──────────────────────────────────────────────────────────────────
const css = `
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=Space+Grotesk:wght@400;500;600;700&display=swap');

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --bg-deep:    #081c50;
    --bg-panel:   #0d2464;
    --bg-card:    rgba(12, 38, 105, 0.62);
    --blue-e:     #2563ff;
    --blue-p:     #0f4c81;
    --silver:     #b8c7e0;
    --space-gray: #1a3872;
    --green-n:    #00f5a0;
    --purple-t:   #7c3aed;
    --ice-white:  #e8f4fd;
    --glow-blue:  rgba(37,99,255,0.35);
    --glow-green: rgba(0,245,160,0.25);
    --glow-purple:rgba(124,58,237,0.3);
    --text-main:  #e8f4fd;
    --text-muted: #7a9cc0;
    --border:     rgba(100,160,255,0.18);
  }

  body { background: linear-gradient(135deg, #081c50 0%, #0e2a6e 50%, #091f58 100%); font-family: 'Inter', sans-serif; color: var(--text-main); overflow: hidden; }

  /* Scrollbar */
  ::-webkit-scrollbar { width: 5px; }
  ::-webkit-scrollbar-track { background: transparent; }
  ::-webkit-scrollbar-thumb { background: rgba(37,99,255,0.4); border-radius: 10px; }

  /* ── SIDEBAR ── */
  .sidebar {
    position: fixed; left: 0; top: 0; bottom: 0; width: 240px;
    background: linear-gradient(180deg, rgba(10,28,70,0.98) 0%, rgba(8,20,55,0.98) 100%);
    border-right: 1px solid var(--border);
    backdrop-filter: blur(20px);
    z-index: 100;
    display: flex; flex-direction: column;
    transition: width .3s cubic-bezier(.4,0,.2,1);
    overflow: hidden;
  }
  .sidebar.collapsed { width: 70px; }
  .sidebar-logo {
    padding: 24px 20px 20px;
    display: flex; align-items: center; gap: 12px;
    border-bottom: 1px solid var(--border);
    min-height: 80px;
  }
  .logo-badge {
    width: 40px; height: 40px; border-radius: 12px; flex-shrink: 0;
    background: linear-gradient(135deg, var(--blue-e), var(--purple-t));
    display: flex; align-items: center; justify-content: center;
    font-weight: 800; font-size: 16px; color: #fff;
    box-shadow: 0 0 20px var(--glow-blue);
  }
  .logo-text { overflow: hidden; white-space: nowrap; }
  .logo-name { font-family: 'Space Grotesk', sans-serif; font-weight: 700; font-size: 13px; color: var(--ice-white); line-height: 1.2; }
  .logo-sub  { font-size: 10px; color: var(--text-muted); }

  .nav-section { flex: 1; overflow-y: auto; padding: 12px 10px; }
  .nav-label { font-size: 9px; text-transform: uppercase; letter-spacing: 1.5px; color: var(--text-muted); padding: 8px 10px 4px; white-space: nowrap; overflow: hidden; }

  .nav-item {
    display: flex; align-items: center; gap: 12px;
    padding: 11px 12px; border-radius: 12px; cursor: pointer;
    transition: all .22s ease; position: relative; overflow: hidden;
    white-space: nowrap; margin-bottom: 2px;
    color: var(--text-muted);
  }
  .nav-item:hover { background: rgba(37,99,255,0.12); color: var(--ice-white); }
  .nav-item:hover .nav-icon { filter: drop-shadow(0 0 6px var(--blue-e)); }
  .nav-item.active {
    background: linear-gradient(135deg, rgba(37,99,255,0.25), rgba(124,58,237,0.15));
    color: var(--ice-white);
    box-shadow: inset 0 0 0 1px rgba(37,99,255,0.3);
  }
  .nav-item.active::before {
    content: ''; position: absolute; left: 0; top: 20%; bottom: 20%;
    width: 3px; background: linear-gradient(180deg, var(--blue-e), var(--purple-t));
    border-radius: 0 3px 3px 0; box-shadow: 0 0 10px var(--glow-blue);
  }
  .nav-icon { flex-shrink: 0; width: 20px; height: 20px; transition: all .22s; }
  .nav-label-text { font-size: 13px; font-weight: 500; overflow: hidden; transition: opacity .2s; }
  .sidebar.collapsed .nav-label-text, .sidebar.collapsed .logo-text, .sidebar.collapsed .nav-label { opacity: 0; pointer-events: none; }
  .nav-badge {
    margin-left: auto; font-size: 10px; font-weight: 700; padding: 2px 7px;
    border-radius: 20px; background: var(--blue-e); color: #fff;
    box-shadow: 0 0 10px var(--glow-blue);
  }

  /* ── MAIN ── */
  .main { margin-left: 240px; height: 100vh; display: flex; flex-direction: column; transition: margin-left .3s; overflow: hidden; }
  .main.expanded { margin-left: 70px; }

  /* ── TOPBAR ── */
  .topbar {
    height: 70px; display: flex; align-items: center; gap: 16px;
    padding: 0 28px;
    background: linear-gradient(90deg, rgba(10,28,70,0.95) 0%, rgba(8,22,55,0.95) 100%);
    border-bottom: 1px solid var(--border);
    backdrop-filter: blur(12px);
    flex-shrink: 0;
  }
  .topbar-toggle {
    width: 36px; height: 36px; border-radius: 10px; border: 1px solid var(--border);
    background: var(--bg-card); cursor: pointer; display: flex; align-items: center; justify-content: center;
    color: var(--text-muted); transition: all .2s;
  }
  .topbar-toggle:hover { color: var(--ice-white); border-color: var(--blue-e); box-shadow: 0 0 12px var(--glow-blue); }
  .topbar-title { font-family: 'Space Grotesk', sans-serif; font-size: 18px; font-weight: 700; flex: 1; }
  .topbar-title span { color: var(--blue-e); }

  .search-bar {
    display: flex; align-items: center; gap: 10px;
    background: var(--bg-card); border: 1px solid var(--border);
    border-radius: 12px; padding: 8px 16px; width: 260px;
    transition: all .2s;
  }
  .search-bar:focus-within { border-color: var(--blue-e); box-shadow: 0 0 16px var(--glow-blue); }
  .search-bar input { background: none; border: none; outline: none; color: var(--ice-white); font-size: 13px; width: 100%; }
  .search-bar input::placeholder { color: var(--text-muted); }

  .topbar-actions { display: flex; align-items: center; gap: 10px; }
  .icon-btn {
    width: 38px; height: 38px; border-radius: 11px; border: 1px solid var(--border);
    background: var(--bg-card); cursor: pointer; display: flex; align-items: center; justify-content: center;
    color: var(--text-muted); transition: all .22s; position: relative;
  }
  .icon-btn:hover { color: var(--ice-white); border-color: rgba(37,99,255,0.5); box-shadow: 0 0 14px var(--glow-blue); }
  .notif-dot {
    position: absolute; top: 7px; right: 7px; width: 7px; height: 7px;
    background: var(--green-n); border-radius: 50%; border: 1.5px solid var(--bg-panel);
    box-shadow: 0 0 6px var(--green-n);
  }
  .avatar-btn {
    display: flex; align-items: center; gap: 10px; cursor: pointer;
    padding: 5px 12px 5px 5px; border-radius: 14px; border: 1px solid var(--border);
    background: var(--bg-card); transition: all .22s;
  }
  .avatar-btn:hover { border-color: rgba(37,99,255,0.4); box-shadow: 0 0 14px var(--glow-blue); }
  .avatar-circle {
    width: 32px; height: 32px; border-radius: 10px;
    background: linear-gradient(135deg, var(--blue-e), var(--purple-t));
    display: flex; align-items: center; justify-content: center;
    font-weight: 700; font-size: 13px; color: #fff;
    box-shadow: 0 0 12px var(--glow-blue);
  }
  .avatar-info { line-height: 1.2; }
  .avatar-name { font-size: 12px; font-weight: 600; color: var(--ice-white); }
  .avatar-role { font-size: 10px; color: var(--text-muted); }

  /* ── CONTENT ── */
  .content { flex: 1; overflow-y: auto; padding: 24px 28px; }

  /* ── CARDS ── */
  .glass-card {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 18px;
    backdrop-filter: blur(16px);
    transition: all .25s ease;
  }
  .glass-card:hover { border-color: rgba(37,99,255,0.25); box-shadow: 0 8px 40px rgba(0,0,0,0.3), 0 0 20px rgba(37,99,255,0.08); }

  /* ── STAT CARDS ── */
  .stats-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; margin-bottom: 24px; }
  .stat-card {
    padding: 22px; border-radius: 18px; position: relative; overflow: hidden;
    border: 1px solid var(--border); backdrop-filter: blur(16px);
    transition: all .25s; cursor: default;
  }
  .stat-card::before {
    content: ''; position: absolute; top: -40%; right: -20%;
    width: 100px; height: 100px; border-radius: 50%;
    opacity: .18; filter: blur(24px);
  }
  .stat-card:nth-child(1) { background: linear-gradient(135deg, rgba(37,99,255,0.15), rgba(37,99,255,0.05)); }
  .stat-card:nth-child(1)::before { background: var(--blue-e); }
  .stat-card:nth-child(2) { background: linear-gradient(135deg, rgba(0,245,160,0.12), rgba(0,245,160,0.04)); }
  .stat-card:nth-child(2)::before { background: var(--green-n); }
  .stat-card:nth-child(3) { background: linear-gradient(135deg, rgba(124,58,237,0.15), rgba(124,58,237,0.05)); }
  .stat-card:nth-child(3)::before { background: var(--purple-t); }
  .stat-card:nth-child(4) { background: linear-gradient(135deg, rgba(245,158,11,0.12), rgba(245,158,11,0.04)); }
  .stat-card:nth-child(4)::before { background: #f59e0b; }
  .stat-card:hover { transform: translateY(-3px); box-shadow: 0 12px 40px rgba(0,0,0,0.25); }
  .stat-icon { width: 44px; height: 44px; border-radius: 13px; display: flex; align-items: center; justify-content: center; margin-bottom: 14px; }
  .stat-card:nth-child(1) .stat-icon { background: rgba(37,99,255,0.2); box-shadow: 0 0 20px rgba(37,99,255,0.25); }
  .stat-card:nth-child(2) .stat-icon { background: rgba(0,245,160,0.15); box-shadow: 0 0 20px rgba(0,245,160,0.2); }
  .stat-card:nth-child(3) .stat-icon { background: rgba(124,58,237,0.2); box-shadow: 0 0 20px rgba(124,58,237,0.25); }
  .stat-card:nth-child(4) .stat-icon { background: rgba(245,158,11,0.15); box-shadow: 0 0 20px rgba(245,158,11,0.2); }
  .stat-value { font-family: 'Space Grotesk', sans-serif; font-size: 32px; font-weight: 800; line-height: 1; margin-bottom: 4px; }
  .stat-label { font-size: 12px; color: var(--text-muted); margin-bottom: 12px; }
  .stat-delta { font-size: 11px; font-weight: 600; display: flex; align-items: center; gap: 4px; }
  .delta-up { color: var(--green-n); }
  .delta-num { background: rgba(0,245,160,0.1); padding: 2px 8px; border-radius: 20px; }

  /* ── GRID LAYOUT ── */
  .grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-bottom: 20px; }
  .grid-3 { display: grid; grid-template-columns: 2fr 1fr; gap: 20px; margin-bottom: 20px; }

  /* ── SECTION TITLE ── */
  .sec-header { display: flex; align-items: center; justify-content: space-between; padding: 20px 22px 16px; }
  .sec-title { font-family: 'Space Grotesk', sans-serif; font-size: 16px; font-weight: 700; }
  .sec-sub { font-size: 12px; color: var(--text-muted); margin-top: 2px; }
  .sec-action { font-size: 12px; color: var(--blue-e); cursor: pointer; font-weight: 600; transition: opacity .2s; }
  .sec-action:hover { opacity: .7; }

  /* ── PROGRESS BAR ── */
  .progress-wrap { padding: 0 22px 18px; }
  .progress-item { margin-bottom: 14px; }
  .progress-meta { display: flex; justify-content: space-between; margin-bottom: 6px; }
  .progress-name { font-size: 13px; font-weight: 500; }
  .progress-pct  { font-size: 12px; color: var(--text-muted); }
  .progress-track { height: 6px; background: rgba(255,255,255,0.06); border-radius: 10px; overflow: hidden; }
  .progress-fill  { height: 100%; border-radius: 10px; position: relative; }
  .progress-fill::after {
    content: ''; position: absolute; right: 0; top: 0; bottom: 0; width: 12px;
    background: rgba(255,255,255,0.4); border-radius: 10px; filter: blur(2px);
  }

  /* ── ACTIVITY LIST ── */
  .activity-list { padding: 0 22px 18px; }
  .activity-item { display: flex; align-items: center; gap: 14px; padding: 12px 0; border-bottom: 1px solid rgba(255,255,255,0.04); }
  .activity-item:last-child { border-bottom: none; }
  .act-dot { width: 38px; height: 38px; border-radius: 11px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
  .act-info { flex: 1; }
  .act-title { font-size: 13px; font-weight: 500; margin-bottom: 2px; }
  .act-time  { font-size: 11px; color: var(--text-muted); }
  .act-badge { font-size: 10px; padding: 3px 10px; border-radius: 20px; font-weight: 600; white-space: nowrap; }

  /* ── XP BAR ── */
  .xp-section { padding: 18px 22px; }
  .xp-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }
  .xp-title { font-size: 13px; font-weight: 600; }
  .xp-level { font-size: 11px; color: var(--green-n); font-weight: 700; background: rgba(0,245,160,0.1); padding: 3px 10px; border-radius: 20px; }
  .xp-track { height: 8px; background: rgba(255,255,255,0.06); border-radius: 10px; overflow: hidden; position: relative; }
  .xp-fill { height: 100%; border-radius: 10px; background: linear-gradient(90deg, var(--blue-e), var(--green-n)); position: relative; width: 72%; box-shadow: 0 0 12px rgba(0,245,160,0.3); }
  .xp-fill::after { content: ''; position: absolute; inset: 0; background: linear-gradient(90deg, transparent 70%, rgba(255,255,255,0.3)); }
  .xp-info { display: flex; justify-content: space-between; margin-top: 6px; font-size: 11px; color: var(--text-muted); }

  /* ── BADGES ── */
  .badges-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; padding: 0 22px 18px; }
  .badge-item { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 12px 8px; border-radius: 14px; background: rgba(255,255,255,0.03); border: 1px solid var(--border); cursor: pointer; transition: all .2s; }
  .badge-item:hover { background: rgba(37,99,255,0.1); border-color: rgba(37,99,255,0.3); transform: translateY(-2px); }
  .badge-icon { width: 36px; height: 36px; border-radius: 10px; display: flex; align-items: center; justify-content: center; }
  .badge-name { font-size: 10px; color: var(--text-muted); text-align: center; line-height: 1.3; }

  /* ── MINI CALENDAR ── */
  .mini-cal { padding: 0 22px 18px; }
  .cal-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; }
  .cal-month { font-size: 14px; font-weight: 700; }
  .cal-nav { display: flex; gap: 4px; }
  .cal-btn { width: 28px; height: 28px; border-radius: 8px; border: 1px solid var(--border); background: transparent; color: var(--text-muted); cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all .2s; font-size: 12px; }
  .cal-btn:hover { background: rgba(37,99,255,0.15); color: var(--ice-white); }
  .cal-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 4px; }
  .cal-day-name { font-size: 9px; color: var(--text-muted); text-align: center; padding: 4px 0; font-weight: 600; text-transform: uppercase; }
  .cal-day { width: 100%; aspect-ratio: 1; border-radius: 8px; display: flex; align-items: center; justify-content: center; font-size: 11px; cursor: pointer; transition: all .18s; color: var(--text-muted); }
  .cal-day:hover { background: rgba(37,99,255,0.15); color: var(--ice-white); }
  .cal-day.today { background: var(--blue-e); color: #fff; font-weight: 700; box-shadow: 0 0 14px var(--glow-blue); }
  .cal-day.has-event { position: relative; color: var(--ice-white); font-weight: 600; }
  .cal-day.has-event::after { content: ''; position: absolute; bottom: 3px; left: 50%; transform: translateX(-50%); width: 4px; height: 4px; border-radius: 50%; background: var(--green-n); box-shadow: 0 0 4px var(--green-n); }
  .cal-day.holiday::after { background: #ef4444; box-shadow: 0 0 4px #ef4444; }
  .cal-day.other-month { opacity: .3; }

  /* ── QUICK ACTIONS ── */
  .quick-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; padding: 0 22px 18px; }
  .quick-btn {
    padding: 14px 16px; border-radius: 14px; border: 1px solid var(--border);
    background: rgba(255,255,255,0.03); cursor: pointer; transition: all .22s;
    display: flex; align-items: center; gap: 10px; text-align: left;
    color: var(--text-main);
  }
  .quick-btn:hover { background: rgba(37,99,255,0.12); border-color: rgba(37,99,255,0.35); transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,0.2); }
  .quick-btn:hover .quick-icon { box-shadow: 0 0 14px var(--glow-blue); }
  .quick-icon { width: 36px; height: 36px; border-radius: 10px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
  .quick-text { font-size: 12px; font-weight: 600; line-height: 1.3; }
  .quick-sub  { font-size: 10px; color: var(--text-muted); margin-top: 1px; }

  /* ── MÓDULO PAGES ── */
  .module-page { padding: 4px; }
  .module-header { margin-bottom: 28px; }
  .module-title { font-family: 'Space Grotesk', sans-serif; font-size: 28px; font-weight: 800; background: linear-gradient(135deg, var(--ice-white), var(--blue-e)); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
  .module-desc { font-size: 14px; color: var(--text-muted); margin-top: 6px; }
  .btn-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 14px; margin-bottom: 28px; }
  .module-btn {
    padding: 18px 16px; border-radius: 16px;
    border: 1px solid var(--border);
    background: linear-gradient(135deg, rgba(15,25,55,0.8), rgba(10,18,40,0.8));
    cursor: pointer; transition: all .25s; display: flex; flex-direction: column; gap: 10px;
    align-items: flex-start; color: var(--text-main); text-align: left;
  }
  .module-btn:hover {
    background: linear-gradient(135deg, rgba(37,99,255,0.2), rgba(124,58,237,0.12));
    border-color: rgba(37,99,255,0.45);
    transform: translateY(-3px);
    box-shadow: 0 10px 30px rgba(0,0,0,0.25), 0 0 20px rgba(37,99,255,0.12);
  }
  .module-btn-icon { width: 42px; height: 42px; border-radius: 13px; display: flex; align-items: center; justify-content: center; }
  .module-btn-label { font-size: 13px; font-weight: 600; }
  .module-btn-desc  { font-size: 11px; color: var(--text-muted); }

  /* ── JUEGOS ── */
  .game-hero { padding: 28px; border-radius: 20px; margin-bottom: 24px; position: relative; overflow: hidden;
    background: linear-gradient(135deg, rgba(37,99,255,0.2) 0%, rgba(124,58,237,0.2) 50%, rgba(0,245,160,0.1) 100%);
    border: 1px solid rgba(37,99,255,0.25); }
  .game-hero::before { content: ''; position: absolute; top: -60px; right: -40px; width: 200px; height: 200px;
    background: radial-gradient(circle, rgba(124,58,237,0.3), transparent 70%); border-radius: 50%; }
  .game-hero-title { font-family: 'Space Grotesk', sans-serif; font-size: 22px; font-weight: 800; margin-bottom: 6px; }
  .game-hero-desc  { font-size: 13px; color: var(--text-muted); margin-bottom: 18px; }
  .game-stats { display: flex; gap: 24px; }
  .game-stat-item { text-align: center; }
  .game-stat-val   { font-family: 'Space Grotesk', sans-serif; font-size: 22px; font-weight: 800; color: var(--green-n); text-shadow: 0 0 12px rgba(0,245,160,0.5); }
  .game-stat-label { font-size: 10px; color: var(--text-muted); }

  /* LEADERBOARD */
  .leaderboard { padding: 0 22px 18px; }
  .lb-item { display: flex; align-items: center; gap: 12px; padding: 11px 14px; border-radius: 12px; margin-bottom: 8px;
    background: rgba(255,255,255,0.03); border: 1px solid var(--border); transition: all .2s; }
  .lb-item:hover { background: rgba(37,99,255,0.1); border-color: rgba(37,99,255,0.25); }
  .lb-rank { width: 24px; font-size: 12px; font-weight: 800; color: var(--text-muted); text-align: center; }
  .lb-rank.gold   { color: #f59e0b; text-shadow: 0 0 10px rgba(245,158,11,0.6); }
  .lb-rank.silver { color: var(--silver); }
  .lb-rank.bronze { color: #cd7c3f; }
  .lb-avatar { width: 34px; height: 34px; border-radius: 10px; display: flex; align-items: center; justify-content: center;
    font-weight: 700; font-size: 13px; flex-shrink: 0; }
  .lb-name  { flex: 1; font-size: 13px; font-weight: 500; }
  .lb-xp    { font-size: 12px; color: var(--green-n); font-weight: 700; }
  .lb-bar   { width: 60px; height: 4px; background: rgba(255,255,255,0.06); border-radius: 10px; overflow: hidden; }
  .lb-fill  { height: 100%; background: linear-gradient(90deg, var(--blue-e), var(--green-n)); border-radius: 10px; }

  /* ── ANALYTICS ── */
  .chart-area { padding: 18px 22px; }
  .chart-placeholder { height: 180px; border-radius: 14px; background: rgba(255,255,255,0.02); border: 1px dashed rgba(255,255,255,0.08);
    display: flex; align-items: center; justify-content: center; color: var(--text-muted); font-size: 13px; position: relative; overflow: hidden; }
  .chart-bars { display: flex; align-items: flex-end; gap: 8px; height: 140px; padding: 0 16px; width: 100%; }
  .chart-bar { flex: 1; border-radius: 6px 6px 0 0; position: relative; min-width: 0; transition: all .3s; cursor: pointer; }
  .chart-bar:hover { filter: brightness(1.2); }
  .chart-bar-label { position: absolute; bottom: -20px; left: 50%; transform: translateX(-50%); font-size: 9px; color: var(--text-muted); white-space: nowrap; }

  /* ── PILL TABS ── */
  .pill-tabs { display: flex; gap: 8px; padding: 18px 22px 0; }
  .pill-tab { padding: 6px 16px; border-radius: 20px; font-size: 12px; font-weight: 600; cursor: pointer;
    border: 1px solid var(--border); color: var(--text-muted); transition: all .2s; }
  .pill-tab:hover { color: var(--ice-white); }
  .pill-tab.active { background: var(--blue-e); color: #fff; border-color: var(--blue-e); box-shadow: 0 0 14px var(--glow-blue); }

  /* ── ACTION BTN ── */
  .action-btn {
    display: inline-flex; align-items: center; gap: 8px;
    padding: 10px 20px; border-radius: 12px; font-size: 13px; font-weight: 600;
    cursor: pointer; transition: all .22s; border: none;
  }
  .btn-primary { background: linear-gradient(135deg, var(--blue-e), var(--purple-t)); color: #fff; box-shadow: 0 4px 20px var(--glow-blue); }
  .btn-primary:hover { transform: translateY(-2px); box-shadow: 0 8px 28px var(--glow-blue); }
  .btn-ghost  { background: rgba(255,255,255,0.05); color: var(--text-muted); border: 1px solid var(--border); }
  .btn-ghost:hover  { background: rgba(37,99,255,0.12); color: var(--ice-white); border-color: rgba(37,99,255,0.3); }

  /* ── ALERT CARD ── */
  .alert-card { padding: 14px 18px; border-radius: 13px; display: flex; align-items: center; gap: 12px; margin-bottom: 10px; }
  .alert-warn { background: rgba(245,158,11,0.08); border: 1px solid rgba(245,158,11,0.2); }
  .alert-info { background: rgba(37,99,255,0.08); border: 1px solid rgba(37,99,255,0.2); }
  .alert-success { background: rgba(0,245,160,0.07); border: 1px solid rgba(0,245,160,0.2); }

  /* ── PARTICLES (CSS only) ── */
  .particles { position: fixed; inset: 0; pointer-events: none; z-index: 0; overflow: hidden; }
  .particle { position: absolute; border-radius: 50%; opacity: .12; animation: floatUp linear infinite; }
  @keyframes floatUp { 0% { transform: translateY(100vh) scale(0); opacity: 0; } 20% { opacity: .12; } 80% { opacity: .08; } 100% { transform: translateY(-20px) scale(1); opacity: 0; } }
  @keyframes pulse { 0%,100% { opacity: .5; } 50% { opacity: 1; } }
  @keyframes shimmer { 0% { background-position: -200% center; } 100% { background-position: 200% center; } }
  @keyframes spin { from { transform: rotate(0); } to { transform: rotate(360deg); } }

  /* ── RESPONSIVE ── */
  @media (max-width: 1100px) { .stats-grid { grid-template-columns: repeat(2,1fr); } }
  @media (max-width: 768px) {
    .sidebar { width: 70px; }
    .sidebar .nav-label-text, .sidebar .logo-text, .sidebar .nav-label { opacity: 0; pointer-events: none; }
    .main { margin-left: 70px; }
    .stats-grid { grid-template-columns: 1fr 1fr; }
    .grid-2, .grid-3 { grid-template-columns: 1fr; }
    .search-bar { display: none; }
  }

  /* ── REFINED VISUAL SYSTEM ── */
  body {
    background:
      radial-gradient(circle at 85% 8%, rgba(37,99,255,0.18), transparent 28%),
      radial-gradient(circle at 18% 92%, rgba(124,58,237,0.14), transparent 30%),
      linear-gradient(135deg, #07183f 0%, #0b2668 52%, #081d50 100%);
  }
  .sidebar {
    background:
      linear-gradient(180deg, rgba(7,22,58,0.98), rgba(5,15,42,0.98)),
      radial-gradient(circle at 50% 0%, rgba(37,99,255,0.16), transparent 42%);
    border-right-color: rgba(139,180,255,0.16);
    box-shadow: 12px 0 40px rgba(0,0,0,0.16);
  }
  .sidebar-logo {
    padding-top: 20px;
    min-height: 76px;
    border-bottom-color: rgba(139,180,255,0.12);
  }
  .logo-badge, .avatar-circle {
    box-shadow: 0 8px 24px rgba(37,99,255,0.28), 0 0 0 4px rgba(124,58,237,0.08);
  }
  .nav-section { padding: 18px 12px; }
  .nav-item {
    padding: 12px 13px;
    border: 1px solid transparent;
  }
  .nav-item:hover {
    background: rgba(37,99,255,0.14);
    border-color: rgba(100,160,255,0.12);
  }
  .nav-item.active {
    background: linear-gradient(110deg, rgba(37,99,255,0.28), rgba(124,58,237,0.2));
    border-color: rgba(100,160,255,0.2);
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.06), 0 8px 22px rgba(37,99,255,0.12);
  }
  .topbar {
    height: 76px;
    padding: 0 30px;
    background: rgba(7,22,58,0.78);
    border-bottom-color: rgba(139,180,255,0.14);
    box-shadow: 0 8px 30px rgba(0,0,0,0.12);
  }
  .topbar-title { letter-spacing: -0.02em; }
  .topbar-toggle, .icon-btn, .avatar-btn {
    background: rgba(255,255,255,0.045);
    border-color: rgba(139,180,255,0.17);
  }
  .content {
    padding: 30px;
    background: linear-gradient(180deg, rgba(7,24,64,0.1), rgba(7,24,64,0.22));
  }
  .glass-card {
    background: linear-gradient(145deg, rgba(18,51,125,0.68), rgba(8,28,76,0.72));
    border-color: rgba(139,180,255,0.16);
    border-radius: 20px;
    box-shadow: 0 12px 34px rgba(0,0,0,0.13), inset 0 1px 0 rgba(255,255,255,0.035);
  }
  .glass-card:hover {
    border-color: rgba(100,160,255,0.34);
    box-shadow: 0 16px 42px rgba(0,0,0,0.22), 0 0 24px rgba(37,99,255,0.1);
  }
  .sec-header { padding: 22px 24px 17px; }
  .sec-title { letter-spacing: -0.015em; }
  .sec-sub { color: #91abd0; }
  .stats-grid { gap: 18px; margin-bottom: 26px; }
  .stat-card {
    min-height: 176px;
    padding: 22px 23px;
    border-color: rgba(139,180,255,0.16);
    box-shadow: 0 12px 30px rgba(0,0,0,0.12), inset 0 1px 0 rgba(255,255,255,0.04);
  }
  .stat-card:hover { transform: translateY(-5px); }
  .stat-icon {
    width: 46px;
    height: 46px;
    border-radius: 14px;
  }
  .stat-value { letter-spacing: -0.04em; }
  .progress-wrap, .activity-list, .mini-cal, .quick-grid, .badges-grid, .leaderboard { padding-left: 24px; padding-right: 24px; }
  .progress-track { height: 8px; background: rgba(4,15,42,0.55); }
  .progress-fill { box-shadow: 0 0 12px rgba(37,99,255,0.25); }
  .activity-item { padding: 14px 0; border-bottom-color: rgba(139,180,255,0.09); }
  .act-dot { box-shadow: 0 6px 16px rgba(0,0,0,0.18); }
  .quick-btn, .badge-item, .lb-item {
    background: rgba(255,255,255,0.045);
    border-color: rgba(139,180,255,0.14);
  }
  .quick-btn:hover, .badge-item:hover, .lb-item:hover {
    background: rgba(37,99,255,0.14);
    border-color: rgba(100,160,255,0.3);
  }
  .cal-day { border-radius: 10px; }
  .cal-day.today {
    background: linear-gradient(135deg, var(--blue-e), var(--purple-t));
    box-shadow: 0 6px 18px rgba(37,99,255,0.3);
  }
  @media (max-width: 768px) {
    .topbar { padding: 0 16px; }
    .content { padding: 20px 16px; }
    .stats-grid { gap: 12px; }
    .stat-card { min-height: 150px; padding: 17px; }
    .stat-value { font-size: 27px; }
  }
`;

// ─── DATA ────────────────────────────────────────────────────────────────────
// Eventos reales del calendario — construidos desde MESES (mes actual + próximos)
// Índices: 5=Junio, 6=Julio … ordenados por proximidad
const getDateLabel = (date, today) => {
  const diffDays = Math.round((date - today) / 86400000);
  return diffDays === 0 ? "Hoy" : diffDays === 1 ? "Mañana" : diffDays < 0
    ? `Hace ${-diffDays} día${-diffDays > 1 ? "s" : ""}`
    : `En ${diffDays} días`;
};

const UPCOMING_EVENTS = (() => {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const events = [];
  MESES.forEach((mes, monthIndex) => {
    mes.notas.forEach((nota) => {
      const date = new Date(today.getFullYear(), monthIndex, nota.dia);
      if (date >= today && date <= new Date(today.getTime() + 45 * 86400000)) {
        events.push({
          title: nota.titulo,
          time: getDateLabel(date, today),
          mes: mes.nombre,
          date,
          color: "rgba(37,99,255,0.2)",
          badge: nota.tag === "reunion" ? "Reunión" : "Académico",
          badgeColor: nota.tag === "reunion" ? "#2563ff" : "#00f5a0",
          responsable: nota.responsables || null,
        });
      }
    });
  });
  COLOMBIA_HOLIDAYS_2026.forEach((holiday) => {
    const date = new Date(`${holiday.date}T00:00:00`);
    if (date >= today && date <= new Date(today.getTime() + 45 * 86400000)) {
      events.push({
        title: holiday.name,
        time: getDateLabel(date, today),
        mes: date.toLocaleDateString("es-CO", { month: "long" }),
        date,
        color: "rgba(239,68,68,0.2)",
        badge: "Festivo",
        badgeColor: "#ef4444",
      });
    }
  });
  return events.sort((a, b) => a.date - b.date).slice(0, 4);
})();

