function StatsPage() {
  const BAR_COLORS = [
    "rgba(37,99,255,0.6)","rgba(37,99,255,0.7)","rgba(124,58,237,0.65)",
    "rgba(37,99,255,0.8)","rgba(37,99,255,0.75)","linear-gradient(180deg,#00f5a0,#2563ff)"
  ];
  const [kpis, setKpis] = useState([
    { v:"89%", l:"Promedio institucional", c:"#2563ff" },
    { v:"94%", l:"Asistencia promedio",    c:"#00f5a0" },
    { v:"4.7", l:"Promedio académico",     c:"#7c3aed" },
    { v:"12",  l:"Estudiantes en riesgo",  c:"#ef4444" },
  ]);
  const [progress, setProgress] = useState([
    { name:"Matemáticas — Grado 8°",  pct:82, color:"linear-gradient(90deg,#2563ff,#7c3aed)" },
    { name:"Lenguaje — Grado 7°",     pct:67, color:"linear-gradient(90deg,#00f5a0,#2563ff)" },
    { name:"Ciencias — Grado 9°",     pct:91, color:"linear-gradient(90deg,#7c3aed,#f59e0b)" },
    { name:"Sociales — Grado 6°",     pct:55, color:"linear-gradient(90deg,#f59e0b,#ef4444)" },
  ]);
  const [board, setBoard] = useState([
    { name:"Valentina Ruiz",  xp:3840, pct:96, color:"#2563ff", init:"VR" },
    { name:"Santiago Mora",   xp:3610, pct:90, color:"#7c3aed", init:"SM" },
    { name:"Isabella Torres", xp:3420, pct:86, color:"#00f5a0", init:"IT" },
    { name:"Mateo Hernández", xp:3100, pct:78, color:"#f59e0b", init:"MH" },
    { name:"Camila Jiménez",  xp:2890, pct:72, color:"#ef4444", init:"CJ" },
  ]);
  const [bars, setBars] = useState([
    {label:"Feb",h:45},{label:"Mar",h:68},{label:"Abr",h:52},
    {label:"May",h:80},{label:"Jun",h:72},{label:"Jul",h:91},
  ]);
  const [uploading, setUploading] = useState(false);
  const [uploadMsg, setUploadMsg] = useState(null);
  const [fileName,  setFileName]  = useState(null);
  const fileRef = useRef(null);

  const handleFile = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setUploading(true); setFileName(file.name); setUploadMsg(null);
    e.target.value = "";
    try {
      const isPDF = file.type === "application/pdf";
      const isImg = file.type.startsWith("image/");
      const b64 = await new Promise((res,rej)=>{ const r=new FileReader(); r.onload=()=>res(r.result.split(",")[1]); r.onerror=rej; r.readAsDataURL(file); });
      const txt = (!isPDF&&!isImg) ? await new Promise((res,rej)=>{ const r=new FileReader(); r.onload=()=>res(r.result); r.onerror=rej; r.readAsText(file); }).catch(()=>null) : null;

      let content = [];
      if (isImg)       content.push({type:"image",    source:{type:"base64",media_type:file.type,data:b64}});
      else if (isPDF)  content.push({type:"document", source:{type:"base64",media_type:"application/pdf",data:b64}});
      else if (txt)    content.push({type:"text",     text:`Archivo: ${file.name}\n\n${txt.slice(0,10000)}`});

      content.push({type:"text", text:`Analiza este documento estadístico académico de la I.E. La Amistad, San José de Pare.
Extrae los datos y responde ÚNICAMENTE con este JSON válido (sin texto extra, sin backticks):
{"kpis":[{"v":"XX%","l":"Promedio institucional","c":"#2563ff"},{"v":"XX%","l":"Asistencia promedio","c":"#00f5a0"},{"v":"X.X","l":"Promedio académico","c":"#7c3aed"},{"v":"XX","l":"Estudiantes en riesgo","c":"#ef4444"}],"progress":[{"name":"Asignatura — Grado","pct":82,"color":"linear-gradient(90deg,#2563ff,#7c3aed)"},{"name":"Asignatura — Grado","pct":67,"color":"linear-gradient(90deg,#00f5a0,#2563ff)"},{"name":"Asignatura — Grado","pct":91,"color":"linear-gradient(90deg,#7c3aed,#f59e0b)"},{"name":"Asignatura — Grado","pct":55,"color":"linear-gradient(90deg,#f59e0b,#ef4444)"}],"board":[{"name":"Nombre Apellido","xp":3840,"pct":96,"color":"#2563ff","init":"NA"},{"name":"Nombre Apellido","xp":3610,"pct":90,"color":"#7c3aed","init":"SM"},{"name":"Nombre Apellido","xp":3420,"pct":86,"color":"#00f5a0","init":"IT"},{"name":"Nombre Apellido","xp":3100,"pct":78,"color":"#f59e0b","init":"MH"},{"name":"Nombre Apellido","xp":2890,"pct":72,"color":"#ef4444","init":"CJ"}],"bars":[{"label":"Feb","h":45},{"label":"Mar","h":68},{"label":"Abr","h":52},{"label":"May","h":80},{"label":"Jun","h":72},{"label":"Jul","h":91}]}
Usa datos reales del documento. Si no hay dato usa el ejemplo. Solo JSON.`});

      const res = await fetch("https://api.anthropic.com/v1/messages",{
        method:"POST", headers:{"Content-Type":"application/json"},
        body:JSON.stringify({model:"claude-sonnet-4-6",max_tokens:1200,messages:[{role:"user",content}]}),
      });
      if (!res.ok) throw new Error(`API ${res.status}`);
      const data = await res.json();
      const raw  = data.content.map(b=>b.text||"").join("").replace(/```json|```/g,"").trim();
      const parsed = JSON.parse(raw);
      if (parsed.kpis)     setKpis(parsed.kpis);
      if (parsed.progress) setProgress(parsed.progress);
      if (parsed.board)    setBoard(parsed.board);
      if (parsed.bars)     setBars(parsed.bars);
      setUploadMsg({ok:true, text:`✅ Datos actualizados desde "${file.name}"`});
    } catch(err) {
      setUploadMsg({ok:false, text:`❌ ${err.message}`});
    } finally { setUploading(false); }
  };

  return (
    <div className="module-page">
      <div className="module-header">
        <div className="module-title">📊 Estadísticas</div>
        <div className="module-desc">
          Rendimiento académico · Período 2 · 2026
          {fileName && <span style={{marginLeft:10,fontSize:12,color:"var(--green-n)"}}>· {fileName}</span>}
        </div>
      </div>

      {/* KPI CARDS */}
      <div className="stats-grid">
        {kpis.map((s,i)=>(
          <div key={i} className="stat-card">
            <div className="stat-value" style={{color:s.c,textShadow:`0 0 20px ${s.c}44`,transition:"all .5s"}}>{s.v}</div>
            <div className="stat-label">{s.l}</div>
          </div>
        ))}
      </div>

      {/* CHARTS */}
      <div className="grid-2">
        <div className="glass-card">
          <div className="sec-header"><div className="sec-title">Rendimiento mensual</div></div>
          <div style={{padding:"0 22px 24px"}}>
            <div style={{display:"flex",alignItems:"flex-end",gap:8,height:150,paddingBottom:24}}>
              {bars.map((b,i)=>(
                <div key={i} style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",gap:4}}>
                  <div style={{fontSize:10,color:"var(--text-muted)",fontWeight:600}}>{b.h}%</div>
                  <div style={{width:"100%",height:`${b.h}%`,background:BAR_COLORS[i]||BAR_COLORS[0],borderRadius:"6px 6px 0 0",
                    boxShadow:i===bars.length-1?"0 0 16px rgba(0,245,160,0.3)":"none",transition:"height .6s ease"}}/>
                  <div style={{fontSize:10,color:"var(--text-muted)"}}>{b.label}</div>
                </div>
              ))}
            </div>
          </div>
        </div>
        <div className="glass-card">
          <div className="sec-header"><div className="sec-title">Por asignatura</div></div>
          <div className="progress-wrap" style={{paddingTop:8}}>
            {progress.map((p,i)=>(
              <div key={i} className="progress-item">
                <div className="progress-meta">
                  <span className="progress-name">{p.name}</span>
                  <span className="progress-pct">{p.pct}%</span>
                </div>
                <div className="progress-track">
                  <div className="progress-fill" style={{width:`${p.pct}%`,background:p.color,transition:"width .7s ease"}}/>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* LEADERBOARD */}
      <div className="glass-card" style={{marginBottom:20}}>
        <div className="sec-header">
          <div className="sec-title">Leaderboard académico</div>
          <span className="sec-action">Ver reporte completo</span>
        </div>
        <div className="leaderboard">
          {board.map((s,i)=>(
            <div key={i} className="lb-item">
              <div className={`lb-rank ${i===0?"gold":i===1?"silver":i===2?"bronze":""}`}>{i+1}</div>
              <div className="lb-avatar" style={{background:`${s.color}22`,color:s.color,border:`1px solid ${s.color}40`}}>{s.init}</div>
              <div className="lb-name">{s.name}</div>
              <div className="lb-bar"><div className="lb-fill" style={{width:`${s.pct}%`,transition:"width .7s ease"}}/></div>
              <div className="lb-xp">{s.xp.toLocaleString()} XP</div>
            </div>
          ))}
        </div>
      </div>

      {/* UPLOAD BUTTON */}
      <div className="glass-card" style={{padding:"20px 24px"}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",flexWrap:"wrap",gap:12}}>
          <div>
            <div style={{fontFamily:"'Space Grotesk',sans-serif",fontWeight:700,fontSize:14,marginBottom:3}}>
              📂 Actualizar estadísticas con datos reales
            </div>
            <div style={{fontSize:12,color:"var(--text-muted)"}}>
              Sube un archivo (PDF, Excel, CSV, imagen) — la IA extrae los datos y actualiza todo automáticamente
            </div>
          </div>
          <div style={{display:"flex",alignItems:"center",gap:12,flexWrap:"wrap"}}>
            {uploadMsg && (
              <span style={{fontSize:12,fontWeight:600,color:uploadMsg.ok?"var(--green-n)":"#ef4444"}}>
                {uploadMsg.text}
              </span>
            )}
            <button
              className="action-btn btn-primary"
              onClick={()=>fileRef.current?.click()}
              disabled={uploading}
              style={{opacity:uploading?0.6:1,cursor:uploading?"wait":"pointer",display:"flex",alignItems:"center",gap:8}}
            >
              {uploading
                ? <><div style={{width:14,height:14,borderRadius:"50%",border:"2px solid rgba(255,255,255,0.3)",borderTopColor:"#fff",animation:"spin .7s linear infinite",flexShrink:0}}/> Analizando…</>
                : <><Icon d={icons.download} size={15}/> Subir datos</>
              }
            </button>
            <input ref={fileRef} type="file"
              accept=".pdf,.xlsx,.xls,.csv,.png,.jpg,.jpeg,.txt,.docx"
              onChange={handleFile} style={{display:"none"}}
            />
          </div>
        </div>
      </div>
    </div>
  );
}

