// ─── PARTICLES ────────────────────────────────────────────────────────────────
function Particles() {
  const parts = Array.from({ length: 12 }, (_, i) => ({
    left: `${(i * 8.3) % 100}%`,
    width: `${3 + (i % 3) * 2}px`,
    height: `${3 + (i % 3) * 2}px`,
    duration: `${12 + i * 2}s`,
    delay: `${i * 1.5}s`,
    color: i % 3 === 0 ? "#2563ff" : i % 3 === 1 ? "#7c3aed" : "#00f5a0",
  }));
  return (
    <div className="particles">
      {parts.map((p, i) => (
        <div key={i} className="particle" style={{
          left: p.left, bottom: -10, width: p.width, height: p.height,
          background: p.color, boxShadow: `0 0 8px ${p.color}`,
          animationDuration: p.duration, animationDelay: p.delay,
        }} />
      ))}
    </div>
  );
}

